                macapk_diag_safe_read((const void*)(sp + 0x550), &vmstate, 8);
                if (vmstate) macapk_diag_safe_read((const void*)(vmstate + 8), &desc, 8);
                if (desc) { macapk_diag_safe_read((const void*)(desc + 0xc), &cursor2, 4);
                            macapk_diag_safe_read((const void*)(desc + 8),   &key,     4); }
