                    // non-buffer input; never-changes => the initial decrypt diverged at 0x2080a. OFF unless HUBTRAJ.
                    {
                        uint64_t bb = 0; if (desc) macapk_diag_safe_read((const void*)desc, &bb, 8);
                        uint32_t v2080a = 0xdeadbeefu;
                        if (bb) macapk_diag_safe_read((const void*)(bb + 0x2080au), &v2080a, 4);
                        static uint32_t s_last2080a = 0x12345678u;
                        static int s_bfd2080a = ::open("/tmp/pairip_buf2080a.log", O_WRONLY | O_CREAT | O_TRUNC, 0644);
                        if (v2080a != s_last2080a) {
                            if (s_bfd2080a >= 0) {
                                char bb2[176]; int bn = std::snprintf(bb2, sizeof bb2,
                                    "pass=%ld cursor2=%#x buf[0x2080a:+4]: %#010x -> %#010x bufbase=%#llx\n",
                                    n, cursor2, s_last2080a, v2080a, (unsigned long long)bb);
                                if (bn > 0) { ssize_t w2 = ::write(s_bfd2080a, bb2, (size_t)bn); (void)w2; }
                            }
                            s_last2080a = v2080a;
                        }
                    }
                    // cont.264 (2026-10-13): co-arm STOREWATCH's PG page-guard from HERE. The standalone
                    // arming (~L11400) is only reached WITHOUT HUBTRAJ, but without HUBTRAJ nothing emulates
                    // the hub `mov w8,w10` so the run aborts after the first hub pass. Here the hub IS emulated
