                    const char* p=std::strchr(fd_env,':');
                    if(p){ fd_delta=(uint32_t)std::strtoul(p+1,nullptr,16);
                        const char* q=std::strchr(p+1,':');
                        if(q){ fd_lo=std::strtol(q+1,nullptr,10);
                            const char* r=std::strchr(q+1,':'); if(r) fd_hi=std::strtol(r+1,nullptr,10); } }
