                    if (g_ss_fd>=0){ char hb[96]; int hn=std::snprintf(hb,sizeof hb,
                        "=== begin outer o=%ld w8=%08x pc=%#x ===\n", o, w8, opc);
                        if(hn>0){ssize_t w=::write(g_ss_fd,hb,hn);(void)w;} }
