                char b[900]; int n2 = std::snprintf(b, sizeof b, "[outerdump] o=%ld w8=%08x pc=%#x sp=%llx",
                    o, w8, opc, (unsigned long long)uc->uc_mcontext->__ss.__sp);
                for (int r=0;r<29;r++) n2+=std::snprintf(b+n2,sizeof b-n2," x%d=%llx",r,(unsigned long long)X[r]);
