// CallStaticObjectMethodV (vtable slot 115, offset 0x1cc). Same as
// the varargs variant except r3 is a guest pointer to the va_list,
// not the first variadic value. cocos2d-x v2's JniHelper builds a
// va_list and goes through this slot rather than the varargs slot,
// so all string-pref reads (CCUserDefault::getStringForKey etc.)
// hit here.
uint32_t CallStaticObjectMethodV(uint32_t env_h, uint32_t cls_h,
                                  uint32_t mid_h, uint32_t va_list_ptr) {
    JNIEnv* e = env_for(env_h);
    jclass  c = obj_for<jclass>(cls_h);
    jmethodID m = reinterpret_cast<jmethodID>(
                       __macapk_jni_resolve_handle(mid_h));
    const JniMethodMeta* meta = lookup_method_meta(mid_h);
    log_variadic_call("CallStaticObjectMethodV", mid_h, meta);
    if (!e || !c || !m) return 0;
    std::vector<char> args;
    if (meta) args = parse_jni_arg_types(meta->sig);
    jvalue jv[16];
    if (!args.empty()) {
        pack_arm32_valist_into_jvalues(va_list_ptr, args, jv,
                                       int(sizeof(jv) / sizeof(jv[0])));
    }
    jobject r = e->CallStaticObjectMethodA(c, m, args.empty() ? nullptr : jv);
    if (e->ExceptionCheck()) {
        e->ExceptionDescribe();
        e->ExceptionClear();
        return 0;
    }
    if (!r) return 0;
    if (jni_handle_trace()) {
        // GetObjectRefType is safe (no oop deref): 1=Local, 2=Global, 0=Invalid.
        std::fprintf(stderr,
            "[jni-htrace] CallStaticObjectMethodV(%s) raw r=%p refType=%d\n",
            meta ? meta->name.c_str() : "?", reinterpret_cast<void*>(r),
            (int)e->GetObjectRefType(r));
    }
    jobject g = e->NewGlobalRef(r);
    e->DeleteLocalRef(r);
    if (!g) return 0;
    uint32_t h = __macapk_jni_make_handle(g);
    if (jni_handle_trace())
        std::fprintf(stderr,
            "[jni-htrace] CallStaticObjectMethodV(%s) -> handle=0x%x g=%p gRefType=%d\n",
            meta ? meta->name.c_str() : "?", h, reinterpret_cast<void*>(g),
            (int)e->GetObjectRefType(g));
    if (strcheck_enabled() && meta)
        strcheck_probe_string(e, g, meta->name.c_str(), meta->sig.c_str());
    return h;
}

