// Float return: bit-cast, NOT a numeric conversion -- the guest's next
// instruction (its own compiled `vmov s0, r0`-style move, since armeabi-v7a
// is softfp) expects the IEEE-754 bit pattern in r0, not a rounded integer.
uint32_t CallStaticFloatMethod(uint32_t env_h, uint32_t cls_h,
                               uint32_t mid_h, uint32_t arg0) {
    JNIEnv* e = env_for(env_h);
    jclass  c = obj_for<jclass>(cls_h);
    jmethodID m = reinterpret_cast<jmethodID>(
                       __macapk_jni_resolve_handle(mid_h));
    const JniMethodMeta* meta = lookup_method_meta(mid_h);
    log_variadic_call("CallStaticFloatMethod", mid_h, meta);
    if (!e || !c || !m) return 0;
    std::vector<char> args;
    if (meta) args = parse_jni_arg_types(meta->sig);
    jvalue jv[16];
    if (!args.empty()) {
        pack_arm32_inline_args_into_jvalues(
            arg0, macapk_jni::g_jni_dispatch_sp, args, jv,
            static_cast<int>(std::size(jv)));
    }
    jfloat r = e->CallStaticFloatMethodA(c, m, args.empty() ? nullptr : jv);
    if (e->ExceptionCheck()) {
        e->ExceptionDescribe();
        e->ExceptionClear();
        return 0;
    }
    uint32_t bits;
    std::memcpy(&bits, &r, sizeof(bits));
    return bits;
}

