// =================================================================
// NewObject / V / A -- constructor invocation. (LANE M 2026-07-28.)
// =================================================================
//
// Same shape as CallStaticObjectMethod{,V,A} (object-returning, needs the
// local->global ref promotion so the handle survives JNI-frame crossing),
// but calls NewObjectA instead and the second arg is a jclass (like static)
// rather than a jobject (like instance) -- constructors are always invoked
// against the class being constructed, matching Layer B's own
// MACAPK_BIONIC_JNI_BRIDGE(NewObject, jobject, jclass, true, false).
uint32_t NewObject(uint32_t env_h, uint32_t cls_h,
                   uint32_t mid_h, uint32_t arg0) {
    JNIEnv* e = env_for(env_h);
    jclass  c = obj_for<jclass>(cls_h);
    jmethodID m = reinterpret_cast<jmethodID>(
                       __macapk_jni_resolve_handle(mid_h));
    const JniMethodMeta* meta = lookup_method_meta(mid_h);
    log_variadic_call("NewObject", mid_h, meta);
    if (!e || !c || !m) return 0;
    std::vector<char> args;
    if (meta) args = parse_jni_arg_types(meta->sig);
    jvalue jv[16];
    if (!args.empty()) {
        pack_arm32_inline_args_into_jvalues(
            arg0, macapk_jni::g_jni_dispatch_sp, args, jv,
            static_cast<int>(std::size(jv)));
    }
    jobject r = e->NewObjectA(c, m, args.empty() ? nullptr : jv);
    if (e->ExceptionCheck()) {
        e->ExceptionDescribe();
        e->ExceptionClear();
        return 0;
    }
    if (!r) return 0;
    jobject g = e->NewGlobalRef(r);
    e->DeleteLocalRef(r);
    if (!g) return 0;
    return __macapk_jni_make_handle(g);
}

