// MACAPK_PAIRIP_FAKE_JNIENV: our synthetic "libart.so" region (JNI trampolines at
// genuine ART's per-slot offsets). Published by macapk_install_fake_art_jnienv so
// this shim reports it to pairip's dl_iterate_phdr with a REAL PT_LOAD covering it.
static std::atomic<uintptr_t> g_fake_libart_base{0};
static std::atomic<uintptr_t> g_fake_libart_size{0};
// Exposed so arm64_native's /proc/self/maps writer can name our fake-libart
// region "libart.so" -- pairip locates libart via /proc/self/maps (measured:
// openat "/proc/self/maps"), NOT dl_iterate_phdr, so the region must appear
// there for the JNIEnv-fp-in-libart verification to resolve against it.
extern "C" uintptr_t __macapk_pairip_fake_libart(uintptr_t* out_size) {
    if (out_size) *out_size = g_fake_libart_size.load();
    return g_fake_libart_base.load();
}

// ---------------------------------------------------------------------------
// NDK system-font API (android/system_fonts.h + android/font.h). pairip 52.3's
// anti-tamper VM enumerates the system fonts via ASystemFontIterator/AFont and
// FOLDS each font's path+weight+italic+variation-axes (pass 16645; see
// docs/pairip-523-crack-state cont.301/302). A real device returns the AOSP system
// font set (366 objects on API-34); Mac.apk had NO native impl, so the iterator
// returned empty and the VM's font fold diverged. These shims return the faithful
// AOSP-API-34 table (pairip_system_fonts.h, generated by debug/gen_system_fonts.py
// from a device ASystemFontIterator capture) -- a platform-stable surface, like
// AOSP source, so ALL pairip apps see the real system fonts.
// ABI pinned from the NDK headers (API 29+):
//   ASystemFontIterator* ASystemFontIterator_open(void);
//   AFont* ASystemFontIterator_next(ASystemFontIterator*);   // nullptr at end
//   void ASystemFontIterator_close(ASystemFontIterator*);
//   void AFont_close(AFont*);
//   const char* AFont_getFontFilePath(const AFont*);
//   uint16_t AFont_getWeight(const AFont*);   bool AFont_isItalic(const AFont*);
//   const char* AFont_getLocales(const AFont*);   // may be nullptr
//   size_t AFont_getCollectionIndex(const AFont*);
//   size_t AFont_getAxisCount(const AFont*);
//   uint32_t AFont_getAxisTag(const AFont*, uint32_t);
//   float AFont_getAxisValue(const AFont*, uint32_t);
// The AFont* handed back is a pointer to a static table entry, so AFont_close is a
// no-op (never free it); the iterator is a tiny heap cursor.
#include "pairip_system_fonts.h"
namespace { struct MacApkFontIter { int idx; }; }
static std::atomic<long> g_afont_open_calls{0};
static std::atomic<long> g_afont_next_calls{0};
// Gated OFF by default (MACAPK_AFONT=1 to enable). pairip 52.3 does NOT call the NDK AFont API
// (measured cont.303: AFONT_TRACE empty over a full run; no /system/fonts opens) -- so this is NOT
// the pass-16645 fix, and returning 366 fonts with /system/fonts paths that do not exist as files
// could mislead a real app that enumerates then opens them. Kept, gated, because it is a correct
// faithful NDK surface and the pass-16645 carrier IS font data (ital/wdth/wght+enGB); enable it for
// testing once pairip's real font-read path is implemented. Default (off) == the prior panic-stub
// behaviour (open returns null -> empty iterator).
static bool macapk_afont_on() {
    static const bool on = (std::getenv("MACAPK_AFONT") != nullptr);
    return on;
}
extern "C" void* __macapk_arm64_ASystemFontIterator_open(void) {
    if (!macapk_afont_on()) return nullptr;
    if (g_afont_open_calls.fetch_add(1) == 0 && std::getenv("MACAPK_AFONT_TRACE"))
        { std::fprintf(stderr, "[afont] ASystemFontIterator_open called (n=%d fonts)\n", g_macapk_sys_fonts_n); std::fflush(stderr); }
    MacApkFontIter* it = (MacApkFontIter*)std::malloc(sizeof(MacApkFontIter));
    if (it) it->idx = 0;
    return it;
}
extern "C" const void* __macapk_arm64_ASystemFontIterator_next(void* iter) {
    MacApkFontIter* it = (MacApkFontIter*)iter;
    long nc = g_afont_next_calls.fetch_add(1);
    if ((nc == 0 || nc == g_macapk_sys_fonts_n) && std::getenv("MACAPK_AFONT_TRACE"))
        { std::fprintf(stderr, "[afont] ASystemFontIterator_next call #%ld (idx=%d)\n", nc, it?it->idx:-1); std::fflush(stderr); }
    if (!it || it->idx >= g_macapk_sys_fonts_n) return nullptr;
    return &g_macapk_sys_fonts[it->idx++];
}
extern "C" void __macapk_arm64_ASystemFontIterator_close(void* iter) { std::free(iter); }
extern "C" void __macapk_arm64_AFont_close(void* /*font*/) { /* static table ptr; no-op */ }
extern "C" const char* __macapk_arm64_AFont_getFontFilePath(const void* font) {
    return font ? ((const MacApkSysFont*)font)->path : nullptr;
}
extern "C" uint16_t __macapk_arm64_AFont_getWeight(const void* font) {
    return font ? ((const MacApkSysFont*)font)->weight : (uint16_t)400;
}
extern "C" bool __macapk_arm64_AFont_isItalic(const void* font) {
    return font ? ((const MacApkSysFont*)font)->italic != 0 : false;
}
extern "C" const char* __macapk_arm64_AFont_getLocales(const void* font) {
    return font ? ((const MacApkSysFont*)font)->locales : nullptr;
}
extern "C" size_t __macapk_arm64_AFont_getCollectionIndex(const void* font) {
    return font ? ((const MacApkSysFont*)font)->collectionIndex : 0;
}
extern "C" size_t __macapk_arm64_AFont_getAxisCount(const void* font) {
    return font ? ((const MacApkSysFont*)font)->naxes : 0;
}
extern "C" uint32_t __macapk_arm64_AFont_getAxisTag(const void* font, uint32_t axisIndex) {
    const MacApkSysFont* f = (const MacApkSysFont*)font;
    if (!f || axisIndex >= f->naxes) return 0;
    return f->axes[axisIndex].tag;
}
extern "C" float __macapk_arm64_AFont_getAxisValue(const void* font, uint32_t axisIndex) {
    const MacApkSysFont* f = (const MacApkSysFont*)font;
    if (!f || axisIndex >= f->naxes) return 0.0f;
    return f->axes[axisIndex].value;
}

extern "C" int __macapk_arm64_dl_iterate_phdr(
    int (*callback)(void*, size_t, void*), void* data) {
    if (!callback) return 0;
    macapk_dlpi_forward_ctx ctx{callback, data, 0};
    // Report OUR faithful-ART-offset trampoline region as libart.so (with a real
    // PT_LOAD covering it) so pairip's address-in-module / offset-within-libart
    // verification resolves our JNIEnv fps to their genuine-ART relative offsets.
    // MACAPK_PAIRIP_FAKE_MODULES makes maps report the full 1253-line device set
    // (with libart rebased onto the JNIEnv-fake region). To keep dl_iterate_phdr
    // COHERENT with maps, emit that same set here (it includes libart), instead of
    // the lone fake-libart entry below. Otherwise (JNIEnv-only run) emit just libart.
    const bool s_fake_mods = g_macapk_pairip_fake_modules;  // cont.187: constructor-settled, not lazy getenv
    if (s_fake_mods) {
        if (ctx.result == 0)
            __macapk_pairip_iterate_fake_modules(&macapk_dlpi_forward_one, &ctx);
    } else if (uintptr_t flb = g_fake_libart_base.load()) {
        static uint64_t s_lphdr[7] = {0};
        uint32_t* lp = reinterpret_cast<uint32_t*>(&s_lphdr[0]);
        lp[0] = 1;                                   // p_type = PT_LOAD
        lp[1] = 5;                                   // p_flags = R+X
        s_lphdr[2] = 0;                              // p_vaddr = 0 (base is flb)
        s_lphdr[5] = g_fake_libart_size.load();      // p_memsz
        if (ctx.result == 0)
            macapk_dlpi_forward_one(reinterpret_cast<void*>(flb), s_lphdr, 1,
                                    "/apex/com.android.art/lib64/libart.so", &ctx);
    }
    static const bool s_phdr_dev   = std::getenv("MACAPK_TEST_PHDR_DEVICE") != nullptr;
    static const bool s_phdr_trace = std::getenv("MACAPK_PHDR_TRACE") != nullptr;
    // DIAGNOSTIC (MACAPK_PHDR_FAKE_LIBART, default OFF): report ONE "libart.so"
    // module with a REAL PT_LOAD phdr covering ALL of userspace, so pairip's
    // address-in-module check (callback iterates PT_LOAD, tests target in
    // [p_vaddr+base, +p_memsz)) says every JNIEnv fp "is in libart". Tests the
    // hypothesis that pairip's JNIEnv verification is "do the fps live in a
    // module named libart" (which the phnum=0 MACAPK_TEST_PHDR_DEVICE could not
    // satisfy). If OUR +0x440c4 MOVES, that IS the check -> the honest fix is to
    // present a faithful libart whose range covers our JNI trampolines. Presenting
    // the real Android module view is the product thesis (owner 2026-09-09), not a
    // forge; the real anti-debug is untouched.
    static const bool s_fake_libart = std::getenv("MACAPK_PHDR_FAKE_LIBART") != nullptr;
    if (s_fake_libart && ctx.result == 0) {
        // Elf64_Phdr: p_type@0, p_flags@4, p_offset@8, p_vaddr@0x10, p_paddr@0x18,
        // p_filesz@0x20, p_memsz@0x28, p_align@0x30 (size 0x38).
        static uint64_t s_phdr[7] = {0};   // 56 bytes
        uint32_t* pt = reinterpret_cast<uint32_t*>(&s_phdr[0]);
        pt[0] = 1;                          // p_type = PT_LOAD
        pt[1] = 5;                          // p_flags = R+X
        s_phdr[2] = 0;                      // p_vaddr = 0  (base is 0 below)
        s_phdr[5] = 0x0000800000000000ull;  // p_memsz = all of userspace
        macapk_dlpi_forward_one(reinterpret_cast<void*>(0), s_phdr, 1,
                                "/apex/com.android.art/lib64/libart.so", &ctx);
    }
    int emitted = 0;
    if (s_phdr_dev) {
        // Device order: app_process64 + linker + system libs FIRST, then app libs.
        uintptr_t dummy = 0x700000000000ull;
        for (const char* nm : kMacapkAndroidSysLibs) {
            if (ctx.result != 0) break;
            macapk_dlpi_forward_one(reinterpret_cast<void*>(dummy), nullptr, 0, nm, &ctx);
            dummy += 0x200000;
            ++emitted;
        }
    }
    if (ctx.result == 0)
        __macapk_arm64_native_iterate_phdr(&macapk_dlpi_forward_one, &ctx);
    if (s_phdr_trace) {
        static std::atomic<long> s_n{0};
        long n = s_n.fetch_add(1);
        std::fprintf(stderr, "[phdr-iter] call #%ld: %d synthetic + guest ELFs, result=%d\n",
                     n, emitted, ctx.result);
        std::fflush(stderr);
    }
    return ctx.result;
}

// clock_gettime(clockid_t clock_id, struct timespec* ts).
//
// Bionic and macOS use DIFFERENT integer values for the clock_id
// enum. Without remapping, passing libSystem's clock_gettime a Bionic
// clock_id silently returns EINVAL and the timespec stays
// uninitialized -- engines that read the resulting tv_sec/tv_nsec see
// garbage. FMOD's AudioDevice::init was hitting this and reading a
// completely bogus per-tick delta, which propagated into the audio
// buffer-size negotiation and produced a multi-hundred-MB "actual
// buffer size" that then misaligned every subsequent malloc into the
// same arena.
//
//   Bionic: REALTIME=0, MONOTONIC=1, PROC_CPU=2, THREAD_CPU=3,
//           MONOTONIC_RAW=4, REALTIME_COARSE=5, MONOTONIC_COARSE=6,
//           BOOTTIME=7
//   macOS:  REALTIME=0, MONOTONIC_RAW=4, MONOTONIC_RAW_APPROX=5,
//           MONOTONIC=6, UPTIME_RAW=8, UPTIME_RAW_APPROX=9,
//           PROC_CPUTIME=12, THREAD_CPUTIME=16
//
// The mapping below resolves each Bionic id to its closest macOS
// equivalent and falls back to MONOTONIC for unknown ids (rather
// than EINVAL, which would re-introduce the original bug).
// ALWAYS ON for Stage-6 guests, decided once for the process lifetime
// (v1.0.569). It used to default-on only once libunity loaded
// (g_unity_present, latched during libunity symbol RESOLUTION), which let the
// guest's monotonic epoch FLIP mid-boot: any guest code sampling
// clock_gettime(CLOCK_MONOTONIC family) before the latch -- earlier .so
// init_arrays, engine clock-init call_onces -- captured the UNREBASED macOS
// uptime (~8.6e14 ns on a days-up host), while every later sample is
// process-relative (~1e9 ns); a "start time" captured pre-flip then poisons
// every later "now - start" subtraction by ~the host uptime. A clock's epoch
// must never change mid-process, and Android's CLOCK_MONOTONIC/BOOTTIME are
// device-boot-relative (small) for EVERY app, so rebase from the very first
// guest clock call, unconditionally. (Note: the Subway Surfers "gameplay 2x
// fast" poison measured 2026-07-03 turned out to be a DIFFERENT mix -- Java
// System.nanoTime() via JNI vs the rebased guest clock, see the
// swappy_present_tick offset fix -- but the mid-boot flip is the same hazard
// class and is closed by this change. RE:
// docs/unity-swappy-present-time-2x-and-clock-epoch-flip_2026-07-03.md.)
extern std::atomic<bool> g_unity_present;
extern std::atomic<bool> g_unity_present;   // defined ~L11167 (set on libunity load)
static bool clock_rebase_enabled() {
    // ⚠ COUPLING NOTE (2026-09-27, for whoever retires this rebase). Android has ONE
    // monotonic clock: System.nanoTime() == CLOCK_MONOTONIC == Choreographer frameTimeNanos.
    // Unity mixes them: Subway (2022.3) samples System.nanoTime() through JNI at its
    // choreographer enable (libunity 0x717864), Crossy (Unity 6000.3, libunity md5 03f78e94)
    // samples clock_gettime(CLOCK_MONOTONIC) there (0x898d58 `mov w0,#1; bl clock_gettime`,
    // then curTs = prevTs = that value, offset = GTSS - it*1e-9), and BOTH then store
    // frameTimeNanos per vsync (0x71a488 / 0x898c7c) and read presentTime =
    // curTs*1e-9 + offset (+ period*framesAdvanced). Since MACAPK_CHOREO_NANOTIME_BASE
    // (default ON) the Java frame times are System.nanoTime(), so this rebase makes the
    // Crossy family's two terms disagree by about the host uptime (Time.unscaledTime ~
    // uptime seconds, the v1.0.219 residual), while the Subway family is now coherent.
    // Only a guest CLOCK_MONOTONIC equal to System.nanoTime() satisfies both, and that
    // collides with the v1.0.212 float32 measurement this rebase answers. RESOLVED below
    // by MACAPK_GUEST_CLOCK_NANOTIME (default ON): the rebase this function decides now
    // fires only under =0 / MACAPK_CLOCK_REBASE=1, never in the default arm.
    // docs/unity-choreographer-vsync-nanotime-contract_2026-09-27.md section 4.
    //
    // v1.0.623: gate the MONOTONIC-family rebase (below) on libunity presence, which
    // is what it was ALWAYS meant to do (the rebase-site comment says "Gated on
    // libunity so cocos/other guests are untouched"), but the code had been env-only
    // default-ON for EVERY Stage-6 guest. The rebase exists SOLELY for Unity's float32
    // per-frame unscaled-delta precision. Applying it to a NON-Unity guest is actively
    // HARMFUL: it puts the guest's native CLOCK_MONOTONIC on a process-relative epoch
    // (~1 s) that MISMATCHES the host-epoch (~host-uptime) time values the guest mixes
    // into its scheduler's delayed-task deadlines. On MCPE this strands the
    // "Localization" TaskGroup's dependency task "never due" by ~host-uptime, so the
    // per-tick RLM sweep never releases the dispatch hold and boot hangs forever at
    // "54%" (openAsset pins 4878) on any host with non-trivial uptime. The error
    // scales with uptime -- which is EXACTLY why a freshly-booted machine crossed 7/7
    // (error = minutes, inside the boot window) while a multi-day-uptime machine sticks
    // 0/N. PROVEN by-construction, not probabilistically: MACAPK_CLOCK_REBASE=0 (== no
    // rebase, epoch-consistent) crosses MCPE 2/2 in 22 s vs the rebased default 0/2
    // stuck, on a 1.4-day-uptime host. Gating on g_unity_present keeps Unity correct
    // (Subway/Crossy unchanged) AND makes every non-Unity guest epoch-consistent on
    // every run regardless of uptime/load/interleaving. g_unity_present is set during
    // libunity's symbol resolution (load time), before any Unity clock read, so Unity
    // never sees an un-rebased sample. Env override wins: MACAPK_CLOCK_REBASE=1 forces
    // on, =0 forces off (A/B + escape hatch). Generic engine-level predicate, no per-APK.
    static const int forced = []{
        const char* e = std::getenv("MACAPK_CLOCK_REBASE");
        return e ? (std::atoi(e) != 0 ? 1 : 0) : -1;
    }();
    if (forced >= 0) return forced == 1;
    // RESOLVED (2026-09-28) by MACAPK_GUEST_CLOCK_NANOTIME: the guest CLOCK_MONOTONIC
    // IS System.nanoTime()'s clock now, so no rebase at all -- the COUPLING NOTE's
    // "only state that satisfies both families". The v1.0.212 "float32 subtraction"
    // reading was never confirmed in libunity code; batch W measured Unity 6000's
    // presentTime path keeping a correct unscaledDeltaTime at a 2.09e6 s magnitude.
    // docs/guest-clock-one-monotonic-base_2026-09-28.md.
    if (macapk_guest_clock_nanotime()) return false;
    return g_unity_present.load(std::memory_order_relaxed);
}

// sysconf: Bionic and macOS assign DIFFERENT integers to the same _SC_* name, so
// a guest compiled against Bionic's <bits/sysconf.h> passes numbers that macOS
// libSystem sysconf misinterprets. Root cause of the Crossy Road post-age-gate
// crash: il2cpp's bundled bdwgc GC_setpagesize calls sysconf(39) (Bionic
// _SC_PAGESIZE), but on macOS 39 == _SC_SHARED_MEMORY_OBJECTS which returns -1,
// so GC_page_size became (unsigned)-1 = 0xffffffff. Every bdwgc heap-region
// alignment then rounded to a garbage ~4 GiB-ish boundary, and the heap-section
// array growth that freed such a region tripped bdwgc's "Deallocating excessively
// large block" abort during the scene load. Translate the Bionic constant to the
// macOS constant before the real call. Values verified against Bionic
// libc/include/bits/sysconf.h and $(xcrun --show-sdk-path)/usr/include/unistd.h;
// same class of bug as the mmap MAP_ANON (0x20 vs 0x1000) and sigmask "how"
// mismatches. Untranslated names are forwarded raw (best effort) with an optional
// trace so any future mismatch that matters is easy to spot.
extern "C" long __macapk_arm64_sysconf(int bionic_name) {
    int mac;
    switch (bionic_name) {
        case 0:  mac = _SC_ARG_MAX;          break;  // Bionic _SC_ARG_MAX
        case 5:  mac = _SC_CHILD_MAX;        break;  // Bionic _SC_CHILD_MAX
        case 6:  mac = _SC_CLK_TCK;          break;  // Bionic _SC_CLK_TCK
        case 9:  mac = _SC_LINE_MAX;         break;  // Bionic _SC_LINE_MAX
        case 10: mac = _SC_NGROUPS_MAX;      break;  // Bionic _SC_NGROUPS_MAX
        case 11: mac = _SC_OPEN_MAX;         break;  // Bionic _SC_OPEN_MAX
        // PAGESIZE must be the REAL macOS page size (16384). libunity's own
        // allocator (and bdwgc) call mmap/munmap/mprotect with page-granular
        // addresses + sizes; returning Android's 4096 makes libunity_munmap
        // SIGBUS (BUS_ADRALN) on a sub-page during UnityPlayer.loadNative.
        // (Tested: 4096 -> early SIGBUS. The splash stall is NOT a pagesize
        // mismatch -- it is the InstantiateAsync/Addressables async-op
        // completion not being pumped; see the splash investigation notes.)
        case 39: mac = _SC_PAGESIZE;         break;  // Bionic _SC_PAGESIZE  <-- the crash fix
        case 40: mac = _SC_PAGE_SIZE;        break;  // Bionic _SC_PAGE_SIZE (alias)
        case 96: mac = _SC_NPROCESSORS_CONF; break;  // Bionic _SC_NPROCESSORS_CONF
        case 97: mac = _SC_NPROCESSORS_ONLN; break;  // Bionic _SC_NPROCESSORS_ONLN
        case 98: mac = _SC_PHYS_PAGES;       break;  // Bionic _SC_PHYS_PAGES
        case 99: mac = _SC_PHYS_PAGES;       break;  // Bionic _SC_AVPHYS_PAGES (macOS has no
                                                     // available-pages query; total is a safe bound)
        default:
            if (macapk_envp("MACAPK_FUTEX_TRACE")) {
                long rv = sysconf(bionic_name);
                std::fprintf(stderr,
                    "[sysconf] untranslated Bionic _SC_=%d forwarded raw -> %ld\n",
                    bionic_name, rv);
                return rv;
            }
            return sysconf(bionic_name);
    }
    // MACAPK_NPROC_OVERRIDE: report a larger online/configured CPU count so a guest
    // that sizes a FIXED thread pool by hardware_concurrency()/_SC_NPROCESSORS gets
    // more workers. Diagnostic lever for the MCPE Streaming-Pool exhaustion deadlock
    // (all pool workers held busy-waiting inside tasks that spin for an `isReady`
    // flag only the QUEUED connect-starter can set -> no free worker to run it).
    // Default unset = report true host count. Env read once, cached.
    if (bionic_name == 96 || bionic_name == 97) {
        static long np_ovr = []{ const char* e = std::getenv("MACAPK_NPROC_OVERRIDE");
                                 return e ? std::atol(e) : 0L; }();
        if (np_ovr > 0) return np_ovr;
    }
    long rv = sysconf(mac);
    if (macapk_envp("MACAPK_FUTEX_TRACE"))
        std::fprintf(stderr, "[sysconf] Bionic _SC_=%d -> macOS %d -> %ld\n",
                     bionic_name, mac, rv);
    return rv;
}


// ---- livelock breaker: rate-cap pathological monotonic-clock polling ---------
// The MCPE "54%" signaling-sign-in hang is a WorkerPool LIVELOCK, NOT a clock/epoch
// bug (proven live: with the monotonic clock rebased to a small process-relative
// magnitude the spin is byte-for-byte IDENTICAL -- ~12.8M clk-1 reads in 45 s -- so
// float32 precision at large magnitude is not the cause). Two "Streaming Pool"
// workers busy-drain a self-reposting readiness-poll task (the libHttpClient
// XAsyncSchedule(async,0) idiom: the task's run() returns "reschedule", its
// deadline[task+0x48] <= now by construction, so submit's deadline<=now branch
// re-dispatches it IMMEDIATELY every iteration) and flood the pool's intake queue.
// The Legacy-signaling connect-starter task (also a zero-delay self-reschedule)
// therefore rarely gets a worker turn and never reaches its "issue the websocket
// request" step -> the sign-in never completes -> boot hangs at "54%". The drain
// loop reads steady_clock::now (== our clock_gettime CLOCK_MONOTONIC) ONCE PER
// ITERATION, measured at ~140k/s PER spinning thread. No real workload needs the
// monotonic time anywhere near that often (a 60fps game reads it low-thousands/s at
// most), so a per-thread read rate that high is definitionally a spin. A per-thread
// TOKEN BUCKET hard-caps each thread's monotonic-clock read rate: a legit consumer
// stays under its refill rate and is NEVER slept (zero effect on normal apps or
// steady-state frame pacing), while a spinning drain loop is capped -- which both
// frees the CPU core AND throttles its intake-queue flood so the starved producer's
// task finally gets picked. This is the QUEUE-FAIRNESS lever that the many
// scheduling/priority/PI-mutex attempts (v620-v621, all probabilistic) never
// reached: it slows the FLOODER instead of trying to prioritise the STARVED.
// Generic -- engine-agnostic, no per-APK, self-targeting purely by the read rate.
// The bucket clock is the RAW pre-rebase monotonic sample (below), so it is immune
// to the rebase. See docs/mcpe-54pct-signaling-signin-spin_2026-07-15.md.
//   cap:   sustained reads/sec allowed per thread (spin ~140k/s -> ~7x throttle)
//   burst: instantaneous read allowance (a whole frame's legit reads pass free)
static constexpr double   kSpinBreakCapHz     = 20000.0;
static constexpr double   kSpinBreakBurst     = 20000.0;
static constexpr uint64_t kSpinBreakMaxSleepUs = 2000;
static bool macapk_clk_spin_break_enabled() {
    // DEFAULT OFF as of 2026-07-15. This throttle shipped v629 believing it broke
    // the MCPE online-signaling livelock, but a drift-controlled interleaved A/B
    // that session REFUTED it: with the throttle ON the run crossed 2/10 vs 4/10
    // with it OFF (i.e. it did not help, and if anything slightly hurt). It is a
    // clock-read-rate WORKAROUND, not a semantic fix, and the real gate is a native
    // WorkerPool wait that never arrives (not a clock-read flood). Kept behind
    // MACAPK_CLK_SPIN_BREAK=1 for A/B; default OFF so no app pays a clock-read
    // sleep it does not need. Inert-when-on for normal apps still holds; it is
    // simply not earning its keep, so it is off.
    static const int on = []{ const char* e = std::getenv("MACAPK_CLK_SPIN_BREAK");
                              return e ? (std::atoi(e) != 0 ? 1 : 0) : 0; }();
    return on == 1;
}

extern "C" int __macapk_arm64_clock_gettime(int clock_id,
                                                struct timespec* ts) {
    // Belt-and-suspenders x18 self-heal. Guest arm64 code calls clock_gettime
    // constantly, so any thread that reached guest code without passing an
    // explicit guest-entry boundary above (e.g. a JVM worker thread invoking a
    // non-divergent guest native, which HotSpot calls as a raw fn pointer with
    // no wrapper) enables x18 preservation on its first shim call here. Guarded
    // (if(!bit)), so cheap. See docs/x18-custom-abi-toggle-entitlement_2026-07-14.md.
    macapk_enable_x18_preservation();
    if (!ts) { errno = EFAULT; return -1; }
    clockid_t darwin_clock;
    switch (clock_id) {
        case 0:  darwin_clock = CLOCK_REALTIME;            break;
        case 1:  darwin_clock = CLOCK_MONOTONIC;           break;
        case 2:  darwin_clock = CLOCK_PROCESS_CPUTIME_ID;  break;
        case 3:  darwin_clock = CLOCK_THREAD_CPUTIME_ID;   break;
        case 4:  darwin_clock = CLOCK_MONOTONIC_RAW;       break;
        case 5:  darwin_clock = CLOCK_REALTIME;            break;
        case 6:  darwin_clock = CLOCK_MONOTONIC;           break;
        case 7:  darwin_clock = CLOCK_MONOTONIC;           break;
        default: darwin_clock = CLOCK_MONOTONIC;           break;
    }
    // MACAPK_GUEST_CLOCK_NANOTIME (default ON): the Bionic id's AOSP meaning, on the
    // clock System.nanoTime() reads (table + sources above __macapk_shim_clock_gettime).
    if (macapk_guest_clock_nanotime())
        darwin_clock = macapk_guest_clock_host_id(clock_id);
    int r = ::clock_gettime(darwin_clock, ts);
    // Livelock breaker (see block above __macapk_arm64_clock_gettime). Runs on the
    // RAW ts (before the rebase below) so the token bucket's clock is unaffected by
    // the rebase. Only the monotonic family is polled in a drain loop; realtime/CPU
    // clocks are never spun on. A slept read returns a value up to a couple ms stale,
    // which is harmless for the only threads that ever sleep here (spinners, whose
    // loop does not care about sub-ms freshness); every legit consumer stays under
    // the refill rate and never sleeps, so its value is exactly as fresh as before.
    if (r == 0 && macapk_clk_spin_break_enabled()
        && (clock_id == 1 || clock_id == 4 || clock_id == 6 || clock_id == 7)) {
        static thread_local double   tl_tokens  = kSpinBreakBurst;
        static thread_local uint64_t tl_last_ns = 0;
        uint64_t raw_ns = (uint64_t)ts->tv_sec * 1000000000ull
                          + (uint64_t)(uint32_t)ts->tv_nsec;
        if (tl_last_ns == 0) tl_last_ns = raw_ns;
        if (raw_ns > tl_last_ns) {                    // refill (monotonic; guard skew)
            tl_tokens += (double)(raw_ns - tl_last_ns) * (kSpinBreakCapHz / 1e9);
            if (tl_tokens > kSpinBreakBurst) tl_tokens = kSpinBreakBurst;
        }
        tl_last_ns = raw_ns;
        if (tl_tokens >= 1.0) {
            tl_tokens -= 1.0;                          // under cap: free, no sleep
        } else {
            // Over cap: sleep just long enough for one token to accrue, then this
            // thread is hard-limited to kSpinBreakCapHz reads/sec.
            double need = 1.0 - tl_tokens;             // tokens still owed
            uint64_t us = (uint64_t)(need / kSpinBreakCapHz * 1e6);
            if (us > kSpinBreakMaxSleepUs) us = kSpinBreakMaxSleepUs;
            if (us) usleep((useconds_t)us);
            tl_tokens = 0.0;
        }
    }
    // Clock rebase: OFF by default since MACAPK_GUEST_CLOCK_NANOTIME (2026-09-28);
    // the text below is the v1.0.212 rationale, which now applies only under
    // MACAPK_GUEST_CLOCK_NANOTIME=0 or a forced MACAPK_CLOCK_REBASE=1.
    // Clock rebase (default-on once libunity is present; see
    // clock_rebase_enabled). macOS CLOCK_MONOTONIC is host uptime (observed
    // ~305666 s, i.e. days), whereas Android's monotonic clock starts near 0
    // at device boot. Unity's per-frame UNSCALED delta path subtracts two
    // monotonic samples in float32; one float32 ULP near 305666 s is ~0.03 s,
    // larger than a 16 ms frame, so the subtraction rounds to 0 and
    // Time.unscaledDeltaTime collapses to a ~1e-5 clamp floor (every
    // unscaledDeltaTime-driven UI animation -- e.g. Crossy's age-gate panel --
    // crawls ~1000x too slow). Rebase the MONOTONIC family to be process-
    // relative (start ~1 s) so magnitudes match Android and float32 frame
    // deltas keep full precision. Verified via the il2cpp time-probe:
    // unscaledDeltaTime 9.99858e-06 -> 0.0369 (== deltaTime at timeScale 1, the
    // Unity invariant). Transparent to consumers that already subtract their
    // own startup sample (realtimeSinceStartup is unchanged: both terms shift
    // by the same base). Gated on libunity so cocos / other guests are
    // untouched; never package-gated.
    if (r == 0 && clock_rebase_enabled()
        && (clock_id == 1 || clock_id == 4 || clock_id == 6 || clock_id == 7)) {
        static std::atomic<uint64_t> s_base_ns{0};
        uint64_t now_ns = (uint64_t)ts->tv_sec * 1000000000ull
                          + (uint64_t)(uint32_t)ts->tv_nsec;
        uint64_t base = s_base_ns.load(std::memory_order_relaxed);
        if (base == 0) {
            uint64_t want = (now_ns > 1000000000ull)
                            ? now_ns - 1000000000ull : 0;  // start ~1 s in
            if (s_base_ns.compare_exchange_strong(base, want))
                base = want;
        }
        uint64_t rel = (now_ns > base) ? now_ns - base : 0;
        ts->tv_sec  = (time_t)(rel / 1000000000ull);
        ts->tv_nsec = (long)(rel % 1000000000ull);
    }
    // MACAPK_CLOCK_TRACE: which clock IDs does the engine read, how
    // often, and do the values advance? A frozen clock here = a frozen
    // per-frame delta for whatever Time value derives from it.
    if (r == 0 && macapk_envp("MACAPK_CLOCK_TRACE")) {
        static std::atomic<uint32_t> n[8]{};
        uint32_t idx = (clock_id >= 0 && clock_id < 8) ? clock_id : 0;
        uint32_t c = n[idx].fetch_add(1, std::memory_order_relaxed);
        if (c < 4 || (c % 600) == 0) {
            std::fprintf(stderr,
                "[clk-arm64] clock_gettime(clk=%d) #%u r=%d ts=(%llds, %ldns)\n",
                clock_id, c, r, (long long)ts->tv_sec, (long)ts->tv_nsec);
            std::fflush(stderr);
        }
    }
    return r;
}

// gettimeofday: libunity and libEOSSDK import it (gettimeofday@LIBC).
//
// ABI MISMATCH (the v1.0.333 Among Us "Invalid Date values" fatal loop):
//   Bionic/Linux arm64 (bionic/libc/kernel/uapi/linux/time.h +
//   uapi/asm-generic/posix_types.h):
//     struct timeval { __kernel_old_time_t tv_sec;       // long = 8 B @0
//                      __kernel_suseconds_t tv_usec; };  // long = 8 B @8
//   macOS (MacOSX.sdk sys/_types/_timeval.h + sys/_types.h:86
//   "typedef __int32_t __darwin_suseconds_t"):
//     struct timeval { __darwin_time_t tv_sec;            // 8 B @0
//                      __darwin_suseconds_t tv_usec; };   // 4 B @8
// Forwarding the guest pointer raw lets Darwin write only 4 of the 8
// tv_usec bytes; the Bionic reader sees stale stack garbage in the upper
// half (observed: +2^32 us and +2^35 us). The EOS SDK builds its log
// timestamps as gettimeofday + localtime_r (struct tm IS layout-identical
// across the two ABIs, so Y/M/D/H/M/S were right) + Ms = tv_usec/1000,
// got Ms ~= 4295000, declared the date invalid, and dead-looped its
// fatal-error handler. Convert through a host struct instead.
//
// (Also: without any shim the caller would get macOS's real wall-clock
// epoch ~1.75e9 s; if per-frame timers read it into float32 the ULP near
// 1.75e9 is ~128 s -- the v1.0.212 huge-time-in-float32 bug class.
// Tested + reverted: rebasing this to process-relative had NO effect on
// the Crossy splash stall, so the AsyncInstantiate integration budget does
// not key off gettimeofday -- it is the rebased clock_gettime(MONOTONIC),
// which is already precise.)
struct MacapkBionicTimeval64 {
    int64_t tv_sec;
    int64_t tv_usec;
};
extern "C" int __macapk_arm64_gettimeofday(MacapkBionicTimeval64* tv,
                                           void* tz) {
    // Write the FULL Bionic timeval the way a real device does. NDK-verified
    // (compiled against the aarch64 Bionic sysroot): sizeof(struct timeval)==16
    // and offsetof(tv_usec)==8, so tv_usec is a full 8-byte long. Forwarding
    // the guest pointer raw to macOS gettimeofday only writes 4 of those 8
    // bytes (Darwin's suseconds_t is int32), leaving the high half as stale
    // stack/heap garbage; a Bionic reader then sees tv_usec ~= 2^32+real. That
    // garbage broke real apps -- the EOS SDK dead-looped its "Invalid Date"
    // fatal handler (starving Among Us' online game-load -> player kicked).
    // Converting through a host struct and writing both 8-byte fields is the
    // correct, unconditional behavior (matches Android for every app).
    //
    // (History: v1.0.334 had this gated off / EOS-only because enabling it
    // surfaced a SEPARATE Crossy bug -- Firebase's datatransport called the
    // then-missing android.net.NetworkInfo.getSubtype(), threw NoSuchMethodError
    // on a background thread, and Crashlytics halted the process. That gap is
    // now fixed in NetworkInfo, so the correct clock is safe for all apps and
    // the gate is gone.)
    struct timeval host;
    int r = ::gettimeofday(tv ? &host : nullptr,
                           reinterpret_cast<struct timezone*>(tz));
    if (r == 0 && tv) {
        tv->tv_sec  = host.tv_sec;
        tv->tv_usec = host.tv_usec;   // full 8-byte write; high half zero
    }
    if (macapk_envp("MACAPK_CLOCK_TRACE")) {
        static std::atomic<uint32_t> n{0};
        uint32_t c = n.fetch_add(1, std::memory_order_relaxed);
        if (c < 4 || (c % 600) == 0)
            std::fprintf(stderr,
                "[clk-arm64] gettimeofday #%u r=%d tv=(%llds, %lldus)\n",
                c, r, tv ? (long long)tv->tv_sec : -1,
                tv ? (long long)tv->tv_usec : -1);
    }
    return r;
}

extern "C" int __macapk_arm64_pthread_once(int* once, void (*init)(void)) {
    if (!once || !init) return 22;
    // 0 = uninitialized, 2 = in-progress, 1 = done. Spin while another
    // thread is in-progress; we don't have a futex/condvar set up for
    // this and Bionic's 4-byte once_t can't store one anyway.
    int expected = 0;
    if (__atomic_compare_exchange_n(once, &expected, 2,
                                    false,
                                    __ATOMIC_ACQUIRE,
                                    __ATOMIC_ACQUIRE)) {
        init();
        __atomic_store_n(once, 1, __ATOMIC_RELEASE);
        return 0;
    }
    while (__atomic_load_n(once, __ATOMIC_ACQUIRE) == 2) {
        sched_yield();
    }
    return 0;
}

// pthread_mutex_t on 64-bit Bionic is `struct { int32_t __private[10]; }`
// (40 bytes). macOS's pthread_mutex_t is 64 bytes -- much bigger -- and
// has a different layout. If we routed mutex calls to libSystem,
// pthread_mutex_init's 64-byte memset would scribble 24 bytes past the
// app's Bionic-sized allocation, frequently into adjacent global
// objects (e.g. FMOD::Globals members), which is what causes
// FMOD_System_Create to dereference garbage further down.
//
// Simple Bionic-compatible impl: spin-CAS on __private[0]. Real-world
// contention is low for the init paths we hit, and this avoids the
// layout mismatch entirely. If a workload turns out to need fair
// scheduling, we can swap this for a Bionic-shaped mutex wrapping a
// macOS os_unfair_lock via a side-table keyed by mutex address.
//
// USE-AFTER-FREE PROTECTION (mutex + cond):
//
// Older libfmod builds (the FMOD forum issue "FORTIFY:
// pthread_mutex_lock called on a destroyed mutex" documents the same
// pattern) have a known use-after-destroy bug -- they call lock /
// signal / etc through a pointer to a pthread object whose
// containing struct has already been free()'d. On Bionic with
// FORTIFY this fast-fails. Our shim historically wrote
// unconditionally into the pointed-at memory (CAS 0->1 on lock,
// fetch_add +4 on signal), and when malloc had since recycled that
// chunk for someone else -- typically libcocos's zlib
// `inflate_state` (its ~7 KB allocation is a popular allocator
// recycle slot) -- the stale ops scribbled into the recycler's
// fields. Over ~8 stale signals the +4 stream plants exactly 32
// inside `state->lens[]` (uint16 each), which drives inflate_table's
// bit-reverse increment loop into a 33+ bit huff value and SIGBUS
// on the next scatter store. This is the heap-corruption signature
// `huff=0x80000002 / mask=0xffffffff` that turned up invariantly
// across many runs in the 2026-05-15 sessions.
//
// Defense: at init time we stamp a magic sentinel deep inside each
// pthread object (in Bionic's `__reserved` region, which Bionic
// itself never reads or writes), and every subsequent lock / signal
// / wait verifies the magic before mutating the memory. If the
// containing struct is freed and the memory is recycled, the new
// owner overwrites our magic with its own data, and the next stale
// op simply refuses to write. The magic is unique per pthread kind
// and 32 bits wide, so accidental collision with a recycler's
// genuine data at the same offset is astronomically unlikely.
//
// Bionic layouts for reference (aarch64 LP64):
//   pthread_mutex_t  = 40 bytes; we stamp magic at offset 36 (slot 9).
//   pthread_cond_t   = 48 bytes; we stamp magic at offset 40 (slot 10).
// Both offsets fall inside the __reserved tail that Bionic guarantees
// it doesn't touch.
//
// Static initialization (PTHREAD_MUTEX_INITIALIZER / PTHREAD_COND_
// INITIALIZER) gives an all-zero struct with no magic. We special-
// case that: if the magic is missing but the rest of the struct
// is also zero, we treat the object as a valid never-locked /
// never-signalled instance and lazy-stamp the magic at the first op.
// Corrupted / use-after-freed memory is non-zero with no magic, so
// the all-zero check excludes that path.
static constexpr uint16_t kBionicMutexDestroyed = 0xffff;
static constexpr uint32_t kMacApkMutexMagic   = 0xc0d36055u;
static constexpr int kMutexMagicSlot = 9;  // offset 36, in Bionic __reserved
static inline bool macapk_arm64_mutex_is_destroyed(const int32_t* m) {
    return (uint16_t)(__atomic_load_n(&m[0], __ATOMIC_RELAXED) & 0xffff)
           == kBionicMutexDestroyed;
}
static inline bool macapk_arm64_mutex_all_zero(const int32_t* m) {
    for (int i = 0; i < 10; ++i) {
        if (__atomic_load_n(&m[i], __ATOMIC_RELAXED) != 0) return false;
    }
    return true;
}
// Recursive/errorcheck mutex support. Bionic's pthread_mutex honors
// PTHREAD_MUTEX_RECURSIVE (value 1) / PTHREAD_MUTEX_ERRORCHECK (2) -- the same
// thread re-locking a RECURSIVE mutex must succeed (bump a depth counter), not
// block. Our old shim ignored the type and a recursive re-lock blocked the
// thread waiting on ITSELF forever (e.g. std::recursive_mutex during init).
// We store the type + recursion depth + owner thread id in the Bionic
// __reserved slots (m[1..4]); m[0] stays the 3-state futex word, m[9] the magic.
static constexpr int kMutexTypeSlot  = 1;  // Bionic type: 0 normal,1 recursive,2 errorcheck
static constexpr int kMutexCountSlot = 2;  // recursion depth while held
static constexpr int kMutexOwnerLo   = 3;  // owner thread id (pthread_self) lo32
static constexpr int kMutexOwnerHi   = 4;  // owner thread id hi32
static constexpr int kMutexFairSlot  = 5;  // fairness streak: contended-unlocks since a waiter last broke through. Bionic __reserved.
static constexpr int kMutexGrantSlot = 6;  // MACAPK_MUTEX_HANDOFF grant word: 0=none,1=handoff pending. Bionic __reserved. See docs/fair-handoff-mutex-design_2026-07-19.md.
static inline uint64_t macapk_self_id() {
    return (uint64_t)(uintptr_t)pthread_self();
}
static inline uint64_t macapk_mutex_owner(const int32_t* m) {
    return (uint64_t)(uint32_t)__atomic_load_n(&m[kMutexOwnerLo], __ATOMIC_RELAXED)
         | ((uint64_t)(uint32_t)__atomic_load_n(&m[kMutexOwnerHi], __ATOMIC_RELAXED) << 32);
}
static inline void macapk_mutex_set_owner(int32_t* m, uint64_t id) {
    __atomic_store_n(&m[kMutexOwnerLo], (int32_t)(uint32_t)id, __ATOMIC_RELAXED);
    __atomic_store_n(&m[kMutexOwnerHi], (int32_t)(uint32_t)(id >> 32), __ATOMIC_RELAXED);
}

// ---- owner-aware (kernel priority-inheritance) mutex via raw UL_UNFAIR_LOCK ----
// The default guest mutex parks m[0] with os_sync_wait_on_address (UL_COMPARE_AND_WAIT),
// which Apple documents as providing NO priority-inversion avoidance: a parked waiter
// neither donates priority to the lock HOLDER nor hands off its CPU quantum, so on xnu's
// strict-tier clutch scheduler a low-priority boot worker starves behind a busy holder
// (the MCPE localization race -- docs/mcpe-localization-scheduling-rootcause_2026-07-13.md).
// This alternate path parks m[0] with the raw UL_UNFAIR_LOCK ulock protocol (the same one
// os_unfair_lock uses), so the kernel (a) resolves the owner from the lock word (the
// holder's mach thread port name) and promotes the holder via a turnstile while a waiter
// blocks, and (b) hands the waiter's quantum directly to the holder at block time
// (thread_handoff_parameter). On unlock the highest-priority waiter is woken and made the
// turnstile inheritor. We use the RAW __ulock syscalls, not libplatform's os_unfair_lock
// wrappers, because those ABORT the process on unlock-by-non-owner / double-unlock /
// recursive-relock -- all of which Bionic guests can legally-ish do; the raw protocol lets
// us keep Bionic error semantics (EPERM/EBUSY/EDEADLK) and never crash. Gate
// MACAPK_MUTEX_OWNER_AWARE (read ONCE at startup: the whole process must use ONE opcode
// family, since mixing UL_COMPARE_AND_WAIT and UL_UNFAIR_LOCK on one address is EDOM).
extern "C" int __ulock_wait2(uint32_t operation, void* addr, uint64_t value,
                             uint64_t timeout_ns, uint64_t value2);
extern "C" int __ulock_wake(uint32_t operation, void* addr, uint64_t wake_value);
static constexpr uint32_t kUL_UNFAIR_LOCK           = 2;
static constexpr uint32_t kULF_WAKE_ALLOW_NON_OWNER = 0x400;
static constexpr uint32_t kULF_WAIT_ADAPTIVE_SPIN   = 0x40000;
static constexpr uint32_t kULF_NO_ERRNO             = 0x1000000;
static constexpr uint32_t kOS_ULOCK_NOWAITERS_BIT   = 1;   // low bit of a mach port name
static bool macapk_mutex_owner_aware() {
    static const bool on = []{ const char* e = std::getenv("MACAPK_MUTEX_OWNER_AWARE");
                               return e && e[0] != '0'; }();
    return on;
}
// MACAPK_MUTEX_HANDOFF (default OFF): replace the v599-v619 contended-unlock fairness
// usleep with a fair grant-word DIRECT HANDOFF (parking_lot unlock_fair / WebKit direct
// handoff): on a contended unlock the word STAYS 2 (never passes through 0, so nobody can
// barge), ownership is published in kMutexGrantSlot and claimed post-park by exactly one
// waiter; the no-waiter case is detected via os_sync_wake_by_address_any's ENOENT and
// revoked. Fixes the ROOT of the tight-loop-unlocker-starves-co-consumer bug (macOS has no
// wakeup preemption; Bionic's same barging algorithm is fair only via Linux's scheduler).
// OWNER_AWARE takes precedence (checked first). See docs/fair-handoff-mutex-design_2026-07-19.md.
static bool macapk_mutex_handoff() {
    static const bool on = []{ const char* e = std::getenv("MACAPK_MUTEX_HANDOFF");
                               return e && e[0] != '0'; }();
    return on;
}
// The thread's mach port name -- os_unfair_lock's owner token. Mach port names always
// have the low bit set (ipc generation bits); the NOWAITERS protocol relies on that.
static inline uint32_t macapk_self_mach_port() {
    static thread_local uint32_t p = 0;
    if (!p) p = pthread_mach_thread_np(pthread_self());
    return p;
}
static inline bool macapk_arm64_mutex_ensure_valid(int32_t* m);   // defined below
// Acquire m[0] via the UL_UNFAIR_LOCK protocol (mirrors libplatform os_unfair_lock_lock).
// Returns 0, or 22 (EINVAL) if the mutex was destroyed while we waited. Owner/type/count
// bookkeeping stays in the caller (kept identical to the default path).
static int macapk_oal_word_lock(int32_t* m) {
    const uint32_t self = macapk_self_mach_port();
    uint32_t expected = 0;
    if (__atomic_compare_exchange_n(reinterpret_cast<uint32_t*>(&m[0]), &expected, self,
                                    false, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED))
        return 0;                                   // uncontended fast path
    for (;;) {
        if (!macapk_arm64_mutex_ensure_valid(m)) return 22;   // destroyed under us
        uint32_t cur = __atomic_load_n(reinterpret_cast<uint32_t*>(&m[0]), __ATOMIC_RELAXED);
        if (cur == 0) {
            uint32_t e0 = 0;
            if (__atomic_compare_exchange_n(reinterpret_cast<uint32_t*>(&m[0]), &e0, self,
                                            false, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED))
                return 0;
            continue;
        }
        // Advertise waiters by clearing the NOWAITERS bit, then block. `value` is the
        // word WITH the waiters bit cleared so the kernel can resolve the PI target.
        uint32_t withw = cur & ~kOS_ULOCK_NOWAITERS_BIT;
        if (withw != cur &&
            !__atomic_compare_exchange_n(reinterpret_cast<uint32_t*>(&m[0]), &cur, withw,
                                         false, __ATOMIC_RELAXED, __ATOMIC_RELAXED))
            continue;                               // word moved; re-evaluate
        __ulock_wait2(kUL_UNFAIR_LOCK | kULF_WAIT_ADAPTIVE_SPIN | kULF_NO_ERRNO,
                      &m[0], withw, 0, 0);
    }
}
// Release m[0]. Wakes the highest-priority waiter (kernel turnstile) if any were parked.
static inline void macapk_oal_word_unlock(int32_t* m) {
    const uint32_t self = macapk_self_mach_port();
    uint32_t prev = __atomic_exchange_n(reinterpret_cast<uint32_t*>(&m[0]), 0,
                                        __ATOMIC_RELEASE);
    // prev==self (NOWAITERS bit set) means we held it uncontended -> no waiters. Otherwise
    // (waiters bit was cleared, or an unlock-from-another-thread) wake one waiter.
    // ALLOW_NON_OWNER tolerates Bionic's unlock-from-a-different-thread patterns.
    if (prev != self)
        __ulock_wake(kUL_UNFAIR_LOCK | kULF_WAKE_ALLOW_NON_OWNER | kULF_NO_ERRNO, &m[0], 0);
}
// Owner-aware lock/trylock/unlock: the SAME type/recursion/errorcheck bookkeeping as the
// default path, but the m[0] core uses the UL_UNFAIR_LOCK protocol above.
static int macapk_oal_mutex_lock(int32_t* m) {
    if (!macapk_arm64_mutex_ensure_valid(m)) return 22;
    const uint64_t self = macapk_self_id();
    const int32_t type = __atomic_load_n(&m[kMutexTypeSlot], __ATOMIC_RELAXED);
    if (type != 0 && macapk_mutex_owner(m) == self) {
        if (type == 1) { __atomic_add_fetch(&m[kMutexCountSlot], 1, __ATOMIC_RELAXED); return 0; }
        return 35;                                  // ERRORCHECK -> EDEADLK
    }
    int r = macapk_oal_word_lock(m);
    if (r != 0) return r;
    macapk_mutex_set_owner(m, self);
    __atomic_store_n(&m[kMutexCountSlot], 1, __ATOMIC_RELAXED);
    return 0;
}
static int macapk_oal_mutex_trylock(int32_t* m) {
    if (!macapk_arm64_mutex_ensure_valid(m)) return 22;
    const uint64_t self = macapk_self_id();
    const int32_t type = __atomic_load_n(&m[kMutexTypeSlot], __ATOMIC_RELAXED);
    if (type == 1 && macapk_mutex_owner(m) == self) {
        __atomic_add_fetch(&m[kMutexCountSlot], 1, __ATOMIC_RELAXED);
        return 0;
    }
    const uint32_t sp = macapk_self_mach_port();
    uint32_t e0 = 0;
    if (__atomic_compare_exchange_n(reinterpret_cast<uint32_t*>(&m[0]), &e0, sp,
                                    false, __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        macapk_mutex_set_owner(m, self);
        __atomic_store_n(&m[kMutexCountSlot], 1, __ATOMIC_RELAXED);
        return 0;
    }
    return 16;                                      // EBUSY
}
static int macapk_oal_mutex_unlock(int32_t* m) {
    if (!macapk_arm64_mutex_ensure_valid(m)) return 22;
    const int32_t type = __atomic_load_n(&m[kMutexTypeSlot], __ATOMIC_RELAXED);
    if (type != 0) {
        if (macapk_mutex_owner(m) != macapk_self_id()) return 1;   // EPERM
        if (__atomic_load_n(&m[kMutexCountSlot], __ATOMIC_RELAXED) > 1) {
            __atomic_sub_fetch(&m[kMutexCountSlot], 1, __ATOMIC_RELAXED);
            return 0;                               // still held recursively
        }
    }
    __atomic_store_n(&m[kMutexCountSlot], 0, __ATOMIC_RELAXED);
    macapk_mutex_set_owner(m, 0);
    macapk_oal_word_unlock(m);
    return 0;
}
// Returns true if the mutex is recognised as ours.
//
// Two acceptable forms:
//   - magic stamped at kMutexMagicSlot (the common case, set by
//     pthread_mutex_init or by lazy-stamp below)
//   - PTHREAD_MUTEX_INITIALIZER-style static init: the entire 40-byte
//     struct is zero AND the first observed op is a non-destructive
//     read of a TYPED mutex feature (i.e. just lock/trylock/unlock --
//     not destroy). For that case we lazy-stamp the magic. We reject
//     the lazy stamp if the memory was just hit by a "freed-then-
//     recycled" calloc / zero-initialised allocation though, because
//     that produces the same all-zero shape and the dangling caller
//     would scribble through. There is no perfect runtime test that
//     distinguishes those two cases, so we apply the lazy stamp only
//     when the caller passed a static-data address (read-only at
//     load time, becomes RW only when relocations install the magic
//     -- but static pthread inits don't go through that path).
//
// In practice every Android lib we see calls pthread_mutex_init
// dynamically (both libfmod and libcocos2dcpp import it), so the
// lazy-stamp path is a fallback for the rare PTHREAD_MUTEX_INITIALIZER
// user. To avoid the use-after-free false positive entirely, we
// require the lazy-stamp path to ALSO see the magic still missing
// after the stamp -- i.e. another thread isn't racing us to lazy-
// stamp. This makes spurious stamps on use-after-freed-then-zeroed
// memory at most a single +1 increment on the recipient's offset 0,
// which is far below the threshold (lens[i] >= 16) that triggers the
// inflate_table crash.
static inline bool macapk_arm64_mutex_ensure_valid(int32_t* m) {
    if (uint32_t(__atomic_load_n(&m[kMutexMagicSlot], __ATOMIC_RELAXED))
            == kMacApkMutexMagic) {
        return true;
    }
    if (!macapk_arm64_mutex_all_zero(m)) {
        // CONCURRENT-FIRST-LOCK RACE (v1.0.590): two threads lock a fresh
        // (all-zero) std::mutex for the FIRST time at once. The winner lazy-stamps
        // the magic (below) AND immediately acquires (sets m[0]=1, owner slots),
        // so between our magic-load above (which saw not-magic) and this all-zero
        // check the mutex is now BOTH magic-stamped and non-zero. Without a
        // re-check we'd wrongly declare it invalid and return EINVAL -- which
        // libc++'s std::mutex::lock() turns into an uncaught std::system_error ->
        // std::terminate (this was the MCPE Swappy ChoreographerFilter SIGABRT:
        // the ChoreographerFilter mutex is locked by threadMain and the
        // choreographer-posting thread near-simultaneously at startup). Re-load
        // the magic with ACQUIRE ordering before giving up: if a concurrent
        // stamper set it, the mutex IS ours and valid. (The CAS-stamp path below
        // already handles the symmetric race via its `expected` readback.)
        return uint32_t(__atomic_load_n(&m[kMutexMagicSlot], __ATOMIC_ACQUIRE))
                   == kMacApkMutexMagic;
    }
    // Try once to claim this slot via CAS so concurrent lazy-stampers
    // don't race.
    int32_t expected = 0;
    if (!__atomic_compare_exchange_n(&m[kMutexMagicSlot],
                                     &expected,
                                     int32_t(kMacApkMutexMagic),
                                     false,
                                     __ATOMIC_RELEASE,
                                     __ATOMIC_RELAXED)) {
        return uint32_t(expected) == kMacApkMutexMagic;
    }
    return true;
}
// ===== Bionic-faithful futex-backed blocking for mutex / cond / sem =====
//
// Real Bionic implements pthread_mutex_t, pthread_cond_t AND sem_t all on top
// of the futex syscall -- one kernel wait-queue per address. Our shims used to
// busy-spin on sched_yield(), which is wrong on three counts that together
// deadlocked Unity's il2cpp runtime during the first nativeRender():
//   (a) a spinning waiter burns a whole core, and with the many threads
//       il2cpp/Baselib spawn, N spinners can starve the ONE thread that must
//       run to post/signal (priority/scheduler starvation -> apparent hang);
//   (b) the busy-spin shares NO wait-queue with the raw-futex path
//       (__macapk_arm64_syscall SYS_futex -> os_sync_*), so a wake issued
//       via one mechanism never reaches a waiter parked via the other -- and
//       il2cpp mixes sem_t / pthread_cond_t / Baselib-futex freely;
//   (c) pthread_cond_timedwait ignored its timeout entirely.
// Boehm-GC stop-the-world's ACK semaphore (sem_timedwait on the collector,
// sem_post from each thread's suspend handler) and the GC-Finalizer-thread
// start Event (pthread_cond) both stalled here. Back all three primitives on
// the SAME os_sync primitive the futex path uses, keyed on the primitive's own
// 32-bit state word, so they block for real and interoperate -- mirroring how
// Bionic layers them on futex.
//
// macapk_futex_wait_word: block while *addr == val. rel_timeout_ns == 0 means
// wait forever. Returns 0 when woken or *addr already moved off `val` (caller
// MUST re-check its own predicate -- os_sync, like futex, allows spurious
// returns); returns -1 with errno set by os_sync (macOS ETIMEDOUT==60) on the
// deadline. Callers translate that to the Bionic errno their caller expects.
//
// DIAGNOSTIC (MACAPK_OSWAIT_TRACE-gated): trace os_sync park/wake for
// addresses at/above the libunity allocator arena floor (0x300000000) only,
// to isolate the GfxDevice command-queue / GfxEvent handshake from il2cpp GC
// and job-system churn (those sync words live on the il2cpp heap, below the
// arena). An arena address that is PARKed on but never appears in a WAKE is a
// missed wakeup -- exactly the "GfxDeviceWorker never acks render-init" gate.
// No behaviour change: pure logging, gated, capped, no control-flow effect.
// v1.0.585 diag: per-thread guest ENTRY (the pthread_create start address) so the OSWAIT
// trace can attribute each park/wake to a thread ROLE by its start (e.g. cohtml Gameface
// Layout worker file vaddr 0x11b579fc vs a NetherNet reader vs a pool worker), since
// Mac.apk guest threads are unnamed. Set only when the trampoline is installed (gated on
// the trace env in __macapk_arm64_pthread_create), so production is untouched.
static thread_local uintptr_t t_pthread_entry = 0;
// v1.0.645: guest-vs-host thread tag for the foreign-wake defer (Android
// wakeup-granularity emulation, see __macapk_arm64_pthread_cond_signal). Every
// GUEST thread routes through macapk_thread_trampoline, which sets this to 1;
// HOST threads (the JVM main thread and HotSpot/JNI worker threads -- incl. the
// host-JVM OkHttp completion pool that posts libHttpClient HTTP completions)
// never pass through the trampoline, so they read the zero default. Used to
// defer ONLY host-originated condvar wakes of a guest cond.
static thread_local int t_is_guest = 0;
// Async-signal-safe by construction: a plain int defaulting to 0, so a host thread reads
// the default even before any lazy init, and a guest thread sets 1 at thread entry long
// before it can reach TaskGroup::queue. Used by the TGQ admission probe above.
static bool macapk_thread_is_host() { return t_is_guest == 0; }
// jvm_reserve: the bytes __macapk_arm64_pthread_create added BELOW the guest's
// requested stack for the host JVM's attach zones (0 = none; see
// macapk_guest_stack_jvm_reserve). Carried to the trampoline so the new thread
// can answer pthread_getattr_np with the stack it ASKED for, as Bionic does.
namespace { struct MacApkThreadStart { void* (*fn)(void*); void* arg; size_t jvm_reserve; }; }
static thread_local size_t t_stack_jvm_reserve = 0;

// ---- MACAPK_GUEST_STACK_JVM_RESERVE (default ON, v1.0.1654) -----------------
// A guest thread that asks for an explicit stack must get that much USABLE
// stack, whatever the host JVM later carves out of it. That is what it gets on
// a device: Bionic maps the guard as an EXTRA mapping below the requested size
// (bionic libc/bionic/pthread_create.cpp __allocate_thread_mapping(stack_size,
// guard_size), `writable_size = mmap_size - stack_guard_size - ...`), and ART
// rejects AttachCurrentThread only below about 16 KiB (art runtime/thread.cc,
// "Attempt to attach a thread with a too-small stack": min_stack =
// GetStackOverflowProtectedSize() + RoundUp(reserved(arm64 8K) + 4K, page)).
//
// On Mac.apk the attach goes to HotSpot, which takes far more, and takes it
// from the bottom of the SAME pthread stack:
//   * guard: red + yellow + reserved, mprotect'ed PROT_NONE by
//     create_stack_guard_pages() (jdk21u prims/jni.cpp:3796);
//   * shadow: must be free below sp before the attach's first Java call
//     (allocate_threadObj -> JavaCalls::call_helper ->
//     os::stack_shadow_pages_available, runtime/os.cpp:1644-1656:
//     sp > stack_end + guard + shadow + frame), else StackOverflowError ->
//     attach_failed -> JNI_ERR (jni.cpp:3820-3838).
// Each zone is align_up(<pages> * 4K, os::vm_page_size())
// (runtime/stackOverflow.cpp:38-68), with the aarch64 defaults Red 1,
// Yellow 2, Reserved 1, Shadow 20 (cpu/aarch64/globals_aarch64.hpp:45-51;
// PrintFlagsFinal on openjdk 21.0.11 and 26.0.1 agree). On a 16 KiB-page host
// that is 16+16+16+80 = 128 KiB. Measured on openjdk@21 (the gate
// debug/geh_fmod-image-tag-alloc-zone_gate.sh reproduces it): a pthread with
// an explicit 96 or 112 KiB stack gets AttachCurrentThread = JNI_ERR, 120 KiB
// and up gets JNI_OK. Every libfmod.so in the corpus creates its threads
// DETACHED with typeStack + 0x8000 (mixer 112 KiB, file 96 KiB) and attaches
// each one first thing; on JNI_ERR the thread returns without running its body
// or posting the start semaphore its creator sem_waits on, so FMOD init hangs.
// So we add the reserve BELOW the guest's request, and the guest keeps the
// whole of what it asked for. Only explicitly-sized threads: the 1 MiB default
// already clears it. Virtual only (pages commit on touch).
// A later -XX:Stack{Red,Yellow,Reserved,Shadow}Pages=N in JAVA_TOOL_OPTIONS,
// MACAPK_JVM_OPTS (runtime/src/jvm_loader.cpp appends it verbatim) or
// _JAVA_OPTIONS replaces the matching count, so this arithmetic and the VM
// agree. (Not parsed: -XX:Flags= and -XX:VMOptionsFile= indirection.)
// =0 restores the verbatim request (and the plain host getattr answer).
static size_t macapk_guest_stack_jvm_reserve() {
    static const size_t r = []() -> size_t {
        const char* v = macapk_envp("MACAPK_GUEST_STACK_JVM_RESERVE");
        if (v && v[0] == '0') {
            // Say it once, so a bisect that sets only this flag explains its
            // own hang: libfmod resolves generically (the old "libfmod" image
            // tag and its NULL-attr pthread_create are deleted), so every FMOD
            // app's mixer/file thread then fails AttachCurrentThread and FMOD
            // init waits forever (gate row L3).
            std::fprintf(stderr,
                "[arm64-shim] MACAPK_GUEST_STACK_JVM_RESERVE=0: explicitly-sized "
                "guest threads get their verbatim stack; a thread under about "
                "120 KiB will fail JVM AttachCurrentThread (FMOD init "
                "hangs)\n");
            return 0;
        }
        long pages[4] = {1, 2, 1, 20};   // Red, Yellow, Reserved, Shadow
        static const char* const kFlag[4] = {
            "-XX:StackRedPages=", "-XX:StackYellowPages=",
            "-XX:StackReservedPages=", "-XX:StackShadowPages="};
        // The VM parses JAVA_TOOL_OPTIONS, then the JNI option vector (where
        // MACAPK_JVM_OPTS lands), then _JAVA_OPTIONS, so a later source wins
        // (jdk21u share/runtime/arguments.cpp parse_vm_init_args, 2047-2068);
        // within each string the last occurrence wins.
        for (const char* var : {"JAVA_TOOL_OPTIONS", "MACAPK_JVM_OPTS", "_JAVA_OPTIONS"}) {
            const char* s = macapk_envp(var);
            if (!s) continue;
            for (int i = 0; i < 4; ++i) {
                const size_t fl = std::strlen(kFlag[i]);
                for (const char* p = std::strstr(s, kFlag[i]); p;
                     p = std::strstr(p + fl, kFlag[i])) {
                    if (p != s && p[-1] != ' ' && p[-1] != '\t') continue;
                    char* end = nullptr;
                    const long n = std::strtol(p + fl, &end, 10);
                    if (end != p + fl && n >= 0 && n < 4096) pages[i] = n;
                }
            }
        }
        const size_t page = (size_t)sysconf(_SC_PAGESIZE);
        size_t total = 0;
        for (long n : pages) {
            const size_t b = (size_t)n * 4096;
            total += (b + page - 1) / page * page;
        }
        return total;
    }();
    return r;
}
// For debug/geh_fmod-image-tag-alloc-zone_gate.sh: the reserve this process
// applies (0 when MACAPK_GUEST_STACK_JVM_RESERVE=0). Not an __macapk_arm64_
// name, so no guest import can ever bind to it.
extern "C" size_t __macapk_host_jvm_attach_reserve(void) {
    return macapk_guest_stack_jvm_reserve();
}

// Forward decl: erases this (exiting) thread's entries from the guest tid
// registries (g_macapk_tidmap / g_macapk_qos_override). Full definition
// sits with those maps, after macapk_apply_thread_nice() further down this
// file; called from macapk_thread_trampoline() below, which runs before
// either map is declared textually.
static void macapk_unregister_guest_tid();

// ---- Gated Bedrock-worker CAP (MACAPK_WP_WORKER_CAP=N, default OFF) -----------
// *** NON-VIABLE AS A FIX (v643, breaks boot) -- kept as a gated DIAGNOSTIC only. ***
// Empirically REFUTED: capping the pool (even N=6, parking ~half of one 12-thread start
// routine) WEDGES early boot (stuck at fopen #~39, never reaches signaling), because the
// racing Bedrock pool is a boot-critical SHARED pool that early boot needs all workers of.
// This is a VALUABLE negative result: it proves we cannot fix the thread-affinity race by
// REDUCING the pool -- the fix must ROUTE the completion to the pump worker WITHOUT shrinking
// the pool (fix #2, the submit-affinity hook at WorkerPool::submit mc+0x13136038 / the
// self-ring [pool+0xf0..0xf8], keyed on [pool+0xd8]==dispatching-worker; see
// docs/mcpe-signaling-affinity-fix-design_2026-07-17.md). Default path is byte-unchanged
// (gated); leaving this in as the diagnostic that pinned "the pool is boot-critical."
// FIX #1 for the MCPE 54% signaling stall (docs/mcpe-signaling-thread-affinity-race +
// affinity-fix-design, 2026-07-17). The stall is a thread-affinity race: the auth
// coroutine's lock-free state is corrupted when its HTTP completion runs on a DIFFERENT
// Bedrock WorkerPool worker than the coroutine's pump (proven: cross <=> completion
// co-located w/ the dominant pump worker; stall <=> a minor worker). WorkerPool::submit
// (mc+0x13136038) has a submit-to-SELF affinity fast-path, so the guest is correct WHEN
// the completion starts on the pump worker. Capping the number of CONCURRENT pool workers
// raises the odds the (briefly-free) pump worker wins the completion-dispatch; N=1 forces
// serialization (Android composite-port semantics).
//
// GENERIC + base-independent: cap is keyed on the pthread START ROUTINE. A start routine
// that spawns > N threads is a thread POOL -> throttle it to N concurrently-running
// threads (excess threads PARK in the trampoline before running any guest code, released
// when a running peer exits OR the cap is lifted). A start routine with <= N instances
// (every one-off thread: render, main, FMOD mixer, cohtml layout, ...) is NEVER parked, so
// non-pool threads are untouched. cocos/GD/Unity don't create a Bedrock pool, but they DO
// create their own pools with the same shape -- so this is DEFAULT-OFF (env-gated) and must
// stay gated until #2 (the submit-affinity hook) replaces it. Watchdog auto-lifts the cap
// after MACAPK_WP_CAP_LIFT_MS (default 200s: longer than any A/B window, so the cap is
// active the whole signin phase; it only ever recovers a genuinely wedged non-A/B run).
// v643 REDESIGN (time-gated + park-at-idle-wait): the v642 create-time park WEDGED BOOT (the
// pool is boot-critical). Fable's mechanism (docs/…thread-affinity-race, /tmp/fable_mechanism.md)
// says the fix is to reduce concurrent pool workers ONLY during the post-boot SIGNIN WINDOW, so
// the auth coroutine's RUN + its completion (QResume) serialize on one worker (op4 doesn't race
// op1). So: (1) do NOT park at thread-create (boot needs all workers); instead mark the "excess"
// workers (a start routine's (N+1)th.. instance). (2) Park excess workers at their IDLE
// wait-for-work `cond_wait` (safe -- no locks held there), and ONLY while the cap is active.
// (3) Time-gate the cap to [START_MS, END_MS] so boot runs uncapped and it self-lifts (a wedge
// degrades to full parallelism). Default-OFF; gated experiment for FACT-C validation (N=1 =>
// forced serialization => must cross ~100%).
static int  g_wp_cap = -1;                 // N (>0 = active); -1 = uninit, 0 = off
static std::atomic<bool> g_wp_cap_active{false};   // time-gated: off during boot
static std::mutex g_wp_cap_mu;
static std::unordered_map<void*, int> g_wp_cap_started;   // start routine -> #threads ever started
static thread_local int t_wp_excess = -1;          // 1 = this thread is an excess pool worker
static void macapk_wp_cap_init_once() {
    static std::once_flag f;
    std::call_once(f, []{
        const char* e = std::getenv("MACAPK_WP_WORKER_CAP");
        g_wp_cap = e ? std::atoi(e) : 0;
        if (g_wp_cap > 0) {
            const char* s = std::getenv("MACAPK_WP_CAP_START_MS");
            const char* d = std::getenv("MACAPK_WP_CAP_END_MS");
            static long start_ms = s ? std::atol(s) : 6000;    // engage 6s in (past early boot)
            static long end_ms   = d ? std::atol(d) : 130000;  // self-lift at 130s (A/B safety)
            std::fprintf(stderr, "[wp-cap] armed: cap=%d workers/start-routine, ACTIVE window [%ld,%ld]ms\n",
                         g_wp_cap, start_ms, end_ms);
            std::fflush(stderr);
            pthread_t wd;
            pthread_create(&wd, nullptr, [](void*) -> void* {
                struct timespec t1{ (time_t)(start_ms/1000), (long)((start_ms%1000)*1000000) };
                nanosleep(&t1, nullptr);
                g_wp_cap_active.store(true);
                std::fprintf(stderr, "[wp-cap] window OPEN (excess pool workers now park at idle)\n"); std::fflush(stderr);
                struct timespec t2{ (time_t)((end_ms-start_ms)/1000), (long)(((end_ms-start_ms)%1000)*1000000) };
                nanosleep(&t2, nullptr);
                g_wp_cap_active.store(false);
                std::fprintf(stderr, "[wp-cap] window CLOSED (full parallelism restored)\n"); std::fflush(stderr);
                return nullptr;
            }, nullptr);
            pthread_detach(wd);
        }
    });
}
// Close the cap window early (e.g. websocket connected). Also usable by the runtime.
extern "C" void __macapk_wp_cap_lift() { g_wp_cap_active.store(false); }
// Called from cond_wait: should THIS thread (an excess pool worker) stay parked now?
static inline bool macapk_wp_cap_should_park() {
    return g_wp_cap > 0 && t_wp_excess == 1 && g_wp_cap_active.load();
}

static void* macapk_thread_trampoline(void* p) {
    auto* s = static_cast<MacApkThreadStart*>(p);
    void* (*fn)(void*) = s->fn; void* arg = s->arg;
    t_stack_jvm_reserve = s->jvm_reserve;   // 0 unless MACAPK_GUEST_STACK_JVM_RESERVE added one
    delete s;
    // Guest-entry boundary: this is a guest-created thread (Unity worker,
    // cohtml pool, FMOD mixer, ...) about to run guest arm64 code that may use
    // x18 as a GPR. Enable x18 preservation before the guest start routine
    // runs. Must precede fn(arg). See docs/x18-custom-abi-toggle-entitlement_2026-07-14.md.
    macapk_enable_x18_preservation();
    t_pthread_entry = reinterpret_cast<uintptr_t>(fn);
    t_is_guest = 1;   // v1.0.645: mark this as a guest thread (foreign-wake defer)
    // Gated worker cap (time-gated): tag this thread as an "excess" pool worker if its start
    // routine has already started >= N threads. Do NOT park here (boot needs the workers) --
    // excess workers park later at their idle cond_wait, only during the cap window.
    macapk_wp_cap_init_once();
    if (g_wp_cap > 0) {
        std::lock_guard<std::mutex> lk(g_wp_cap_mu);
        int& c = g_wp_cap_started[reinterpret_cast<void*>(fn)];
        t_wp_excess = (c >= g_wp_cap) ? 1 : 0;   // (N+1)th.. instance of a pool = excess
        c++;
    } else {
        t_wp_excess = 0;
    }
    void* rv = fn(arg);
    // (efficiency audit 2026-07-24): the guest tid -> pthread_t /
    // QoS-override registries below are insert-only otherwise -- a
    // thread-churning app (spawn-work-exit per task rather than a bounded
    // pool) leaks one entry per exited thread for the rest of the process
    // lifetime. This is the guest-thread exit boundary (mirrors the
    // guest-entry boundary above): the thread is done running guest code
    // and about to unwind back through pthread_create's trampoline, so
    // its tid can never legitimately be looked up again. Erase here,
    // mirroring g_pthread_objs' existing erase-on-destroy pattern
    // elsewhere in this file. See
    // docs/efficiency-native-runtime-memory_2026-07-24.md Finding 2.
    macapk_unregister_guest_tid();
    return rv;
}
static inline bool oswait_trace_addr(const void* addr) {
    static int on = -1;
    static uintptr_t floor = 0x300000000ull;
    if (on < 0) {
        on = getenv("MACAPK_OSWAIT_TRACE") ? 1 : 0;
        // v1.0.584: the 0x300000000 default is Unity-arena-specific (isolates the
        // GfxDevice handshake). For non-Unity engines (MCPE's RenderDragon task
        // scheduler / Gameface pools) the sync words live in other guest modules
        // or the host heap, so make the floor configurable. MACAPK_OSWAIT_FLOOR=0
        // traces EVERY futex-backed park/wake (cond/mutex/sem) so a stuck
        // producer/consumer handshake can be found by its last-before-silence entry.
        const char* fl = getenv("MACAPK_OSWAIT_FLOOR");
        if (fl) floor = (uintptr_t)strtoull(fl, nullptr, 0);
    }
    return on && reinterpret_cast<uintptr_t>(addr) >= floor;
}
static inline void oswait_log(const char* tag, const void* addr, long extra,
                              uint64_t ra) {
    static std::atomic<int> n{0};
    // v1.0.584: cap configurable (default raised to 5M so a full boot-to-stall
    // trace fits and the LAST handshake before the engine goes quiescent is
    // captured, not truncated mid-boot).
    static int cap = -1;
    if (cap < 0) { const char* c = getenv("MACAPK_OSWAIT_CAP");
                   cap = c ? atoi(c) : 5000000; }
    if (n.fetch_add(1, std::memory_order_relaxed) >= cap) return;
    uint64_t tid = 0; pthread_threadid_np(nullptr, &tid);
    // Cache the pthread name per-thread (cheap after first) so each park/wake is
    // attributable to a role (MINECRAFT MAIN vs a Rendering Pool worker vs
    // Gameface) without a separate tid->name map.
    static thread_local char t_nm[24] = {0};
    static thread_local bool t_nm_set = false;
    if (!t_nm_set) { pthread_getname_np(pthread_self(), t_nm, sizeof t_nm);
                     t_nm_set = true; }
    // ra = the guest caller (subtract the run's module base to get an offset).
    std::fprintf(stderr, "[oswait] %s addr=%p v=%ld tid=%llu nm=%s en=%#lx ra=%#llx\n",
                 tag, addr, extra, (unsigned long long)tid,
                 t_nm[0] ? t_nm : "?", (unsigned long)t_pthread_entry,
                 (unsigned long long)ra);
    std::fflush(stderr);
}
// ERRNO-NEUTRAL, like Bionic's own futex helpers (2026-10-12). bionic/libc/private/
// bionic_futex.h __futex(): `int saved_errno = errno; int result = syscall(__NR_futex, ...);
// if (result == -1) { result = -errno; errno = saved_errno; }` -- so pthread_cond_signal,
// pthread_mutex_unlock, sem_post and friends NEVER change errno on a device. os_sync_wake_*
// sets errno = ENOENT whenever no thread was parked (the common case) and os_sync_wait_*
// sets EINTR/ETIMEDOUT, and those leaked straight into the guest: its errno IS the host
// errno (__errno -> __error). MEASURED on ytdlnis 1.9.0's bundled CPython 3.14: os.listdir
// does `errno = 0; Py_BEGIN_ALLOW_THREADS; ep = readdir(dirp); Py_END_ALLOW_THREADS;
// if (ep == NULL && errno != 0) -> error`, the GIL release in between ran our
// pthread_cond_signal, and the end-of-directory NULL arrived with errno == ENOENT. Every
// listing raised FileNotFoundError, importlib cached each stdlib dir as EMPTY, and the
// interpreter died "Failed to import encodings module". Any guest that reads errno across a
// lock handoff could see the same phantom error.
// The wait helper returns 0 when woken (or the word already moved) and -1 ONLY on its
// deadline, so callers test the RETURN VALUE for a timeout, never errno.
// MACAPK_FUTEX_ERRNO_NEUTRAL=0 is the pre-change behaviour (errno leaks), for a bisect.
static bool macapk_futex_errno_neutral_on() {
    static const bool on = [] {
        const char* e = std::getenv("MACAPK_FUTEX_ERRNO_NEUTRAL");
        return !(e && e[0] == '0');
    }();
    return on;
}
static int macapk_futex_wait_word_raw(int32_t* addr, int32_t val,
                                      uint64_t rel_timeout_ns);
static int macapk_futex_wait_word(int32_t* addr, int32_t val,
                                    uint64_t rel_timeout_ns) {
    const int saved_errno = errno;
    const int r = macapk_futex_wait_word_raw(addr, val, rel_timeout_ns);
    if (macapk_futex_errno_neutral_on()) errno = saved_errno;
    else if (r < 0) errno = ETIMEDOUT;
    return r;
}
static int macapk_futex_wait_word_raw(int32_t* addr, int32_t val,
                                      uint64_t rel_timeout_ns) {
    if (oswait_trace_addr(addr)) {
        // __builtin_return_address(1) (the futex caller's caller, i.e. the
        // real parker) is flagged -Wframe-address as possibly-unsafe if the
        // parent frame was optimized away; this is diagnostic-only (gated on
        // the default-off oswait trace) and the callers are not leaf-collapsed,
        // so the parent frame is present. Accept it locally.
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wframe-address"
        oswait_log("PARK", addr, val, (uint64_t)__builtin_return_address(1));
#pragma clang diagnostic pop
    }
    const uint64_t want = static_cast<uint64_t>(static_cast<uint32_t>(val));
    uint64_t deadline_ns = 0;
    if (rel_timeout_ns) {
        struct timespec mono;
        clock_gettime(CLOCK_MONOTONIC, &mono);
        deadline_ns = uint64_t(mono.tv_sec) * 1000000000ull
                    + uint64_t(mono.tv_nsec) + rel_timeout_ns;
    }
    for (;;) {
        int r;
        if (!deadline_ns) {
            r = os_sync_wait_on_address(addr, want, 4,
                                        OS_SYNC_WAIT_ON_ADDRESS_NONE);
        } else {
            struct timespec mono;
            clock_gettime(CLOCK_MONOTONIC, &mono);
            const uint64_t now = uint64_t(mono.tv_sec) * 1000000000ull
                               + uint64_t(mono.tv_nsec);
            if (now >= deadline_ns) { errno = ETIMEDOUT; return -1; }
            r = os_sync_wait_on_address_with_timeout(
                    addr, want, 4, OS_SYNC_WAIT_ON_ADDRESS_NONE,
                    OS_CLOCK_MACH_ABSOLUTE_TIME, deadline_ns - now);
        }
        if (r >= 0) return 0;            // woken, or *addr != want (no block)
        const int e = errno;
        if (e == ETIMEDOUT) return -1;
        if (e == EINTR || e == EFAULT || e == ENOMEM) {
            // Spurious / transient early-return: reload and re-check, exactly
            // like the raw-futex path.
            if (__atomic_load_n(addr, __ATOMIC_RELAXED) != val) return 0;
            continue;
        }
        // EINVAL/unexpected (e.g. an address os_sync can't handle): degrade to
        // a bounded yield so we neither hard-spin a core nor silently lose a
        // wake. If the word never changes this becomes the old yield-spin
        // (no worse than before) rather than a hang.
        sched_yield();
        if (__atomic_load_n(addr, __ATOMIC_RELAXED) != val) return 0;
    }
}
static inline int macapk_futex_wake_word(int32_t* addr, bool all) {
    if (oswait_trace_addr(addr)) {
        // See the -Wframe-address note in macapk_futex_wait_word above:
        // diagnostic-only, parent frame present, accept the nonzero level.
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wframe-address"
        oswait_log(all ? "WAKEall" : "WAKEany", addr, 0,
                   (uint64_t)__builtin_return_address(1));
#pragma clang diagnostic pop
    }
    // Return the os_sync result so the MACAPK_MUTEX_HANDOFF revoke (unlock U3/U4) can learn
    // whether a waiter was actually parked: 0 == woke >= 1 waiter; -1 == nobody woken (errno
    // ENOENT per os_sync_wait_on_address.h). All non-handoff callers discard the value.
    // Errno-neutral: see macapk_futex_wait_word.
    const int saved_errno = errno;
    const int r = all ? os_sync_wake_by_address_all(addr, 4, OS_SYNC_WAKE_BY_ADDRESS_NONE)
                      : os_sync_wake_by_address_any(addr, 4, OS_SYNC_WAKE_BY_ADDRESS_NONE);
    if (macapk_futex_errno_neutral_on()) errno = saved_errno;
    return r;
}
// v1.0.645: foreign-wake defer window in microseconds (MACAPK_FOREIGN_WAKE_DEFER_US,
// 0/unset = off). See __macapk_arm64_pthread_cond_signal for the rationale
// (Android wakeup-granularity emulation for host->guest condvar wakes).
static inline int macapk_foreign_wake_defer_us() {
    static int v = -1;
    if (v < 0) {
        const char* e = std::getenv("MACAPK_FOREIGN_WAKE_DEFER_US");
        v = e ? std::atoi(e) : 0;
        if (v < 0) v = 0;
    }
    return v;
}
// v1.0.645: perform the foreign-wake defer (Android wakeup-granularity emulation)
// iff the caller is a HOST thread. Called from cond_signal (always) and
// cond_broadcast (gated on MACAPK_FOREIGN_WAKE_DEFER_BCAST, since the guest's
// WorkerPool notify primitive turned out to be broadcast-heavy, not signal --
// 4 vs 124 in a boot trace). The counter bump has already happened at the call
// site, so a barging (running) popper still sees the new state immediately;
// only a PARKED waiter's wake is held back by G us, reproducing the Bionic/CFS
// wakeup-granularity window the guest producer/consumer code depends on.
static inline void macapk_foreign_wake_maybe_defer(const int32_t* c,
                                                   const char* tag) {
    const int g = macapk_foreign_wake_defer_us();
    if (g <= 0 || t_is_guest != 0) return;   // only HOST-originated wakes
    struct timespec ts = { g / 1000000, (long)(g % 1000000) * 1000 };
    nanosleep(&ts, nullptr);
    if (macapk_envp("MACAPK_FUTEX_TRACE")) {
        static std::atomic<int> dn{0};
        if (dn.fetch_add(1) < 400) {
            uint64_t tid = 0; pthread_threadid_np(nullptr, &tid);
            std::fprintf(stderr, "[fwake-defer] %s c=%p G=%dus host-tid=%llu\n",
                         tag, (void*)c, g, (unsigned long long)tid);
            std::fflush(stderr);
        }
    }
}
// Bionic pthread_cond_timedwait's abstime is a 16-byte timespec
// {int64 tv_sec; int64 tv_nsec}. The clock is CLOCK_REALTIME by default but
// il2cpp's os::Event/Semaphore set CLOCK_MONOTONIC via pthread_condattr_setclock
// (which we don't plumb through). Disambiguate at the call: compute the delta
// against each plausible clock and take the non-negative, smaller one. The
// candidates differ by decades (REALTIME ~1.7e9 s epoch, host MONOTONIC
// days-large uptime, REBASED guest MONOTONIC ~process seconds), so the wrong
// clock yields an absurd or negative delta -- the right one is the small
// non-negative value. The guest candidate matters because the clock shim
// rebases the MONOTONIC family process-relative (clock_rebase_enabled): a
// guest deadline of "guest now + 5 s" (~500 s) compared only against the host
// clocks would always look expired -> spurious instant ETIMEDOUT. Returns 0
// if the deadline is already in the past (caller -> ETIMEDOUT).
// stamped_clock: which clock the caller KNOWS the deadline is expressed on --
// 0 = unknown (use the magnitude heuristic below), 1 = CLOCK_REALTIME,
// 2 = CLOCK_MONOTONIC. pthread_cond_init records the clock the app selected
// via pthread_condattr_setclock (bionic pthread_cond.cpp: COND_CLOCK_MASK,
// default CLOCK_REALTIME when attr is NULL), so a cond whose clock was
// explicitly chosen no longer has to be guessed at from the value's magnitude.
static uint64_t macapk_abstime_to_rel_ns(const void* abstime,
                                         int stamped_clock = 0) {
    const int64_t* ts = reinterpret_cast<const int64_t*>(abstime);
    struct timespec rt, mo, gm;
    clock_gettime(CLOCK_REALTIME, &rt);
    // The host monotonic candidate must be the clock the guest's own CLOCK_MONOTONIC
    // is read from (CLOCK_UPTIME_RAW under MACAPK_GUEST_CLOCK_NANOTIME): the macOS
    // CLOCK_MONOTONIC sits seconds (or, after a host sleep, hours) away from it, and
    // "smaller non-negative candidate" would then turn an EXPIRED guest deadline into a
    // multi-second park.
    macapk_host_mono_for_guest(&mo);
    // Rebased only under =0 / MACAPK_CLOCK_REBASE=1 (clock_rebase_enabled); under the
    // default MACAPK_GUEST_CLOCK_NANOTIME this IS System.nanoTime()'s clock, unrebased.
    __macapk_arm64_clock_gettime(1 /*CLOCK_MONOTONIC*/, &gm);
    const int64_t rel_rt = (ts[0] - int64_t(rt.tv_sec)) * 1000000000ll
                         + (ts[1] - int64_t(rt.tv_nsec));
    const int64_t rel_mo = (ts[0] - int64_t(mo.tv_sec)) * 1000000000ll
                         + (ts[1] - int64_t(mo.tv_nsec));
    const int64_t rel_gm = (ts[0] - int64_t(gm.tv_sec)) * 1000000000ll
                         + (ts[1] - int64_t(gm.tv_nsec));
    // Epoch-domain disambiguation (fixes the expired-CLOCK_REALTIME 250ms
    // mis-park, v1.0.620 / rank 2 of the scheduling RCA): a REALTIME abstime has
    // ts[0] in the wall-clock epoch (> ~1e9 s == after 2001); host and guest
    // MONOTONIC deadlines are uptime/process-relative (far smaller -- a Mac is
    // never up 1e9 s == 31 y, and the guest clock is rebased process-relative).
    // So when ts[0] is a wall-clock time this is unambiguously a REALTIME
    // deadline: use ONLY rel_rt, and if it is already past return 0 (immediate
    // ETIMEDOUT). Without this, an EXPIRED realtime deadline made rel_rt negative
    // (excluded) while rel_mo/rel_gm were ~56 years positive, so the min-positive
    // loop picked the absurd value and the caller's >30-day clamp turned it into a
    // 250 ms spurious park returning 0 -- where Bionic returns ETIMEDOUT instantly
    // with zero park. libc++ condition_variable::__do_timed_wait uses system_clock
    // (== CLOCK_REALTIME) abstimes, which is exactly this family, so a worker whose
    // wait_until deadline expired while CPU-starved paid a 250 ms penalty per poll
    // cycle -> collapsed poll cadence (see
    // docs/mcpe-localization-scheduling-rootcause_2026-07-13.md).
    if (ts[0] > 1000000000ll) return rel_rt > 0 ? uint64_t(rel_rt) : 0;
    // Not a wall-clock magnitude. If the app EXPLICITLY selected
    // CLOCK_MONOTONIC for this cond, drop rel_rt from the candidate set: the
    // deadline is monotonic by construction, so the only remaining question is
    // host uptime vs our process-rebased guest monotonic (a guest that built
    // the deadline through our clock_gettime shim gets the rebased epoch; one
    // that reached the host clock directly gets uptime). Picking the smaller
    // non-negative of those two is strictly narrower than the three-way guess.
    // The magnitude test above still wins so a CLOCK_MONOTONIC-stamped cond
    // handed a wall-clock abstime (bionic's pthread_cond_timedwait_monotonic_np
    // and friends cross the two) is not mis-scaled.
    if (stamped_clock == 2) {
        int64_t mono = -1;
        for (int64_t cand : {rel_mo, rel_gm})
            if (cand >= 0 && (mono < 0 || cand < mono)) mono = cand;
        return mono < 0 ? 0 : uint64_t(mono);
    }
    int64_t chosen = -1;
    for (int64_t cand : {rel_rt, rel_mo, rel_gm})
        if (cand >= 0 && (chosen < 0 || cand < chosen)) chosen = cand;
    if (chosen < 0) return 0;  // all past -> already expired
    return uint64_t(chosen);
}

extern "C" int __macapk_arm64_pthread_mutex_init(int32_t* m, const void* attr) {
    if (!m) return 22;
    for (int i = 0; i < 10; ++i) m[i] = 0;
    // Our pthread_mutexattr_settype stores the Bionic type int at attr[0].
    if (attr) {
        int32_t type = __atomic_load_n(&reinterpret_cast<const int32_t*>(attr)[0],
                                       __ATOMIC_RELAXED);
        if (type == 1 || type == 2) m[kMutexTypeSlot] = type;
    }
    __atomic_store_n(&m[kMutexMagicSlot], int32_t(kMacApkMutexMagic),
                     __ATOMIC_RELEASE);
    // One-time heartbeat so we can confirm the arm64-native loader is
    // routing pthread_mutex_init to this shim rather than libSystem's
    // (which would write past the end of the Bionic-sized struct).
    static std::atomic<bool> logged{false};
    bool exp = false;
    if (logged.compare_exchange_strong(exp, true)) {
        std::fprintf(stderr,
            "[arm64-shim] first pthread_mutex_init called (m=%p)\n",
            (void*)m);
        std::fflush(stderr);
    }
    return 0;
}
extern "C" int __macapk_arm64_pthread_mutex_destroy(int32_t* m) {
    if (!m) return 22;
    if (!macapk_arm64_mutex_ensure_valid(m)) return 22;
    if (macapk_mutex_owner_aware()) {
        // Owner-aware path: m[0] holds a mach-port owner, not the 0/1/2 futex word,
        // so the 0xffff sentinel + os_sync wake do not apply. Invalidate via the
        // magic slot (ensure_valid then returns EINVAL) and wake any parked
        // UL_UNFAIR_LOCK waiter so it re-checks and returns EINVAL rather than
        // blocking forever. (Destroying a contended mutex is UB; one wake suffices.)
        __atomic_store_n(&m[kMutexMagicSlot], 0, __ATOMIC_RELEASE);
        __atomic_store_n(reinterpret_cast<uint32_t*>(&m[0]), 0, __ATOMIC_RELEASE);
        __ulock_wake(kUL_UNFAIR_LOCK | kULF_WAKE_ALLOW_NON_OWNER | kULF_NO_ERRNO, &m[0], 0);
        return 0;
    }
    __atomic_store_n(&m[0], int32_t(kBionicMutexDestroyed),
                     __ATOMIC_RELEASE);
    __atomic_store_n(&m[kMutexMagicSlot], 0, __ATOMIC_RELEASE);
    // Wake any thread still parked in lock() so it observes the destroyed
    // sentinel and returns EINVAL rather than blocking forever (the word
    // moved off 2, but os_sync only re-evaluates on an explicit wake).
    macapk_futex_wake_word(&m[0], /*all=*/true);
    return 0;
}
