        static long fboot_ms;            // boot-window length in ms; default 90000
        static bool fboot_init = false;
        if (!fboot_init) { const char* eu = std::getenv("MACAPK_FAIR_BOOT_US");
                           int u = eu ? std::atoi(eu) : 50000; if (u < 0) u = 0; fboot_us = (unsigned)u;
                           fboot_ms = macapk_fair_boot_window_ms();   // MACAPK_FAIR_BOOT_RETIRED, above
                           fboot_init = true; }
