// AAudioStream_getTimestamp(stream, clockid, framePosition, timeNanoseconds)
// -- "Timestamps are only valid when the stream is in
// AAUDIO_STREAM_STATE_STARTED"; otherwise the documented answer is
// AAUDIO_ERROR_INVALID_STATE. aaudio_result_t values, verified from
// frameworks/av media/libaaudio/include/aaudio/AAudio.h:
//   AAUDIO_OK 0, AAUDIO_ERROR_BASE -900, _DISCONNECTED -899,
//   _ILLEGAL_ARGUMENT -898, _INTERNAL -896, _INVALID_STATE -895,
//   _INVALID_HANDLE -892, _UNIMPLEMENTED -890.
// A bare -1 (the old return) is not in that family at all, so a caller
// matching a named constant could never classify the failure.
//
// The frame position is the count the playback feeder has actually pushed, and
// the time is read through our own clock_gettime shim so it lands in the SAME
// (process-rebased) CLOCK_MONOTONIC epoch the guest's own clock_gettime
// returns -- an A/V-sync caller differences the two, so mixing epochs here
// would reproduce the vsync frameTimeNanos defect on the audio clock.
extern "C" int macapk_AAudioStream_getTimestamp(void* st, int clockid,
                                                int64_t* framePosition,
                                                int64_t* timeNanoseconds) {
    AAudioStreamImpl* s = (AAudioStreamImpl*)st;
    if (!s || !framePosition || !timeNanoseconds) return -898;
    if (!s->running.load(std::memory_order_relaxed)) return -895;
    struct timespec ts;
    ts.tv_sec = 0; ts.tv_nsec = 0;
    __macapk_arm64_clock_gettime(clockid ? clockid : 1 /*CLOCK_MONOTONIC*/, &ts);
    *framePosition   = s->frames_written;
    *timeNanoseconds = (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
    return 0;   // AAUDIO_OK
}
extern "C" bool macapk_AAudioStream_isMMapUsed(void*) { return false; }
extern "C" int  macapk_AAudioStream_requestFlush(void*) { return 0; }
extern "C" int  macapk_AAudioStream_requestPause(void* st) {
    AAudioStreamImpl* s = (AAudioStreamImpl*)st;
    if (!s) return 0;
    // PAUSED: the feeder stops STARTING new callbacks (the AAudio contract
    // FMOD relies on to reconfigure its mix graph during a scene change).
    // The feeder thread stays alive and resumes on the next requestStart.
    // An in-flight callback is drained by waitForStateChange below.
    s->state.store(6, std::memory_order_release);   // PAUSED
    if (aaudio_rt_ready() && s->handle) g_rt_stop(s->handle);
    std::fprintf(stderr, "[aaudio] requestPause h=%lld\n", (long long)s->handle);
    return 0;
}
// AAudio: wait until the stream leaves `inputState`, returning the new state.
// CRITICAL: when entering a quiescent state (PAUSED/STOPPED) we must not
// return until any IN-FLIGHT callback has finished -- the guest (FMOD) calls
// this after requestPause/Stop and then reconfigures its mix graph; returning
// while the callback still runs is exactly the race that crashed Crossy.
extern "C" int  macapk_AAudioStream_waitForStateChange(void* st, int inputState,
                                                         int* next, int64_t timeoutNs) {
    AAudioStreamImpl* s = (AAudioStreamImpl*)st;
    if (!s) { if (next) *next = 4; return 0; }
    int64_t budget = timeoutNs > 0 ? timeoutNs : (int64_t)2 * 1000 * 1000 * 1000;
    int64_t waited = 0;
    const int64_t step = 1 * 1000 * 1000;   // 1 ms
    for (;;) {
        int cur = s->state.load(std::memory_order_acquire);
        bool quiescent = (cur == 6 || cur == 10);   // PAUSED / STOPPED
        bool drained = !s->in_cb.load(std::memory_order_acquire);
        if (cur != inputState && (!quiescent || drained)) {
            if (next) *next = cur;
            return 0;
        }
        if (waited >= budget) { if (next) *next = cur; return 0; }
        struct timespec ts{0, step}; nanosleep(&ts, nullptr);
        waited += step;
    }
}
extern "C" int  macapk_AAudioStream_write(void* st, const void* buffer, int numFrames, int64_t /*timeoutNs*/) {
    AAudioStreamImpl* s = (AAudioStreamImpl*)st;
    if (!s || numFrames <= 0 || !buffer) return 0;
    if (!aaudio_rt_ready() || !s->handle) return numFrames;   // swallow, never block
    int wrote = 0;
    int nelem = numFrames * s->channels;
    // blocking=true: AAudioStream_write's own guest-facing contract in
    // WRITE mode is a blocking call paced to the ring's backpressure (see
    // the file header); unchanged by the v1.0.989 ABI addition.
    if (s->format == 2) wrote = g_rt_write_f(s->handle, (const float*)buffer, nelem, true);
    else                wrote = g_rt_write_s(s->handle, (const int16_t*)buffer, nelem, true);
    s->frames_written += numFrames;
    return s->channels > 0 ? wrote / s->channels : numFrames;
}
extern "C" const char* macapk_AAudio_convertResultToText(int) { return "AAUDIO_OK"; }
extern "C" int  macapk_AAudio_setMMapPolicy(int /*policy*/) { return 0; }

// ---- MACAPK_AAUDIO_FPDC (default ON; =0 restores the pre-change table) ----
// Three symbols a real libaaudio.so exports that this table used to answer
// with macapk_aaudio_unimpl_stub (-890). MEASURED on dev.serwin.AnarchRE
// (docs/fleet-misc-rocks-frozen-sgt-anarch_2026-09-26.md F2): its libSDL3.so
// dlsym's all three; SDL3's BuildAAudioStream (src/audio/aaudio/SDL_aaudio.c,
// release-3.2.x) calls AAudioStream_getFramesPerDataCallback right after a
// successful openStream and uses the answer as device->sample_frames, so -890
// failed the device format + mix-buffer setup and the stream was stopped
// before it ever started: no audio at all, where a device plays.
// Contracts, from the NDK's own aaudio/AAudio.h (API 26/28) and AOSP android14
// frameworks/av media/libaaudio/src/core/{AAudioAudio,AudioGlobal,AudioStream}.cpp:
//   getFramesPerDataCallback: "If a specific size was requested by calling
//     AAudioStreamBuilder_setFramesPerDataCallback() then this will be the same
//     size. If ... not called then this will return the size chosen by AAudio,
//     or AAUDIO_UNSPECIFIED." AAudioAudio.cpp returns
//     audioStream->getFramesPerDataCallback(), the builder copy made in open.
//   convertStreamStateToText: AudioGlobal_convertStreamStateToText, a switch of
//     AAUDIO_CASE_ENUM(name) -> "#name" over the 14 states, else "Unrecognized".
//   setInputPreset: a builder setter (streamBuilder->setInputPreset).
static bool macapk_aaudio_fpdc_on() {
    static const bool on = [] {
        const char* e = std::getenv("MACAPK_AAUDIO_FPDC");
        return !(e && e[0] == '0');
    }();
    return on;
}
extern "C" int macapk_AAudioStream_getFramesPerDataCallback(void* st) {
    return st ? ((AAudioStreamImpl*)st)->frames_per_data_callback : 0;
}
extern "C" const char* macapk_AAudio_convertStreamStateToText(int state) {
    // aaudio_stream_state_t, NDK AAudio.h: UNINITIALIZED = 0 then consecutive.
    static const char* const kNames[] = {
        "AAUDIO_STREAM_STATE_UNINITIALIZED", "AAUDIO_STREAM_STATE_UNKNOWN",
        "AAUDIO_STREAM_STATE_OPEN",          "AAUDIO_STREAM_STATE_STARTING",
        "AAUDIO_STREAM_STATE_STARTED",       "AAUDIO_STREAM_STATE_PAUSING",
        "AAUDIO_STREAM_STATE_PAUSED",        "AAUDIO_STREAM_STATE_FLUSHING",
        "AAUDIO_STREAM_STATE_FLUSHED",       "AAUDIO_STREAM_STATE_STOPPING",
        "AAUDIO_STREAM_STATE_STOPPED",       "AAUDIO_STREAM_STATE_CLOSING",
        "AAUDIO_STREAM_STATE_CLOSED",        "AAUDIO_STREAM_STATE_DISCONNECTED",
    };
    if (state >= 0 && state < (int)(sizeof kNames / sizeof kNames[0]))
        return kNames[state];
    return "Unrecognized";
}
extern "C" void macapk_AAudioStreamBuilder_setInputPreset(void* b, int preset) {
    if (b) ((AAudioBuilder*)b)->input_preset = preset;
}

