static SLresult sl_play_GetPosition(void*, void* p) { if (p) *(SLuint32*)p = 0; return SL_OK; }
// Real store (was a no-op stub that discarded cb/ctx): SoLoud's OpenSL ES
// backend (soloud_opensles.cpp, confirmed live on Mindustry's libarc.so)
// registers its buffer-completion callback HERE, on the PLAY interface --
// not on the BufferQueue interface's own RegisterCallback (sl_bq_
// RegisterCallback / bq_cb) the way Oboe/OpenAL Soft/the classic NDK sample
// do. Discarding it silently here is why that refill pattern never worked:
// see sl_bq_Enqueue / sl_feeder for where play_cb actually gets invoked.
static SLresult sl_play_RegisterCallback(void* self, void* cb, void* ctx) {
    SLObj* p = ((SLItfHeader*)self)->owner;
    if (p) { p->play_cb = (slPlayCallback)cb; p->play_cb_ctx = ctx; }
    return SL_OK;
}
static SLresult sl_play_GetMask(void*, void* p) { if (p) *(SLuint32*)p = 0; return SL_OK; }
static SLresult sl_play_ClearMarker(void*) { return SL_OK; }
// Real store (was sharing the generic sl_play_ret0_1u no-op). SoLoud calls
// this with SL_PLAYEVENT_HEADATEND immediately after RegisterCallback
// (soloud_opensles.cpp opensles_init); without recording the mask here
// sl_bq_Enqueue has no way to know the guest actually wants the event.
static SLresult sl_play_SetCallbackEventsMask(void* self, SLuint32 mask) {
    SLObj* p = ((SLItfHeader*)self)->owner;
    if (p) p->play_cb_mask = mask;
    return SL_OK;
}
