// ---- SLVolumeItf ----
static SLresult sl_vol_SetVolumeLevel(void* self, int level) {
    SLObj* p = ((SLItfHeader*)self)->owner;
    if (p && aaudio_rt_ready() && p->handle) {
        // OpenSL level is millibels (1/100 dB); convert to linear gain.
        float gain = level <= -9600 ? 0.0f : powf(10.0f, level / 2000.0f);
        typedef void (*setvol_fn)(int64_t, float, float);
        static setvol_fn sv = (setvol_fn)dlsym(RTLD_DEFAULT, "macapk_audio_stream_set_volume");
        if (sv) sv(p->handle, gain, gain);
    }
    return SL_OK;
}
