// ---- SLEngineItf ----
static SLresult sl_eng_CreateOutputMix(void* self, void* pMix, SLuint32,
                                       const void*, const void*) {
    (void)self;
    if (!pMix) return SL_OK;
    SLObj* m = new SLObj();
    m->objVtable = sl_obj_vtable_ptr();
    m->type = SLOBJ_OUTPUTMIX;
    *(void**)pMix = m;
    return SL_OK;
}
static SLresult sl_eng_CreateAudioPlayer(void* self, void* pPlayer,
        void* pAudioSrc, void* pAudioSnk, SLuint32, const void*, const void*) {
    (void)self; (void)pAudioSnk;
    if (!pPlayer) return SL_OK;
    SLObj* p = new SLObj();
    p->objVtable = sl_obj_vtable_ptr();
    p->type = SLOBJ_PLAYER;
    SLDataSource* src = (SLDataSource*)pAudioSrc;
    // numBuffers of the buffer-queue locator sizes the queue, as in AOSP
    // IEngine_CreateAudioPlayer ("nbBuffers = (SLuint16) thiz->mDataSource.
    // mLocator.mBufferQueue.numBuffers" for SL_DATALOCATOR_BUFFERQUEUE (0x6) and
    // SL_DATALOCATOR_ANDROIDSIMPLEBUFFERQUEUE (0x800007BD); both locators are
    // {SLuint32 locatorType; SLuint32 numBuffers;} in OpenSLES(_Android).h).
    // AOSP refuses numBuffers >= 256 (initializeBufferQueueMembers); a zero
    // or other locator keeps 2 so a malformed request still gets a queue.
    p->bq_num_buffers = 2;
    if (src && src->pLocator) {
        const SLuint32* loc = (const SLuint32*)src->pLocator;
        if ((loc[0] == 0x00000006u || loc[0] == 0x800007BDu) && loc[1] >= 1 && loc[1] < 256)
            p->bq_num_buffers = loc[1];
    }
    p->bq_ring.assign(p->bq_num_buffers, SLObj::BQBuf{nullptr, 0});
    if (src && src->pFormat) {
        SLDataFormat_PCM* fmt = (SLDataFormat_PCM*)src->pFormat;
        if (fmt->formatType == 2 /*SL_DATAFORMAT_PCM*/) {
            int ch = (int)fmt->numChannels;
            p->channels = ch < 1 ? 2 : (ch > 2 ? 2 : ch);
            int sr = (int)(fmt->samplesPerSec / 1000);   // milliHz -> Hz
            p->sample_rate = (sr >= 4000 && sr <= 192000) ? sr : 44100;
            p->format = (fmt->bitsPerSample == 32) ? 2 : 1;
        }
    }
    *(void**)pPlayer = p;
    std::fprintf(stderr, "[opensl] CreateAudioPlayer ch=%d sr=%d fmt=%s buffers=%u\n",
                 p->channels, p->sample_rate, p->format == 2 ? "F32" : "I16",
                 (unsigned)p->bq_num_buffers);
    return SL_OK;
}
