// ---- SLObjectItf ----
static SLresult sl_obj_Realize(void* self, SLuint32) {
    SLObj* o = (SLObj*)self;
    o->realized = 1;
    if (o->type == SLOBJ_PLAYER && o->handle == 0 && aaudio_rt_ready()) {
        int enc = (o->format == 2) ? 4 : 2;
        // frameCount 0, as AOSP's OpenSL ES player creates its AudioTrack
        // (frameworks/wilhelm src/android/AudioPlayer_to_android.cpp:1650,
        // "0, // frameCount"): AudioFlinger then gives it the platform
        // minimum, and the app's own queued buffers are the rest of its
        // buffering. This used to be 4096, which the runtime floored to
        // ~340 ms of queued audio (MACAPK_AUDIO_AOSP_FRAMECOUNT).
        o->handle = g_rt_create(o->sample_rate, o->channels, enc, 0);
        if (sl_trace())
            std::fprintf(stderr, "[opensl] player Realize -> stream h=%lld\n",
                         (long long)o->handle);
    }
    if (o->type == SLOBJ_PLAYER && o->handle == 0 && macapk_audio_honest_open()) {
        // No engine stream: answer like android_audioPlayer_realize on a
        // device whose AudioTrack failed initCheck, and stay UNREALIZED as
        // IObject_Realize leaves a failed object (see macapk_audio_honest_open).
        // A later Realize retries the open, as it may on a device.
        o->realized = 0;
        // Marks the player so GetInterface(SL_IID_PLAY) also refuses (see
        // sl_obj_GetInterface) -- otherwise an app that ignores this return
        // value but checks GetInterface would still be handed a live
        // SLPlayItf over a dead player.
        o->realize_failed = true;
        std::fprintf(stderr,
            "[opensl] player Realize sr=%u ch=%u -> FAILED %u "
            "(SL_RESULT_CONTENT_UNSUPPORTED): no host output stream "
            "(MACAPK_AUDIO_HONEST_OPEN)\n",
            (unsigned)o->sample_rate, (unsigned)o->channels,
            (unsigned)SL_CONTENT_UNSUPPORTED);
        return SL_CONTENT_UNSUPPORTED;
    }
    o->realize_failed = false;
    return SL_OK;
}
static SLresult sl_obj_GetState(void* self, SLuint32* pState) {
    SLObj* o = (SLObj*)self;
    if (pState) *pState = o->realized ? 2 : 1;   // REALIZED=2 / UNREALIZED=1
    return SL_OK;
}
static SLresult sl_obj_GetInterface(void* self, const void* iid, void* pInterface) {
    SLObj* o = (SLObj*)self;
    void** out = (void**)pInterface;
    if (!out) return SL_UNSUPPORTED;
    // AOSP (wilhelm src/itf/IObject.c, IObject_GetInterface, fetched from the
    // LineageOS mirror 2026-09-28): "if ((SL_OBJECT_STATE_REALIZED !=
    // thiz->mState) && !(INTERFACE_PREREALIZE & clazz->mInterfaces[index].
    // mInterface)) result = SL_RESULT_PRECONDITIONS_VIOLATED;" and
    // *pInterface stays untouched (NULL). ANDROIDCONFIGURATION carries
    // INTERFACE_PREREALIZE on a real device (it is meant to be configured
    // before Realize), so it stays gettable here too; every other interface
    // on a player whose Realize failed is refused instead of handed out
    // live, matching a device that never leaves SL_OBJECT_STATE_UNREALIZED.
    if (o->type == SLOBJ_PLAYER && o->realize_failed && macapk_audio_honest_open() &&
        !sl_iid_eq(iid, &kMacSlGuidAndroidcfg)) {
        *out = nullptr;
        return SL_PRECONDITIONS_VIOLATED;
    }
    if (sl_iid_eq(iid, &kMacSlGuidEngine)) { o->engineItf.vtable = &g_sl_eng_vtable; o->engineItf.owner = o; *out = &o->engineItf; return SL_OK; }
    if (sl_iid_eq(iid, &kMacSlGuidPlay))   { o->playItf.vtable = &g_sl_play_vtable; o->playItf.owner = o; *out = &o->playItf; return SL_OK; }
    if (sl_iid_eq(iid, &kMacSlGuidAndroidbq) || sl_iid_eq(iid, &kMacSlGuidBufferq)) { o->bqItf.vtable = &g_sl_bq_vtable; o->bqItf.owner = o; *out = &o->bqItf; return SL_OK; }
    if (sl_iid_eq(iid, &kMacSlGuidVolume)) { o->volumeItf.vtable = &g_sl_vol_vtable; o->volumeItf.owner = o; *out = &o->volumeItf; return SL_OK; }
    if (sl_iid_eq(iid, &kMacSlGuidAndroidcfg)) { o->cfgItf.vtable = &g_sl_cfg_vtable; o->cfgItf.owner = o; *out = &o->cfgItf; return SL_OK; }
    {
        const uint8_t* b = (const uint8_t*)iid;
        std::fprintf(stderr,
            "[opensl] GetInterface unsupported iid=%p obj=%d bytes="
            "%02x%02x%02x%02x %02x%02x %02x%02x %02x%02x %02x%02x%02x%02x%02x%02x\n",
            iid, (int)o->type,
            b[0],b[1],b[2],b[3], b[4],b[5], b[6],b[7], b[8],b[9],
            b[10],b[11],b[12],b[13],b[14],b[15]);
    }
    return SL_UNSUPPORTED;
}
static void sl_obj_Destroy(void* self) {
    SLObj* o = (SLObj*)self;
    if (!o) return;
    o->feeder_running.store(false, std::memory_order_relaxed);
    if (o->feeder_started) { pthread_join(o->feeder, nullptr); o->feeder_started = false; }
    if (o->type == SLOBJ_PLAYER && aaudio_rt_ready() && o->handle) g_rt_release(o->handle);
    delete o;
}
