        case 61:  return __macapk_arm64_getdents64((int)a1, (void*)macapk_untag_ptr((void*)a2), (size_t)a3);  // getdents64
        // 172/173/174/175/176/177 were NOT wired, so a guest using the RAW svc path (which
        // pairip does deliberately, to dodge libc hooks) got -1 from getpid() -- a value no
        // device ever returns. Measured in the syscall census at dispatch record 1371.
        // 173 (getppid) is already handled by the ptrace-emulation block below; the rest of
        // the id family was NOT wired, so a guest using the RAW svc path (which pairip does
        // deliberately, to dodge libc hooks) got -1 from getpid() -- a value no device ever
        // returns. Measured in the syscall census at dispatch record 1371.
        case 172: return (long)getpid();                       // getpid
        case 174: return (long)getuid();                       // getuid
        case 175: return (long)geteuid();                      // geteuid
        case 176: return (long)getgid();                       // getgid
        case 177: return (long)getegid();                      // getegid
        case 62:  return (long)__macapk_arm64_lseek64((int)a1, (off_t)a2, (int)a3);  // lseek
        case 59:  return (long)__macapk_arm64_pipe2((int*)a1, (int)a2);  // pipe2
        // read/pread64/pwrite64 call the HOST-errno cores: their exported faces
        // answer in Linux errno since 2026-09-28 (MACAPK_RW_ERRNO_LINUX), and this
        // router's contract is host errno (translated once by the face above).
        case 63:  return (long)macapk_arm64_read_host((int)a1, (void*)macapk_untag_ptr((void*)a2), (size_t)a3);  // read
        // 64 write (asm-generic/unistd.h: `#define __NR_write 64`), added
        // 2026-09-28. Instagram's libappstatelogger2 records "terminated by
        // signal" from INSIDE its SIGTERM handler with a raw svc write (the
        // async-signal-safe form), and this router answered -ENOSYS: the app
        // logged "Error writing to app state log file" on every SIGTERM, so the
        // state file never recorded a clean termination. The host-errno core, so
        // a raw write to an eventfd adds to its counter like libc write() does.
        // MACAPK_ROUTER_WRITE=0: the old -ENOSYS, byte-identical to the pre-fix
        // tree (macapk_router_unimplemented is the SAME body the default case
        // below runs, so the log line and the fetch_add(1) slot count match
        // exactly what an unshimmed nr=64 produced before this case existed).
        case 64:  if (!macapk_router_write_on())
                      return macapk_router_unimplemented(number, __builtin_return_address(0));
                  return (long)macapk_write_host((int)a1, (const void*)macapk_untag_ptr((void*)a2), (size_t)a3);  // write
        case 67:  return (long)::pread((int)a1, (void*)macapk_untag_ptr((void*)a2), (size_t)a3, (off_t)a4);  // pread64
        case 68:  return (long)::pwrite((int)a1, (const void*)a2, (size_t)a3, (off_t)(int64_t)a4);  // pwrite64
        case 78:  return (long)__macapk_arm64_readlinkat((int)a1, (const char*)macapk_untag_ptr((void*)a2), (char*)macapk_untag_ptr((void*)a3), (size_t)a4);  // readlinkat
        case 79:  return (long)__macapk_arm64_fstatat((int)a1, (const char*)macapk_untag_ptr((void*)a2), (BionicStat*)macapk_untag_ptr((void*)a3), (int)a4);  // fstatat
        case 80:  return (long)__macapk_arm64_fstat((int)a1, (BionicStat*)macapk_untag_ptr((void*)a2));  // fstat
        case 115:  return (long)__macapk_arm64_clock_nanosleep((int)a1, (int)a2, (const struct timespec*)a3, (struct timespec*)macapk_untag_ptr((void*)a4));  // clock_nanosleep
        case 118:  return (long)__macapk_arm64_sched_setparam((pid_t)a1, (const void*)a2);  // sched_setparam
        case 120:  return (long)__macapk_arm64_sched_getscheduler((pid_t)a1);  // sched_getscheduler
        case 121:  return (long)__macapk_arm64_sched_getparam((pid_t)a1, (void*)macapk_untag_ptr((void*)a2));  // sched_getparam
        case 124:  return (long)__macapk_arm64_sched_yield();  // sched_yield
        case 140:  return (long)__macapk_arm64_setpriority((int)a1, (int)a2, (int)a3);  // setpriority
        case 160:  return (long)__macapk_arm64_uname((void*)macapk_untag_ptr((void*)a1));  // uname
        case 167:  return (long)__macapk_arm64_prctl((int)a1, (unsigned long)a2, (unsigned long)a3, (unsigned long)a4, (unsigned long)a5);  // prctl
        case 179:  return (long)__macapk_arm64_sysinfo((void*)macapk_untag_ptr((void*)a1));  // sysinfo
        case 198:  return macapk_router_from_linux((long)__macapk_arm64_socket((int)a1, (int)a2, (int)a3));  // socket
        case 200:  return macapk_router_from_linux((long)__macapk_arm64_bind((int)a1, (const struct sockaddr*)a2, (socklen_t)a3));  // bind
        case 202:  return macapk_router_from_linux((long)__macapk_arm64_accept((int)a1, (struct sockaddr*)macapk_untag_ptr((void*)a2), (socklen_t*)a3));  // accept
        case 203:  return macapk_router_from_linux((long)__macapk_arm64_connect((int)a1, (const struct sockaddr*)a2, (socklen_t)a3));  // connect
        case 204:  return macapk_router_from_linux((long)__macapk_arm64_getsockname((int)a1, (struct sockaddr*)macapk_untag_ptr((void*)a2), (socklen_t*)a3));  // getsockname
        case 205:  return macapk_router_from_linux((long)__macapk_arm64_getpeername((int)a1, (struct sockaddr*)macapk_untag_ptr((void*)a2), (socklen_t*)a3));  // getpeername
        case 206:  return macapk_router_from_linux((long)__macapk_arm64_sendto((int)a1, (const void*)a2, (size_t)a3, (int)a4, (const struct sockaddr*)a5, (socklen_t)a6));  // sendto
        case 207:  return macapk_router_from_linux((long)__macapk_arm64_recvfrom((int)a1, (void*)macapk_untag_ptr((void*)a2), (size_t)a3, (int)a4, (struct sockaddr*)macapk_untag_ptr((void*)a5), (socklen_t*)a6));  // recvfrom
        case 208:  return macapk_router_from_linux((long)__macapk_arm64_setsockopt((int)a1, (int)a2, (int)a3, (const void*)a4, (socklen_t)a5));  // setsockopt
        case 209:  return macapk_router_from_linux((long)__macapk_arm64_getsockopt((int)a1, (int)a2, (int)a3, (void*)macapk_untag_ptr((void*)a4), (socklen_t*)a5));  // getsockopt
        case 216:  return (long)__macapk_arm64_mremap((void*)macapk_untag_ptr((void*)a1), (size_t)a2, (size_t)a3, (int)a4);  // mremap
        case 222:  return (long)__macapk_arm64_mmap((void*)macapk_untag_ptr((void*)a1), (size_t)a2, (int)a3, (int)a4, (int)a5, (off_t)a6);  // mmap
        case 226:  return (long)__macapk_arm64_mprotect((void*)macapk_untag_ptr((void*)a1), (size_t)a2, (int)a3);  // mprotect
        case 233:  return (long)__macapk_arm64_madvise((void*)macapk_untag_ptr((void*)a1), (size_t)a2, (int)a3);  // madvise
        case 279:  // SYS_memfd_create (name=a1, flags=a2). memfd_create is new
                   // enough that callers invoke it via raw syscall() rather than a
                   // libc wrapper; Facebook's lacrima/breakpad crash reporter does
                   // exactly this to back its crash-dump shared buffer, and a bare
