uint32_t __macapk_shim_glActiveTexture(uint32_t unit, uint32_t, uint32_t, uint32_t) {
    note_gl_call("glActiveTexture");
    glActiveTexture(unit); return 0;
}
uint32_t __macapk_shim_glClear(uint32_t mask, uint32_t, uint32_t, uint32_t) {
    // v1.0.824: [touch-diag] -- OFF unless MACAPK_TOUCH_DIAG=1.
    //
    // Env-gated on purpose. The v1.0.822 version ran on every launch and, worse,
    // used RAW unchecked guest reads in this hot path. A diagnostic must not be
    // able to change a normal run: this one cannot even execute unless asked
    // for, and every read is bounds-checked against the guest arena.
    //
    // Dumps CCTouchDispatcher's whole handler block, because the interesting
    // fact is WHICH array is missing. Layout read straight out of
    // CCTouchDispatcher::init's own stores (0x197384):
    //   +0x18 m_pTargetedHandlers  = CCArray::createWithCapacity(8)
    //   +0x1c m_pStandardHandlers  = CCArray::createWithCapacity(4)
    //   +0x24 m_pHandlersToAdd     = CCArray::createWithCapacity(8)
    //   +0x2d m_bDispatchEvents    = true
    // init() creates all three UNCONDITIONALLY, so a NULL here is our bug, not
    // the app's.
    {
        static const bool td_on = [](){
            const char* e = std::getenv("MACAPK_TOUCH_DIAG");
            return e && *e && *e != '0'; }();
        static std::atomic<uint64_t> s_td{0};
        const uint64_t n = td_on ? s_td.fetch_add(1, std::memory_order_relaxed) : 1;
        if (td_on && g_guest_base && (n == 60 || n == 600 || n == 1800)) {
            // v1.0.845: NO DEFAULT. This used to fall back to 0x306458 (HCR
            // 1.43's CCDirector instance) whenever MACAPK_DIRECTOR_VADDR was
            // unset -- which is CLAUDE.md's explicitly-named violation shape:
            // "an env var with a DEFAULT vaddr baked in (still a violation --
            // the default fires with zero user action)". MACAPK_TOUCH_DIAG
            // reads as a generic 'turn on touch diagnostics' switch and gives
            // no hint that it is HCR-specific, so setting just that one flag
            // on ANY cocos2d-x app was enough to start dereferencing another
            // app's guest memory at HCR's address.
            //
            // Worse, a comment 40 lines below already claimed the opposite of
            // this code: "This replacement has NO default address.
            // MACAPK_DIRECTOR_VADDR must be supplied explicitly." That was
            // true of the scene-tree dumper it described and false of this
            // block, which the v1.0.833 cleanup missed. Now both are true.
            static const uint32_t kDirInst = []() -> uint32_t {
                const char* e = std::getenv("MACAPK_DIRECTOR_VADDR");
                return (e && *e) ? (uint32_t)std::strtoul(e, nullptr, 0) : 0u;
            }();
            if (!kDirInst) {
                static std::atomic<bool> warned{false};
                if (!warned.exchange(true)) {
                    std::fprintf(stderr, "[touch-diag] MACAPK_TOUCH_DIAG is set but "
                        "MACAPK_DIRECTOR_VADDR is not -- skipping. The director vaddr is "
                        "per-build; supply it explicitly for the binary you are debugging.\n");
                }
            } else {
            auto ok = [](uint32_t v, uint32_t n2) {
                return v != 0 && (uint64_t)v + n2 < (uint64_t)kGuestMemSize; };
            auto r32 = [&](uint32_t v) -> uint32_t {
                return ok(v,4) ? *(const uint32_t*)(g_guest_base + v) : 0u; };
            auto r8 = [&](uint32_t v) -> uint32_t {
                return ok(v,1) ? *(const uint8_t*)(g_guest_base + v) : 0u; };
            const uint32_t td = r32(kDirInst + 0x1c);
            if (ok(td, 0x40)) {
                std::fprintf(stderr,
                    "[touch-diag] #%llu td=0x%x dispatchEvents=%u "
                    "locked/toAdd/toRemove/toQuit@20,21,22,2c=%u/%u/%u/%u",
                    (unsigned long long)n, td, r8(td+0x2d),
                    r8(td+0x20), r8(td+0x21), r8(td+0x22), r8(td+0x2c));
                struct { const char* tag; uint32_t off; } F[] = {
                    {"targeted@18", 0x18}, {"standard@1c", 0x1c}, {"toAdd@24", 0x24} };
                for (auto& f : F) {
                    const uint32_t cc = r32(td + f.off);
                    if (!ok(cc, 0x18)) { std::fprintf(stderr, " %s=NULL", f.tag); continue; }
                    const uint32_t data = r32(cc + 0x14);
                    if (!ok(data, 0x0c)) { std::fprintf(stderr, " %s{cc=0x%x data=NULL}", f.tag, cc); continue; }
                    std::fprintf(stderr, " %s{cc=0x%x num=%u max=%u}",
                                 f.tag, cc, r32(data), r32(data+4));
                }
                std::fprintf(stderr, "\n");
            }
            }   // else (kDirInst supplied explicitly)
        }
    }
    note_gl_call("glClear");
    glClear(mask);
    // v1.0.833: REMOVED -- two HCR-specific rescue blocks used to live here
    // (an AssetLoader/onReloadAssets force-call chain, and a scene-diag pass
    // that WROTE guest memory at HCR's cocos2d-x v2 offsets). Both were keyed
    // to hardcoded HCR vaddrs and ran on EVERY lifted ARM32 app, so on any
    // other app they walked and wrote arbitrary memory. Deleted rather than
    // env-gated: the project's rule is ZERO per-APK code in the shipped
    // runtime, and an env flag is not the 'positive identification gate' the
    // narrow diagnostic exception requires.
    // Measured before removal: hcr181 (the app they were written for) renders
    // RICH 47,868 without them, and the asset-kick block's own comment
    // recorded that it fired ZERO times there. Recover from git if the HCR
    // CCCallFunc/action-chain investigation needs them: v1.0.832
    // runtime/translator/src/bionic_shim.cpp.
    // Empty-scene-tree diagnostic for HCR. drawScene calls glClear every
    // frame regardless of whether m_pRunningScene is set; if we see a
    // steady 60fps glClear stream without any glDraw* calls, either:
    //   - m_pRunningScene is NULL (runWithScene never attached a scene)
    //   - or the scene exists but its visit() chain never reaches a
    //     drawing leaf (every CCSprite has m_bVisible=false or zero size)
    //
    // The HCR 1.8.1 libgame.so layout: the CCDirector OBJECT itself (not a
    // pointer to it) is the .bss static `s_SharedDirector` at 0x306458, since
    // sharedDirector() @0x12fa74 returns &s_SharedDirector (cocos2d-x <= 2.0.3,
    // HCR is 2.0-rc2-x-2.0.1; 2.0.4+ heap-allocates it). CCDirector::m_pRunningScene is at offset
    // 0x94 in the instance, found by tracing drawScene at 0x1306c0:
    //   ldr r0, [r4, #0x94] ; r0 = m_pRunningScene
    //   cmp r0, #0
    //   beq 0x130794        ; skip visit if NULL
    //   ldr r3, [r0]        ; r3 = scene's vtable
    //   ldr r3, [r3, #0x110]; vtable[0x110] = visit
    //   blx r3              ; visit the scene
    //
    // Logging at #1, #100, #1000, #2000, ... gives a coarse timeline
    // without flooding the log.
    // v1.0.833: GENERIC opt-in entry to the scene-tree dumper.
    //
    // The dumper itself (scene_tree_maybe_dump, above) is app-agnostic: it takes
    // a scene pointer and reads every field offset from MACAPK_SCENE_TREE_*
    // env vars. What made the OLD caller per-APK was how it obtained that
    // pointer -- it defaulted kDirectorInstance to 0x306458, HCR 1.8.1's
    // director, so it dereferenced that address on every lifted ARM32 app. That
    // caller was deleted in this version along with the rest of the HCR blocks.
    //
    // This replacement has NO default address. MACAPK_DIRECTOR_VADDR must be
    // supplied explicitly, which makes running it the user's deliberate act --
    // configuration, not app-specific code baked into the runtime. With the env
    // unset, nothing below executes and no guest memory is touched.
    //
    // Why keep it at all: it is the diagnostic the open GD Lite ARM32 lead needs
    // (0 children on the running scene => the addChild hypothesis; 1 child stuck
    // => the loadAssets/action-chain hypothesis). See
    // docs/gdlite-arm32-empty-scene_2026-07-29.md for the exact invocation.
    //
    // The +0x94 running-scene offset is a cocos2d-x v2 ENGINE offset, not an app
    // constant, and is overridable -- note the open RECONCILE in CLAUDE.md: GD
    // Lite 2.2.11 measures a CCNode layout that disagrees with the table, so a
    // build whose director layout also differs needs the override.
    static std::atomic<uint64_t> g_scene_diag_counter{0};
    const uint64_t scene_diag_n =
        g_scene_diag_counter.fetch_add(1, std::memory_order_relaxed);
    static const uint32_t s_dir_vaddr = []() -> uint32_t {
        const char* e = std::getenv("MACAPK_DIRECTOR_VADDR");
        return (e && *e) ? static_cast<uint32_t>(std::strtoul(e, nullptr, 0)) : 0u;
    }();
    if (s_dir_vaddr && g_guest_base) {
        static const uint32_t s_running_off = []() -> uint32_t {
            const char* e = std::getenv("MACAPK_DIRECTOR_RUNNING_SCENE_OFF");
            return (e && *e) ? static_cast<uint32_t>(std::strtoul(e, nullptr, 0))
                             : 0x94u;
        }();
        const uint64_t slot = static_cast<uint64_t>(s_dir_vaddr) + s_running_off;
        if (slot + 4 < static_cast<uint64_t>(kGuestMemSize)) {
            const uint32_t running = *reinterpret_cast<const uint32_t*>(
                g_guest_base + slot);
            if (running && static_cast<uint64_t>(running) + 4
                               < static_cast<uint64_t>(kGuestMemSize)) {
                scene_tree_maybe_dump(running, scene_diag_n);
            }
        }
    }
    return 0;
}
