// 4-arg ----------------------------------------------------------------
uint32_t __macapk_shim_glBufferData(uint32_t target, uint32_t size,
                                      uint32_t data, uint32_t usage) {
    // Per GL: a null `data` pointer means "allocate but don't
    // initialize". We must NOT translate 0 through gptr_const, which
    // would yield g_guest_base+0 -- a valid host pointer to garbage at
    // the start of our 1 GiB guest memory region. cocos2d-x's
    // CCTextureAtlas uses this pattern (calls glBufferData with NULL
    // to pre-size the VBO, then fills it with glBufferSubData later).
    const void* p = (data == 0) ? nullptr : gptr_const(data);
    glBufferData(target, static_cast<GLsizeiptr>(static_cast<int32_t>(size)),
                 p, usage);
    return 0;
}
uint32_t __macapk_shim_glBufferSubData(uint32_t target, uint32_t offset,
                                         uint32_t size, uint32_t data) {
    // glBufferSubData with NULL data is undefined per spec, but be
    // defensive: skip the call rather than uploading garbage.
    if (data == 0 || size == 0) return 0;
    if (std::getenv("MACAPK_DUMP_DRAWS")) {
        static std::atomic<int> sd_log_n{0};
        int n = sd_log_n.fetch_add(1);
        if (n < 24) {
            GLint vbo = 0, tex = 0;
            glGetIntegerv(GL_ARRAY_BUFFER_BINDING, &vbo);
            glGetIntegerv(GL_TEXTURE_BINDING_2D, &tex);
            // For cocos2d-x's V3F_C4B_T2F (24-byte vertices), dump up to 16
            if (size >= 24 && target == 0x8892 /* GL_ARRAY_BUFFER */) {
                const uint8_t* p = static_cast<const uint8_t*>(gptr_const(data));
                std::fprintf(stderr,
                    "[gles-diag] glBufferSubData #%d vbo=%d tex=%d off=%u size=%u\n",
                    n, vbo, tex, offset, size);
                // 16 vertices = 4 quads, which is enough to identify a buffer
                // but NOT enough to answer "where did the rest of the batch
                // go" -- a 49-quad label batch shows only its first word.
                // MACAPK_DUMP_VERTS_MAX raises the cap so the whole batch's
                // geometry can be swept for off-screen or degenerate quads.
                static const int kVertCap = [] {
                    const char* e = std::getenv("MACAPK_DUMP_VERTS_MAX");
                    const long v = e ? std::strtol(e, nullptr, 10) : 0;
                    return static_cast<int>(v > 0 ? v : 16);
                }();
                int max_v = static_cast<int>(size / 24);
                if (max_v > kVertCap) max_v = kVertCap;
                for (int v = 0; v < max_v; ++v) {
                    const uint8_t* pv = p + v * 24;
                    float px, py, pz, tu, tv;
                    std::memcpy(&px, pv + 0, 4);
                    std::memcpy(&py, pv + 4, 4);
                    std::memcpy(&pz, pv + 8, 4);
                    std::memcpy(&tu, pv + 16, 4);
                    std::memcpy(&tv, pv + 20, 4);
                    uint32_t tv_bits, tu_bits, px_bits;
                    std::memcpy(&tv_bits, pv + 20, 4);
                    std::memcpy(&tu_bits, pv + 16, 4);
                    std::memcpy(&px_bits, pv + 0, 4);
                    std::fprintf(stderr,
                        "  v%d: pos=(%.2f,%.2f,%.2f / 0x%x) RGBA=(%u,%u,%u,%u) "
                        "uv=(%.4f, %.4f / bits=%x,%x)\n",
                        v, px, py, pz, px_bits,
                        pv[12], pv[13], pv[14], pv[15],
                        tu, tv, tu_bits, tv_bits);
                }
            }
        }
    }
    glBufferSubData(target, static_cast<GLintptr>(static_cast<int32_t>(offset)),
                    static_cast<GLsizeiptr>(static_cast<int32_t>(size)),
                    gptr_const(data));
    return 0;
}
uint32_t __macapk_shim_glClearColor(uint32_t r, uint32_t g, uint32_t b, uint32_t a) {
    glClearColor(as_float(r), as_float(g), as_float(b), as_float(a));
    return 0;
}
uint32_t __macapk_shim_glDrawArrays(uint32_t mode, uint32_t first,
                                      uint32_t count, uint32_t) {
    note_gl_call("glDrawArrays");
    // Diagnostic: first few draw calls dump the GL state machine so we
    // can see what cocos2d-x is actually trying to render. Look for
    // a viewport != 0,0,W,H (off-screen drawing), program=0 (no
    // shader bound), or attribs all zero (degenerate quad).
    static std::atomic<int> da_log_n{0};
    int da_n = da_log_n.fetch_add(1);
    if (da_n < 4) {
        GLint vp[4] = {0,0,0,0};
        glGetIntegerv(GL_VIEWPORT, vp);
        GLint program = 0;
        glGetIntegerv(GL_CURRENT_PROGRAM, &program);
        GLint vbo = 0, ibo = 0;
        glGetIntegerv(GL_ARRAY_BUFFER_BINDING, &vbo);
        glGetIntegerv(GL_ELEMENT_ARRAY_BUFFER_BINDING, &ibo);
        GLint a0_en = 0, a0_size = 0, a0_type = 0, a0_stride = 0, a0_vbo = 0;
        void* a0_ptr = nullptr;
        glGetVertexAttribiv(0, GL_VERTEX_ATTRIB_ARRAY_ENABLED, &a0_en);
        glGetVertexAttribiv(0, GL_VERTEX_ATTRIB_ARRAY_SIZE, &a0_size);
        glGetVertexAttribiv(0, GL_VERTEX_ATTRIB_ARRAY_TYPE, &a0_type);
        glGetVertexAttribiv(0, GL_VERTEX_ATTRIB_ARRAY_STRIDE, &a0_stride);
        glGetVertexAttribiv(0, GL_VERTEX_ATTRIB_ARRAY_BUFFER_BINDING, &a0_vbo);
        glGetVertexAttribPointerv(0, GL_VERTEX_ATTRIB_ARRAY_POINTER, &a0_ptr);
        std::fprintf(stderr,
            "[gles-diag] glDrawArrays#%d mode=0x%x first=%u count=%u "
            "vp=%d,%d,%dx%d program=%d vbo=%d ibo=%d "
            "attr0[en=%d sz=%d ty=0x%x st=%d vbo=%d ptr=%p]\n",
            da_n, (unsigned)mode, (unsigned)first, (unsigned)count,
            vp[0], vp[1], vp[2], vp[3],
            program, vbo, ibo,
            a0_en, a0_size, a0_type, a0_stride, a0_vbo, a0_ptr);
    }
    // MACAPK_DUMP_DRAWARRAYS_RANGE=<lo>[:<hi>] (diagnostic, off by default):
    // for every glDrawArrays in [lo,hi) print the bound texture and, when
    // attribs 0 (position) / 1 (colour) / 2 (texcoord) are CLIENT arrays (no
    // VBO -- cocos2d-x CCSprite::draw's shape), the vertices themselves. The
    // glDrawElements dump above cannot see a non-batched sprite at all.
    {
        static const std::pair<int,int> range = [] {
            const char* e = std::getenv("MACAPK_DUMP_DRAWARRAYS_RANGE");
            if (!e || !*e) return std::pair<int,int>{-1,-1};
            char* end = nullptr;
            const long lo = std::strtol(e, &end, 10);
            const long hi = (end && *end == ':') ? std::strtol(end + 1, nullptr, 10)
                                                 : lo + 200;
            return std::pair<int,int>{static_cast<int>(lo), static_cast<int>(hi)};
        }();
        if (range.first >= 0 && da_n >= range.first && da_n < range.second) {
            GLint tex = 0, prog = 0;
            glGetIntegerv(GL_TEXTURE_BINDING_2D, &tex);
            glGetIntegerv(GL_CURRENT_PROGRAM, &prog);
            std::fprintf(stderr, "[gles-da] #%d mode=0x%x first=%u count=%u tex=%d prog=%d\n",
                         da_n, (unsigned)mode, (unsigned)first, (unsigned)count, tex, prog);
            for (GLuint a = 0; a < 3; ++a) {
                GLint en = 0, sz = 0, ty = 0, st = 0, vb = 0; void* p = nullptr;
                glGetVertexAttribiv(a, GL_VERTEX_ATTRIB_ARRAY_ENABLED, &en);
                if (!en) continue;
                glGetVertexAttribiv(a, GL_VERTEX_ATTRIB_ARRAY_SIZE, &sz);
                glGetVertexAttribiv(a, GL_VERTEX_ATTRIB_ARRAY_TYPE, &ty);
                glGetVertexAttribiv(a, GL_VERTEX_ATTRIB_ARRAY_STRIDE, &st);
                glGetVertexAttribiv(a, GL_VERTEX_ATTRIB_ARRAY_BUFFER_BINDING, &vb);
                glGetVertexAttribPointerv(a, GL_VERTEX_ATTRIB_ARRAY_POINTER, &p);
                std::fprintf(stderr, "    attr%u sz=%d ty=0x%x st=%d vbo=%d", a, sz, ty, st, vb);
                if (vb == 0 && p && count <= 64) {
                    const uint8_t* base = static_cast<const uint8_t*>(p);
                    for (uint32_t v = first; v < first + count && v < first + 4; ++v) {
                        const uint8_t* e = base + static_cast<size_t>(v) * static_cast<size_t>(st);
                        if (ty == GL_FLOAT) {
                            float f[4] = {0, 0, 0, 0};
                            std::memcpy(f, e, sizeof(float) * static_cast<size_t>(sz > 4 ? 4 : sz));
                            std::fprintf(stderr, " (%.2f,%.2f%s%.2f)", f[0], f[1], sz > 2 ? "," : "", sz > 2 ? f[2] : 0.f);
                        } else if (ty == GL_UNSIGNED_BYTE) {
                            std::fprintf(stderr, " [%u,%u,%u,%u]", e[0], e[1], e[2], e[3]);
                        }
                    }
                }
                std::fprintf(stderr, "\n");
            }
        }
    }
    glDrawArrays(mode, static_cast<GLint>(first), static_cast<GLsizei>(count));
    return 0;
}
uint32_t __macapk_shim_glDrawElements(uint32_t mode, uint32_t count,
                                        uint32_t type, uint32_t indices) {
    note_gl_call("glDrawElements");
    // Same dual semantics as glVertexAttribPointer: with an
    // ELEMENT_ARRAY_BUFFER bound `indices` is a byte offset, without
    // one it's a CPU memory pointer (guest VA). cocos2d-x's CCSprite
    // path uses client-side index arrays so we must translate.
    GLint ibo = 0;
    glGetIntegerv(GL_ELEMENT_ARRAY_BUFFER_BINDING, &ibo);
    const void* host_ptr;
    if (ibo == 0 && indices != 0) {
        host_ptr = static_cast<const void*>(g_guest_base + indices);
    } else {
        host_ptr = reinterpret_cast<const void*>(
            static_cast<intptr_t>(indices));
    }
    // Diagnostic: log first few draws + which texture is bound + the
    // bound program, plus the per-vertex color bytes from the bound
    // vertex array (cocos2d-x's CCSpriteBatchNode uses C4B color per
    // vertex). If a label's quads have alpha=0 the glyphs are invisible
    // even though they're submitted to the GPU.
    // Diagnostic (opt-in via MACAPK_DUMP_DRAWS): log full draw context
    // plus all 3 vertex attributes so we can correlate text rendering
    // (glDrawElements + bound batch VBO) with what cocos2d-x is actually
    // submitting. Used during the CCLabelBMFont text-not-rendering hunt.
    if (std::getenv("MACAPK_DUMP_DRAWS")) {
        static std::atomic<int> de_log_n{0};
        int n = de_log_n.fetch_add(1);
        // The default sampling (first 12, then every 500th) is enough to say
        // "which texture dominates" but CANNOT enumerate one frame, and
        // dividing the total by our vsync count does not give draws-per-frame
        // either -- cocos's drawScene does not run once per AngleBeginFrame.
        // MACAPK_DUMP_DRAWS_RANGE=<lo>[:<hi>] logs EVERY draw in [lo,hi), which
        // is what you want once the app is at steady state: pick a window well
        // past boot and you get a complete, contiguous frame.
        static const std::pair<int,int> range = [] {
            const char* e = std::getenv("MACAPK_DUMP_DRAWS_RANGE");
            if (!e || !*e) return std::pair<int,int>{-1,-1};
            char* end = nullptr;
            const long lo = std::strtol(e, &end, 10);
            const long hi = (end && *end == ':') ? std::strtol(end + 1, nullptr, 10)
                                                 : lo + 200;
            return std::pair<int,int>{static_cast<int>(lo), static_cast<int>(hi)};
        }();
        const bool in_range = (range.first >= 0 && n >= range.first && n < range.second);
        if (in_range || n < 12 || (n % 500) == 0) {
            GLint tex = 0, vp[4] = {0,0,0,0}, prog = 0, vbo = 0, ibo = 0;
            glGetIntegerv(GL_TEXTURE_BINDING_2D, &tex);
            glGetIntegerv(GL_VIEWPORT, vp);
            glGetIntegerv(GL_CURRENT_PROGRAM, &prog);
            glGetIntegerv(GL_ARRAY_BUFFER_BINDING, &vbo);
            glGetIntegerv(GL_ELEMENT_ARRAY_BUFFER_BINDING, &ibo);
            std::fprintf(stderr,
                "[gles-diag] glDrawElements #%d mode=0x%x count=%u "
                "type=0x%x tex=%d vp=%dx%d prog=%d vbo=%d ibo=%d\n",
                n, mode, count, type, tex, vp[2], vp[3], prog, vbo, ibo);
        }
    }
    glDrawElements(mode, static_cast<GLsizei>(count), type, host_ptr);
    return 0;
}
