// glScissor: clip rectangle. Logged because a wrong clip is one of the
// usual suspects when content is "shoved left" or partially off-screen.
uint32_t __macapk_shim_glScissor(uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    note_gl_call("glScissor");
    static std::atomic<int> sc_log_n{0};
    int n = sc_log_n.fetch_add(1);
    if (n < 30 || (n % 200) == 0) {
        std::fprintf(stderr,
            "[gles-diag] glScissor #%d (%d, %d, %u, %u)\n",
            n, (int)x, (int)y, w, h);
    }
    glScissor(static_cast<GLint>(x), static_cast<GLint>(y),
              static_cast<GLsizei>(w), static_cast<GLsizei>(h));
    return 0;
}
