// Custom std::terminate handler installed via a global constructor.
// libc++abi's default handler can't demangle exception type_info
// pointers from libc++_shared.so (the NDK's `__ndk1` namespace lives
// in a different libc++abi instance than Apple's), producing useless
// "terminating with exception of type :" messages. Our handler walks
// the current exception via __cxxabiv1::__cxa_current_exception_type
// and __cxa_demangle, then re-throws to let the default handler
// abort. If the exception is a std::exception, we also print what().
//
// PER-APK STATUS. Per-library diagnostic. Generic across any NDK
// app that throws C++ exceptions through libc++_shared.
namespace __cxxabiv1 {
    struct __class_type_info;
    extern "C" std::type_info* __cxa_current_exception_type();
    extern "C" char* __cxa_demangle(const char* mangled, char* buf,
                                     size_t* len, int* status);
}
namespace {
void macapk_terminate_handler() {
    // Re-entrancy guard. v1.0.572: the old handler did an UNCONDITIONAL
    // `throw;` to fish out what(). When std::terminate is called with NO
    // active exception -- a PURE-VIRTUAL call (__cxa_pure_virtual, i.e. a
    // corrupted/half-constructed vtable), a noexcept violation, or a
    // joinable std::thread destructor -- `throw;` with nothing in flight
    // itself calls std::terminate -> re-enters this handler -> infinite
    // recursion that eventually SIGILLs deep in __cxa_demangle (observed on
    // Minecraft). Guard so a second entry aborts immediately.
    static std::atomic<int> in_handler{0};
    if (in_handler.fetch_add(1) != 0) { std::_Exit(134); }

    std::type_info* type = __cxxabiv1::__cxa_current_exception_type();
    const char* mangled = type ? type->name() : nullptr;
    if (mangled) {
        int status = 0;
        char* demangled = __cxxabiv1::__cxa_demangle(
            mangled, nullptr, nullptr, &status);
        std::fprintf(stderr,
            "[macapk-terminate] uncaught C++ exception: %s (mangled: %s)\n",
            demangled ? demangled : mangled, mangled);
        if (demangled) std::free(demangled);
        // v1.0.592: THROW-CHAIN backtrace. terminate() is called during the
        // _Unwind SEARCH phase (BEFORE the stack is unwound), so the frames
        // above __cxa_throw are the REAL throw site + its callers -- the menu
        // code that invoked an empty std::function (bad_function_call). This is
        // NON-PERTURBING (runs only on the crash, not per-throw), so it catches
        // the race origin the __cxa_throw route suppresses. Raw addresses are
        // dumped too so guest frames map via file_vaddr = addr - <libminecraftpe
        // base> (from the run-log "mapped, base="). backtrace_symbols_fd names the
        // host frames; the guest ones show as the Stage-6 wrapper + offset.
        {
            void* bt[48];
            int nb = backtrace(bt, 48);
            std::fprintf(stderr, "[macapk-terminate] throw-chain backtrace:\n");
            backtrace_symbols_fd(bt, nb, 2 /*stderr*/);
            std::fprintf(stderr, "[macapk-terminate] raw:");
            for (int i = 0; i < nb; ++i) std::fprintf(stderr, " %p", bt[i]);
            std::fprintf(stderr, "\n");
            std::fflush(stderr);
        }
        try {
            throw;  // safe: there IS a current exception
        } catch (const std::exception& e) {
            std::fprintf(stderr, "[macapk-terminate] what(): %s\n", e.what());
        } catch (...) {
            std::fprintf(stderr, "[macapk-terminate] (not a std::exception)\n");
        }
    } else {
        // No current exception: std::terminate was called directly. The
        // usual causes are a pure-virtual call (vtable corruption / a freed
        // or half-constructed object -- a heap-corruption tell), a noexcept
        // violation, or a joinable thread destructor. Dump a backtrace so
        // the guest caller (the frame just above abort/terminate) is named
        // instead of vanishing. DO NOT re-throw here (that was the bug).
        std::fprintf(stderr,
            "[macapk-terminate] std::terminate() with NO active exception "
            "(pure-virtual call / noexcept violation / joinable-thread dtor). "
            "Backtrace:\n");
        void* bt[32];
        int n = backtrace(bt, 32);
        char** syms = backtrace_symbols(bt, n);
        for (int i = 0; i < n; ++i) {
            std::fprintf(stderr, "  #%-2d %s\n", i,
                         syms ? syms[i] : "?");
        }
        if (syms) std::free(syms);
    }
    std::fflush(stderr);
    std::abort();
}
__attribute__((constructor))
void install_terminate_handler() {
    std::set_terminate(macapk_terminate_handler);
}
}  // namespace

// =================================================================
// v1.0.152: Unity / NDK shim stubs
// =================================================================
//
// Unity's libunity.so links against ~42 NDK symbols our framework
// didn't yet expose: stdio FILE variables (stdout/stderr), Android
// NDK ANativeWindow_* / ALooper_* / ASensor_* / AChoreographer_*,
// pthread_condattr_setclock, gettid, prctl, __system_property_*,
// fseeko64/ftello64. The arm64_native.cpp resolver looks for
// `__macapk_arm64_<name>` symbols, so each shim is exported under
// that prefix.
//
// For OPAQUE Android NDK handles (ANativeWindow*, ALooper*,
// AChoreographer*, ASensorManager*, ASensorEventQueue*, ASensor*),
// the stubs return non-NULL marker addresses so Unity proceeds
// past null-checks. The shims that operate on these handles ignore
// the handle value (they're all stubs). Unity boots; sensor / frame-
// callback functionality is degraded (no events delivered) but the
// engine main loop runs.
//
// For real-functional symbols (gettid, fseeko64, ftello64,
// pthread_condattr_setclock), the shim implements the actual
// behavior using the macOS equivalent.
//
// Generic across any Unity-based APK or Android NativeActivity-based
// app; no per-APK code.

#include <unistd.h>
#include <pthread.h>

// stdio FILE* variables. Bionic uses `stdout` / `stderr` as global
// FILE* names; macOS uses `__stdoutp` / `__stderrp` with `stdout` /
// `stderr` as macros to them. Export FILE* variables under the
// `__macapk_arm64_` prefix and populate from macOS's globals via
// a constructor so the relocation resolver wires Bionic-side
// references to the macOS-side FILE* values.
extern "C" {
    FILE* __macapk_arm64_stdout = nullptr;
    FILE* __macapk_arm64_stderr = nullptr;
    FILE* __macapk_arm64_stdin  = nullptr;
}
// v1.0.153: install SIGILL handler eagerly (not just via the ARM32
// `allocate_guest_memory` path -- arm64-only apps like Crossy Road
// never call that, so the SEGV/ILL handlers wouldn't otherwise
// install). The arm64-native ELF loader needs the SIGILL emulator
// armed before libunity's static-init runs.
__attribute__((constructor))
static void init_macapk_sigill_handler() {
    install_segv_recovery();
}

__attribute__((constructor))
static void init_macapk_arm64_stdio() {
    __macapk_arm64_stdout = stdout;
    __macapk_arm64_stderr = stderr;
    __macapk_arm64_stdin  = stdin;
}

// MACAPK_PAIRIP_SPAWN_THREADS=<n> (DIAGNOSTIC, default OFF): spawn n idle HOST
// pthreads that park forever, at shim load (BEFORE the guest natives / pairip's
// env-gather run), so ours' REAL /proc/self/task, /proc/self/status Threads:, and
// maps stack_and_tls all cohere at a device-like thread count (device MC ~55-62;
// ours ~15 HotSpot). Every prior thread lever changed only the SERVED surface;
// this changes ours' ACTUAL structure, which folds SELF-CONSISTENTLY through
// pairip's self-hash (no substitution regression). Decisive falsifier for the
// "map_files checkpoint under-fold is a real thread-cardinality axis" hypothesis:
// if the detonation frontier advances materially past 301578 (esp. shrinking the
// +826 under-fold at disp ~208784) it IS a shapeable axis; if not, the residual is
// the maps<->real-pointer coherence wall (real macOS thread stacks are >4GB).
// docs/pairip-frontier-301578-refutations_2026-09-17.md. 2026-09-17.
static void* macapk_pairip_idle_thread(void*) {
    for (;;) { struct timespec ts{3600, 0}; nanosleep(&ts, nullptr); }
    return nullptr;
}
__attribute__((constructor))
static void macapk_pairip_spawn_idle_threads() {
    const char* e = std::getenv("MACAPK_PAIRIP_SPAWN_THREADS");
    if (!e) return;
    long n = std::strtol(e, nullptr, 10);
    if (n <= 0 || n > 512) return;
    long ok = 0;
    for (long i = 0; i < n; ++i) {
        pthread_t t;
        if (pthread_create(&t, nullptr, macapk_pairip_idle_thread, nullptr) == 0) {
            pthread_detach(t);
            ++ok;
        }
    }
    std::fprintf(stderr, "[pairip-spawn] spawned %ld/%ld idle host threads "
                 "(real /proc/self/task now reflects them)\n", ok, n);
    std::fflush(stderr);
}

// memalign: Bionic/glibc aligned allocation. macOS libSystem has no
// `memalign` (only posix_memalign), so libil2cpp's import resolved to
// NULL -> SIGSEGV on first GC arena allocation. Bionic semantics:
// alignment is a power of two; the result is freeable with free().
// posix_memalign additionally requires alignment >= sizeof(void*) and
// an exact power of two, so clamp/round up to satisfy it.
extern "C" void* __macapk_arm64_memalign(size_t alignment, size_t size) {
    if (alignment < sizeof(void*)) alignment = sizeof(void*);
    if (alignment & (alignment - 1)) {            // not a power of two
        size_t a = sizeof(void*);
        // `a` wraps to 0 for alignment > 2^63 and `a < alignment` then never ends (a HANG,
        // measured with memalign(SIZE_MAX, 16) on 2026-09-29); Bionic returns NULL.
        while (a && a < alignment) a <<= 1;
        if (!a) { errno = EINVAL; return nullptr; }
        alignment = a;
    }
    void* p = nullptr;
    if (posix_memalign(&p, alignment, size) != 0) return nullptr;
    macapk_live_add(p);              // track guest C-alloc live set (mallinfo)
    return macapk_tag_ptr(p);
}

// posix_memalign: Bionic exports it; libminecraftpe imports it. macOS
// libSystem has an ABI-identical posix_memalign, so this is a pure passthrough
// -- its ONLY purpose is to route the guest's imported symbol through our
// C-alloc live-set accounting (so a posix_memalign'd block that is later freed
// via __macapk_arm64_free's count=true path was added here first, keeping the
// counter balanced). Same default zone as ::posix_memalign, no behaviour change.
extern "C" int __macapk_arm64_posix_memalign(void** memptr, size_t alignment,
                                             size_t size) {
    int r = ::posix_memalign(memptr, alignment, size);
    if (r == 0 && memptr) { macapk_live_add(*memptr); *memptr = macapk_tag_ptr(*memptr); }
    return r;
}

// memrchr: Bionic/glibc libc function; macOS libSystem does NOT export
// it (confirmed absent from libSystem.B / libsystem_c / libc++ / libz).
// libunity imports it (GLOBAL UND -> a JUMP_SLOT GOT slot) and calls it
// from its path/filename string-parser (find-last-'/'-or-'.' idiom at
// libunity 0xa3ffd4 / 0xa40558 / 0xa4056c). Without this shim the GOT
// slot resolves to NULL and the first call SIGSEGVs -- the classic
// "missing shim is a silent killer" pattern. Standard semantics: scan
// the first n bytes of s for the LAST occurrence of (unsigned char)c.
extern "C" void* __macapk_arm64_memrchr(const void* s, int c, size_t n) {
    const unsigned char* p = static_cast<const unsigned char*>(s) + n;
    unsigned char ch = static_cast<unsigned char>(c);
    while (n--) {
        if (*--p == ch) return const_cast<unsigned char*>(p);
    }
    return nullptr;
}

// gettid: Bionic returns linux-tid (= per-thread pid_t). macOS has
// pthread_threadid_np which gives a unique 64-bit tid; truncate to
// pid_t for Bionic-shaped callers.
extern "C" int32_t __macapk_arm64_gettid() {
    uint64_t tid = 0;
    pthread_threadid_np(nullptr, &tid);
    return (int32_t)(tid & 0x7FFFFFFF);
}

// prctl: Linux process-control. macOS has no equivalent syscall, but several
// of the ops DO have an exact macOS answer, and blanket-failing them is a
// contract violation rather than a graceful degradation -- most sharply for
// PR_GET_DUMPABLE, which the real syscall answers with 0 or 1 and NEVER with a
// negative value, so a guest's `prctl(PR_GET_DUMPABLE) == 1` check could never
// be satisfied. PR_SET_NAME is the dominant real-world use (near-universal in
// C++ thread-pool startup) and silently dropping it costs every diagnostic
// thread name in the process.
//
// Op numbers from include/uapi/linux/prctl.h (bionic includes the uapi header
// verbatim): PR_SET_PDEATHSIG 1, PR_GET_DUMPABLE 3, PR_SET_DUMPABLE 4,
// PR_SET_NAME 15, PR_GET_NAME 16, PR_SET_VMA 0x53564d41 (Android's
// "name this anonymous mapping", ANDROID_VMA_NAME).
//
// The signature is FIXED named parameters, not `(int, ...)`: on Apple arm64 a
// variadic callee takes its args off the STACK, but the Bionic-compiled caller
// put them in x1..x4 per AAPCS64. Reading them with va_arg here would reproduce
// the exact trap already fixed three times in this file (open, syscall, fcntl).
extern "C" int __macapk_arm64_prctl(int op, unsigned long a2,
                                    unsigned long a3, unsigned long a4,
                                    unsigned long a5) {
    // Real core-dump behaviour is a host property we cannot change, but the
    // guest's own set/get round-trip must stay self-consistent: Linux reports
    // back whatever was last set, defaulting to 1 (dumpable) for a normal
    // process, which is what a non-hardened debuggable device shows.
    static std::atomic<int> g_dumpable{1};
    switch (op) {
        case 15: {  // PR_SET_NAME -- names the CALLING thread, <=16 B incl NUL
            if (!a2) { errno = EFAULT; return -1; }
            char name[16];
            std::strncpy(name, reinterpret_cast<const char*>(a2),
                         sizeof(name) - 1);
            name[sizeof(name) - 1] = '\0';
            // Darwin's pthread_setname_np only ever names the calling thread,
            // which is exactly PR_SET_NAME's scope.
            pthread_setname_np(name);
            return 0;
        }
        case 16: {  // PR_GET_NAME -- writes into a caller buffer of >=16 bytes
            if (!a2) { errno = EFAULT; return -1; }
            char name[16];
            name[0] = '\0';
            pthread_getname_np(pthread_self(), name, sizeof(name));
            std::memcpy(reinterpret_cast<void*>(a2), name, sizeof(name));
            return 0;
        }
        case 3:     // PR_GET_DUMPABLE -- must be 0 or 1, never negative
            return g_dumpable.load(std::memory_order_relaxed);
        case 4:     // PR_SET_DUMPABLE
            if (a2 > 2) { errno = EINVAL; return -1; }
            g_dumpable.store(static_cast<int>(a2), std::memory_order_relaxed);
            return 0;
        case 0x53564d41: {  // PR_SET_VMA (Android): name an anonymous mapping.
            // prctl(PR_SET_VMA, PR_SET_VMA_ANON_NAME=0, addr, len, name).
            // We used to accept this and drop it. Record it instead, so
            // /proc/self/{maps,smaps} can echo the name back as [anon:<name>]
            // the way an Android kernel does. This reports a fact the GUEST
            // supplied about its own mapping -- we never invent one, and an
            // unnamed region simply gets no Name: line.
            if (a2 != 0) { errno = EINVAL; return -1; }
            const char* nm = reinterpret_cast<const char*>(a5);
            if (!nm) { errno = EFAULT; return -1; }
            macapk_vma_name_set((uint64_t)a3, (uint64_t)a4, nm);
            return 0;
        }
        case 1:              // PR_SET_PDEATHSIG: a real device accepts it and returns 0.
            return 0;        // Darwin has no parent-death signal, but the call succeeds.
        case 0x59616d61:     // PR_SET_PTRACER (Yama; "Yama"=0x59616d61). A Yama-enabled
            return 0;        // Android device returns 0 when a process names its tracer.
        default:
            // Everything else genuinely has no answer here. Report the same
            // thing a kernel that does not implement the op reports, instead of
            // a bare -1 with a stale errno.
            errno = EINVAL;
            return -1;
    }
}

// getrandom(buf, buflen, flags) -- the friendly libc wrapper bionic added at
// API 28 (bionic/libc/include/sys/random.h) around the same SYS_getrandom(278)
// syscall our raw-syscall dispatcher already implements. Darwin exports no such
// symbol, so a modern NDK library that calls the wrapper rather than
// raw-syscalling hit the loader's unresolved-symbol abort instead of reaching
// the already-correct logic. Same body as the syscall path: arc4random_buf is
// macOS's always-seeded CSPRNG, which matches getrandom's "blocks only until
// the pool is initialised, then always succeeds" contract.
extern "C" ssize_t __macapk_arm64_getrandom(void* buf, size_t buflen,
                                            unsigned int /*flags*/) {
    if (!buf) { errno = EFAULT; return -1; }
    if (buflen) arc4random_buf(buf, buflen);
    return static_cast<ssize_t>(buflen);
}

// getentropy(buf, buflen) -- the OS entropy source that crypto libraries (OpenSSL,
// BoringSSL) call to seed their DRBGs. Bionic has had it since API 28
// (bionic/libc/include/unistd.h). Darwin ALSO exports getentropy, so without this
// shim the guest's import binds to Darwin's -- and Darwin's getentropy is a RAW
// SYSCALL whose kernel copyout REJECTS a TOP-BYTE-TAGGED pointer with EFAULT.
// Measured (clean micro-test, 2026-10-15): getentropy(0xb4..<addr>, 32) returns
// -1/EFAULT while the identical untagged address returns 0. When
// MACAPK_TAGGED_POINTERS is on, our allocator tags heap pointers (top byte 0xb4,
// mirroring Android's heap tagging); Bionic relies on the kernel honouring TBI so
// the tag is transparent to a syscall, but macOS's kernel does not honour TBI for
// syscall arguments, so a tagged buffer faults. The downstream damage is severe and
// silent: OpenSSL 1.1.1's rand_pool_acquire_entropy falls back to SYS_getrandom ONLY
// when getentropy fails with ENOSYS; an EFAULT makes it GIVE UP, so the DRBG receives
// zero entropy and RAND_bytes()/RAND_priv_bytes() return 0. In MC's Bedrock engine
// that drives a deliberate fatal path (a store of 0xdeadc0de to NULL, masked by our
// null-recovery) ~2 frames into engine init, surfacing as an uncaught
// nonstd::bad_expected_access<Bedrock::ErrorInfo<std::error_code>> and SIGABRT --
// the "post-pairip Bedrock crash" (crack log cont.400-402).
//
// Route getentropy to arc4random_buf, exactly like __macapk_arm64_getrandom above:
// it is macOS's always-seeded userspace CSPRNG, and because the fill happens in
// userspace the CPU ignores the TBI tag on the store, so a tagged buffer is fine.
// Preserve getentropy's documented contract (man getentropy / bionic): EINVAL for
// buflen > 256, EFAULT for a NULL buffer, else fill and return 0. This is the same
// category as every other Bionic-vs-libSystem ABI shim in this file -- a faithful
// reimplementation of the platform API, not a forced value: an actual broken entropy
// source would still fail; we only stop FALSELY failing because macOS rejects the
// Bionic tag that Linux would have ignored.
extern "C" int __macapk_arm64_getentropy(void* buf, size_t buflen) {
    if (buflen > 256) { errno = EINVAL; return -1; }
    if (!buf) { errno = EFAULT; return -1; }
    if (buflen) arc4random_buf(buf, buflen);
    return 0;
}

// pthread_condattr_setclock / _getclock. Bionic (libc/bionic/pthread_cond.cpp):
//
//   int pthread_condattr_setclock(pthread_condattr_t* attr, clockid_t clock) {
//     if (clock != CLOCK_MONOTONIC && clock != CLOCK_REALTIME) return EINVAL;
//     *attr = COND_SET_CLOCK(*attr, clock);
//     return 0;
//   }
//
// This used to discard clock_id and return 0, so pthread_cond_timedwait had to
// GUESS which epoch an abstime belonged to from its magnitude. Record the
// choice in the attr's COND_CLOCK_MASK bit; pthread_cond_init copies it onto
// the cond and pthread_cond_timedwait uses it instead of guessing.
// Bionic/Linux clock ids: CLOCK_REALTIME 0, CLOCK_MONOTONIC 1.
extern "C" int __macapk_arm64_pthread_condattr_setclock(
        pthread_condattr_t* attr_in, int clock_id) {
    if (clock_id != 0 && clock_id != 1) return 22;  // EINVAL (bionic value)
    int32_t* attr = reinterpret_cast<int32_t*>(attr_in);
    if (!attr) return 22;
    int32_t v = __atomic_load_n(&attr[0], __ATOMIC_RELAXED);
    v = (v & ~kBionicCondClockMask) | (clock_id ? kBionicCondClockMask : 0);
    __atomic_store_n(&attr[0], v, __ATOMIC_RELAXED);
    return 0;
}
extern "C" int __macapk_arm64_pthread_condattr_getclock(
        const pthread_condattr_t* attr_in, int* clock_id) {
    const int32_t* attr = reinterpret_cast<const int32_t*>(attr_in);
    if (!attr || !clock_id) return 22;
    *clock_id = (__atomic_load_n(&attr[0], __ATOMIC_RELAXED)
                 & kBionicCondClockMask) ? 1 : 0;
    return 0;
}

// Large-file stdio. macOS's fseeko/ftello already use off_t which is
// 64-bit on darwin; alias directly.
extern "C" int __macapk_arm64_fseeko64(FILE* f, off_t off, int whence) {
    return fseeko(f, off, whence);
}
extern "C" off_t __macapk_arm64_ftello64(FILE* f) {
    return ftello(f);
}

// __system_property_find / _read: the two-step spelling of the same lookup.
// These MUST agree with __system_property_get (which now consults a real
// table, see the property store above): a guest that finds a prop_info and
// then reads nothing from it is a worse answer than one that finds nothing,
// because the first branch reads as "the property exists and is empty".
//
// The handle we hand back is the interned KEY, not a prop_info*. Guests treat
// it as opaque and only ever pass it back to _read, and interning it in the
// table keeps it valid for the process lifetime (the table is fill-once).
extern "C" void* __macapk_arm64___system_property_find(const char* name) {
    if (!name || !*name) return nullptr;
    std::lock_guard<std::mutex> lk(g_macapk_prop_mu);
    auto& t = macapk_prop_table();
    auto it = t.find(name);
    // DIAGNOSTIC (MACAPK_PROP_TRACE): a nullptr return is itself an "absent" signal
    // pairip can branch on, so trace _find lookups too (see _get for rationale).
    static const bool s_find_trace = std::getenv("MACAPK_PROP_TRACE") != nullptr;
    if (s_find_trace) {
        std::fprintf(stderr, "[prop-find] %s => %s\n",
                     name, it == t.end() ? "<ABSENT>" : "present");
        std::fflush(stderr);
    }
    if (it == t.end()) return nullptr;
    return const_cast<char*>(it->first.c_str());
}
extern "C" int __macapk_arm64___system_property_read(
        void* pi, char* name, char* value) {
    if (name)  *name  = '\0';
    if (value) *value = '\0';
    if (!pi) return 0;
    const char* key = static_cast<const char*>(pi);
    if (name) {
        // Bionic's name buffer is PROP_NAME_MAX (32).
        size_t n = std::strlen(key);
        if (n > 31) n = 31;
        std::memcpy(name, key, n);
        name[n] = '\0';
    }
    return value ? __macapk_arm64___system_property_get(key, value) : 0;
}
// Note: __macapk_arm64___system_property_get is defined with the property
// store itself, above (search "the property store (2026-08-21)").

// __system_property_foreach: hand every property in the store to a callback.
//
// THE CONTRACT, quoted verbatim from Bionic's own header
// (bionic/libc/include/sys/system_properties.h, fetched 2026-09-05 from
// raw.githubusercontent.com/aosp-mirror/platform_bionic/master):
//
//     /**
//      * Passes a `prop_info` for each system property to the provided
//      * callback. Use __system_property_read_callback() to read the value of
//      * any of the properties.
//      *
//      * This method is for inspecting and debugging the property system, and
//      * not generally useful.
//      *
//      * Returns 0 on success, or -1 on failure.
//      */
//     int __system_property_foreach(
//         void (* _Nonnull __callback)(const prop_info* _Nonnull __pi,
//                                      void* _Nullable __cookie),
//         void* _Nullable __cookie);
//
// So: 0 on success, -1 on failure, and the callback receives the SAME opaque
// prop_info handle that __system_property_find hands out. That last point is
// what makes this implementable at all for us, because our handle is not a
// real prop_info*: it is the INTERNED KEY, a pointer into the std::map's own
// key storage (see __system_property_find above for why that is safe, and note
// the table is fill-once so the pointer stays valid for the process lifetime).
// Passing the same handle kind here means a guest that does foreach then
// __system_property_read gets a correct answer through the existing path.
//
// WHY THE LOCK IS RELEASED BEFORE THE CALLBACK RUNS. The callback is GUEST
// code, and the whole point of handing it a handle is that it will call back
// into __system_property_read / _get, both of which take g_macapk_prop_mu.
// std::mutex is not recursive, so invoking the callback while holding the lock
// is a guaranteed self-deadlock the first time any real caller uses this the
// way the header tells it to. We therefore snapshot the handles under the lock
// and release it before the walk. That is safe precisely because the table is
// fill-once: Boot fills it before any guest code runs and nothing mutates it
// afterwards, so a snapshot cannot go stale underneath us.
//
// ITERATION ORDER is not part of the contract. Bionic walks its property trie
// and the header promises nothing about order; ours comes out sorted by key
// because the backing store is a std::map. A caller that depends on order is
// already broken on a real device.
//
// A NULL callback returns -1 rather than crashing. Bionic would dereference it
// and die; -1 is the failure value the header already documents, so this is a
// strictly safer answer that stays inside the specified contract.
extern "C" int __macapk_arm64___system_property_foreach(
        void (*propfn)(const void* pi, void* cookie), void* cookie) {
    if (!propfn) return -1;
    // DIAGNOSTIC (env-gated, default off): perturb the property set a guest
    // fingerprints, to test whether an app's control flow is SENSITIVE to the
    // property fingerprint. MACAPK_PROP_INJECT="k=v;k2=v2" is applied ONCE, the
    // first time a guest walks the store (i.e. right before it collects its
    // fingerprint). This is a diagnostic tool, not a device value: prefer
    // non-ro keys (ro.* is write-once and will be refused). Used to localise the
    // pairip VM wall (does the fingerprint move the crash, or is it the ptrace
    // channel). See docs/pairip-vm-length-provenance_2026-09-05.md.
    {
        static std::atomic<int> inj_once{0};
        const char* spec = std::getenv("MACAPK_PROP_INJECT");
        if (spec && *spec && inj_once.fetch_add(1) == 0) {
            std::string s(spec), cur;
            auto flush = [&](){
                size_t eq = cur.find('=');
                if (eq != std::string::npos) {
                    std::string k = cur.substr(0, eq), v = cur.substr(eq + 1);
                    if (!k.empty()) {
                        __macapk_property_put(k.c_str(), v.c_str());
                        std::fprintf(stderr,
                            "[prop-inject] put \"%s\"=\"%s\"\n", k.c_str(), v.c_str());
                    }
                }
                cur.clear();
            };
            for (char c : s) { if (c == ';' || c == ',') flush(); else cur.push_back(c); }
            if (!cur.empty()) flush();
            std::fflush(stderr);
        }
    }
    // MACAPK_PROP_INJECT_FILE=<path> (DIAGNOSTIC, default off, 2026-10-10): bulk-load a
    // getprop-style "key=value" file (one per line, split on first '=') into the property store
    // the FIRST time a guest walks it. The pairip 52.3 integrity VM harvests the WHOLE property
    // store via __system_property_foreach at dispatch record n=0 and folds it into its w28 seed;
    // our synthesized store has ~36 props vs a device's ~912, so the harvest -- and the seed --
    // diverge from the earliest point. This presents a device-faithful property SET to test whether
    // the harvest seeds the entry-index w28 (cont.48). __macapk_property_put adds NEW ro.* props
    // (it only refuses OVERWRITING an existing ro.*), so the device set loads cleanly.
    {
        static std::atomic<int> injf_once{0};
        const char* fspec = std::getenv("MACAPK_PROP_INJECT_FILE");
        if (fspec && *fspec && injf_once.fetch_add(1) == 0) {
            FILE* f = std::fopen(fspec, "r");
            if (f) {
                char line[2048]; long nput = 0;
                while (std::fgets(line, sizeof line, f)) {
                    size_t L = std::strlen(line);
                    while (L && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
                    char* eq = std::strchr(line, '=');
                    if (!eq) continue;
                    *eq = 0;
                    if (line[0]) { __macapk_property_put(line, eq + 1); ++nput; }
                }
                std::fclose(f);
                std::fprintf(stderr, "[prop-inject-file] loaded %ld props from %s\n", nput, fspec);
                std::fflush(stderr);
            }
        }
    }
    std::vector<const char*> handles;
    {
        std::lock_guard<std::mutex> lk(g_macapk_prop_mu);
        auto& t = macapk_prop_table();
        handles.reserve(t.size());
        // The interned key, exactly what __system_property_find would return.
        for (const auto& kv : t) handles.push_back(kv.first.c_str());
    }
    // Log once: a guest walking the property store is worth seeing in a boot
    // log, and the COUNT is the diagnostic that matters (a guest comparing an
    // expected property count against ours will disagree here, and this line
    // is what makes that visible instead of mysterious).
    static std::atomic<int> once{0};
    if (once.fetch_add(1) == 0) {
        std::fprintf(stderr,
            "[arm64-shim] __system_property_foreach: walking %zu propertie(s) "
            "from the Java-filled store (at dispatch record n=%ld)\n",
            handles.size(), g_pairip_disp_ctr.load());
        std::fflush(stderr);
    }
    for (const char* h : handles) propfn(h, cookie);
    return 0;
}

// The rest of the Bionic <sys/system_properties.h> surface, landed 2026-09-05 for
// AOSP parity. Every contract below is quoted from the header or from
// bionic/libc/system_properties/system_properties.cpp (fetched 2026-09-05 from
// raw.githubusercontent.com/aosp-mirror/platform_bionic/main).
//
// THE SERIAL. Bionic packs a property's serial as `valuelen << 24` at construction
// (`prop_info::prop_info`, prop_info.cpp:41: `atomic_store_explicit(&this->serial,
// valuelen << 24, memory_order_relaxed)`) and bumps the low bits on each update. Our
// store is fill-once, so a value's length fully determines its serial and that serial
// is stable for the process lifetime, which is exactly what a caller caching it
// expects to see for an unchanging `ro.*` property on a real device.

// __system_property_read_callback: the API-26 replacement for _read, and the one a
// modern caller uses. Header contract:
//     void __system_property_read_callback(const prop_info* __pi,
//         void (*__callback)(void* __cookie, const char* __name,
//                            const char* __value, uint32_t __serial),
//         void* __cookie);
// NOTE the callback takes the COOKIE FIRST, unlike _foreach's callback. Getting that
// backwards would hand the guest a cookie where it expects a name.
//
// Bionic hands a read-only property's value straight through without copying
// (`SystemProperties::ReadCallback`, system_properties.cpp:242-252: "Read only
// properties don't need to copy the value to a temporary buffer, since it can never
// change"), and copies for mutable ones. Ours are all effectively read-only, but the
// copy for the non-`ro.` case is kept so the callback can never observe a value being
// reallocated by a concurrent late put.
extern "C" void __macapk_arm64___system_property_read_callback(
        const void* pi,
        void (*callback)(void* cookie, const char* name, const char* value,
                         uint32_t serial),
        void* cookie) {
    if (!pi || !callback) return;
    const char* key = static_cast<const char*>(pi);
    const char* direct = nullptr;
    std::string copy;
    uint32_t serial = 0;
    {
        std::lock_guard<std::mutex> lk(g_macapk_prop_mu);
        auto& t = macapk_prop_table();
        auto it = t.find(key);
        if (it == t.end()) {
            // Not a handle we issued. Say so once rather than invoking the callback
            // with invented data.
            static std::atomic<int> n{0};
            if (n.fetch_add(1) < 8) {
                std::fprintf(stderr,
                    "[arm64-shim] __system_property_read_callback: unknown handle %p "
                    "(not one this store issued) -- callback NOT invoked\n", pi);
                std::fflush(stderr);
            }
            return;
        }
        serial = static_cast<uint32_t>(it->second.size()) << 24;
        if (std::strncmp(key, "ro.", 3) == 0) direct = it->second.c_str();
        else                                  copy   = it->second;
    }
    // DIAGNOSTIC (MACAPK_PROP_TRACE): log every property a guest actually READS.
    // pairip folds a property fingerprint into its integrity VM; this shows the
    // EXACT set it reads so we can compare our values against a device's.
    static const bool s_prop_trace = std::getenv("MACAPK_PROP_TRACE") != nullptr;
    if (s_prop_trace) {
        std::fprintf(stderr, "[prop-read] %s = %s\n", key, direct ? direct : copy.c_str());
        std::fflush(stderr);
    }
    callback(cookie, key, direct ? direct : copy.c_str(), serial);
}

// __system_property_serial: "Returns the serial number on success, -1 on error."
extern "C" uint32_t __macapk_arm64___system_property_serial(const void* pi) {
    if (!pi) return static_cast<uint32_t>(-1);
    std::lock_guard<std::mutex> lk(g_macapk_prop_mu);
    auto& t = macapk_prop_table();
    auto it = t.find(static_cast<const char*>(pi));
    if (it == t.end()) return static_cast<uint32_t>(-1);
    return static_cast<uint32_t>(it->second.size()) << 24;
}

// __system_property_area_serial: the process-wide "has anything changed" counter.
// Bionic returns -1 when the area is uninitialised; ours is always initialised (Boot
// fills it before any guest code runs), so it always returns a real value.
extern "C" uint32_t __macapk_arm64___system_property_area_serial(void) {
    return g_macapk_prop_area_serial.load(std::memory_order_acquire);
}

// __system_property_find_nth(n): deprecated, and Bionic implements it ON TOP of
// Foreach, so it must agree with our _foreach exactly. Same interned-key handle.
extern "C" const void* __macapk_arm64___system_property_find_nth(unsigned n) {
    std::lock_guard<std::mutex> lk(g_macapk_prop_mu);
    auto& t = macapk_prop_table();
    if (n >= t.size()) return nullptr;
    auto it = t.begin();
    std::advance(it, static_cast<long>(n));
    return it->first.c_str();
}

// __system_property_set: "Returns 0 on success, or -1 on failure."
//
// We return -1, and that is the FAITHFUL answer rather than a convenience. On a real
// device the property service refuses a write from an ordinary app process that lacks
// the SELinux permission for that property, and an ordinary app has it for essentially
// nothing (`PROP_ERROR_PERMISSION_DENIED`). Accepting the write would be worse than
// refusing it in two ways: it would contradict the read-only contract our handles rely
// on, and it would let a guest silently rewrite the device description that the Java
// half of our own platform is simultaneously answering from android.os.Build.
extern "C" int __macapk_arm64___system_property_set(const char* name,
                                                    const char* value) {
    if (!name) return -1;
    static std::atomic<int> n{0};
    if (n.fetch_add(1) < 32) {
        std::fprintf(stderr,
            "[arm64-shim] __system_property_set(\"%s\", \"%s\") -> -1 "
            "(permission denied, as for any ordinary app process; the store is "
            "read-only and mirrors android.os.Build)\n",
            name, value ? value : "(null)");
        std::fflush(stderr);
    }
    return -1;
}

// __system_property_wait(pi, old_serial, &new_serial, timeout): block until the
// property's serial moves past old_serial, or the relative timeout expires. Returns
// true if it observed a change, false on timeout.
//
// Our store is fill-once, so in practice this blocks for the full timeout and returns
// false. THAT IS THE FAITHFUL ANSWER: a real device does exactly the same for a
// property that never changes, and the alternative (returning true immediately) would
// send the caller round a loop re-reading a value that did not move. A NULL timeout
// means wait forever, which is also what Bionic does, so a caller that asks to block
// on an unchanging property blocks -- the same bug it would have on a device.
// The condvar is signalled by __macapk_property_put, so a genuine late push does wake
// a waiter rather than leaving it stuck until timeout.
extern "C" bool __macapk_arm64___system_property_wait(
        const void* pi, uint32_t old_serial, uint32_t* new_serial_ptr,
        const struct timespec* relative_timeout) {
    auto current = [&]() -> uint32_t {
        if (!pi) return g_macapk_prop_area_serial.load(std::memory_order_acquire);
        auto& t = macapk_prop_table();
        auto it = t.find(static_cast<const char*>(pi));
        if (it == t.end()) return static_cast<uint32_t>(-1);
        return static_cast<uint32_t>(it->second.size()) << 24;
    };
    std::unique_lock<std::mutex> lk(g_macapk_prop_mu);
    uint32_t cur = current();
    if (cur != old_serial) {
        if (new_serial_ptr) *new_serial_ptr = cur;
        return true;
    }
    if (!relative_timeout) {
        g_macapk_prop_cv.wait(lk, [&]{ return current() != old_serial; });
        if (new_serial_ptr) *new_serial_ptr = current();
        return true;
    }
    const auto dur = std::chrono::seconds(relative_timeout->tv_sec)
                   + std::chrono::nanoseconds(relative_timeout->tv_nsec);
    const bool changed = g_macapk_prop_cv.wait_for(
        lk, dur, [&]{ return current() != old_serial; });
    if (changed && new_serial_ptr) *new_serial_ptr = current();
    return changed;
}

// __system_property_wait_any(old_serial): deprecated spelling that waits on the AREA
// serial. Bionic returns the new area serial.
extern "C" uint32_t __macapk_arm64___system_property_wait_any(uint32_t old_serial) {
    uint32_t out = 0;
    __macapk_arm64___system_property_wait(nullptr, old_serial, &out, nullptr);
    return out ? out : g_macapk_prop_area_serial.load(std::memory_order_acquire);
}

// Android NDK ANativeWindow_*. Unity wraps the Surface's window for
// EGL rendering; we don't have a real Android NativeWindow, so we
// return a marker handle and pretend a 1080x1920 buffer (any size
// works for the EGL/GL setup -- it gets re-queried later).
//
// v1.0.153 update: Unity's loadNative dereferences fields of the
// ANativeWindow* (e.g. `ldr x8, [x0, #0x20]`), so a bare uint8 marker
// isn't sufficient -- it'd SEGV on the field access. Provide a 4 KB
// zero-filled buffer so any field access reads 0 (Unity will treat
// the engine state as "not ready" and either fall back to its own
// path or fail gracefully).
alignas(16) static uint8_t g_macapk_dummy_ANativeWindow[4096] = {0};
[[maybe_unused]] alignas(16) static uint8_t g_macapk_dummy_ALooper_buf[4096] = {0};        // legacy: ALooper now uses real per-thread loopers
[[maybe_unused]] alignas(16) static uint8_t g_macapk_dummy_AChoreographer_buf[4096] = {0};  // legacy: AChoreographer now binds to the thread's looper
// MacApkNativeWindow + g_macapk_unity_window + macapk_is_unity_window
// are defined earlier in this file (just before the eglCreateWindowSurface
// bridge, which also needs them).
// If the caller hands us the 4 KB dummy window (it asked for an
// ANativeWindow before a real CAMetalLayer existed) we still know the real
// drawable size as soon as the layer-backed window has been set up, so report
// THAT rather than a 1080x1920 literal an engine would size its viewport and
// render targets from. The literal is only a last resort for a query that
// arrives before any window exists at all.
extern "C" int32_t __macapk_arm64_ANativeWindow_getWidth(void* w) {
    if (macapk_is_unity_window(w)) return g_macapk_unity_window.width;
    if (g_macapk_unity_window.magic == kMacApkNWMagic
        && g_macapk_unity_window.width > 0) {
        return g_macapk_unity_window.width;
    }
    return 1080;
}
extern "C" int32_t __macapk_arm64_ANativeWindow_getHeight(void* w) {
    if (macapk_is_unity_window(w)) return g_macapk_unity_window.height;
    if (g_macapk_unity_window.magic == kMacApkNWMagic
        && g_macapk_unity_window.height > 0) {
        return g_macapk_unity_window.height;
    }
    return 1920;
}
extern "C" int32_t __macapk_arm64_ANativeWindow_setBuffersGeometry(
        void* w, int32_t width, int32_t height, int32_t format) {
    // NDK native_window.h: "The width and height control the number of pixels
    // in the buffers, not the dimensions of the window on screen. If these are
    // different than the window's physical size, then its buffer will be
    // scaled to match that size when compositing it to the screen." 0x0 means
    // the window's own size. AOSP: native_window_set_buffers_user_dimensions
    // + set_buffers_format. ANativeWindow_getWidth/Height keep answering the
    // window's DEFAULT size (NATIVE_WINDOW_WIDTH reaches BufferQueueProducer::
    // query -> mCore->mDefaultWidth), which Unreal divides touch X/Y by.
    if (width < 0 || height < 0 || (width == 0) != (height == 0)) return -EINVAL;
    if (!macapk_is_unity_window(w)) return 0;
    if (format != 0) g_macapk_unity_window.format = format;
    using GeoFn = void (*)(int, int);
    static GeoFn set_geo = reinterpret_cast<GeoFn>(
        dlsym(RTLD_DEFAULT, "CocoaSetNativeEglBufferGeometry"));
    if (set_geo) set_geo(width, height);
    static std::atomic<int> n{0};
    if (n.fetch_add(1) < 8)
        std::fprintf(stderr, "[arm64-shim] ANativeWindow_setBuffersGeometry(%d x %d, "
                     "format %d)%s\n", width, height, format,
                     set_geo ? "" : " -- no Cocoa bridge, ignored");
    return 0;
}
extern "C" void __macapk_arm64_ANativeWindow_release(void* /*w*/) {}
extern "C" void __macapk_arm64_ANativeWindow_acquire(void* /*w*/) {}
// The Java Surface the guest handed to ANativeWindow_fromSurface, kept as a
// JNI GLOBAL ref so ANativeWindow_toSurface can hand the SAME object back.
// NDK native_window_jni.h documents toSurface as the exact inverse of
// fromSurface ("Return a Java Surface object derived from the ANativeWindow"),
// so preserving object identity is the faithful behavior -- fabricating an
// unrelated Surface would break any caller that passes it back into
// MediaCodec.configure or compares it against the one it started with.
static std::mutex g_macapk_nw_surface_mu;
static jobject    g_macapk_nw_surface_gref = nullptr;
static void macapk_remember_native_window_surface(jobject surface) {
    if (!surface) return;
    AttachGuard ag;
    if (!ag.env) return;
    jobject fresh = ag.env->NewGlobalRef(surface);
    if (!fresh) { if (ag.env->ExceptionCheck()) ag.env->ExceptionClear(); return; }
    jobject old = nullptr;
    {
        std::lock_guard<std::mutex> lk(g_macapk_nw_surface_mu);
        old = g_macapk_nw_surface_gref;
        g_macapk_nw_surface_gref = fresh;
    }
    if (old) ag.env->DeleteGlobalRef(old);
    // Tell the framework which SurfaceView's Surface a native producer now
    // feeds (Surface.macapkNoteNativeWindowConsumer). AOSP composites that
    // surface BELOW its window and the SurfaceView punches a hole for it
    // (android14 SurfaceView.java :512-533, clearSurfaceViewPort :579-597);
    // our native-EGL layer can only do the same once the framework knows the
    // owner (cocoa_bridge.mm macapk_guest_layer_z_for). Never touch an app's
    // pending exception; a Surface without the method (an older framework
    // jar) is simply not noted, which keeps the legacy above-window slot.
    // MACAPK_SV_GUEST_BELOW=0 (exactly "0", as the Java side reads it) skips the
    // whole block: no GetObjectClass / GetMethodID / upcall, the pre-change path.
    static const bool kGuestBelow = [] {
        const char* e = std::getenv("MACAPK_SV_GUEST_BELOW");
        return !(e && e[0] == '0' && e[1] == '\0');
    }();
    if (kGuestBelow && !ag.env->ExceptionCheck()) {
        jclass sc = ag.env->GetObjectClass(surface);
        jmethodID note = sc ? ag.env->GetMethodID(sc, "macapkNoteNativeWindowConsumer", "()V")
                            : nullptr;
        if (note) ag.env->CallVoidMethod(surface, note);
        if (ag.env->ExceptionCheck()) ag.env->ExceptionClear();
        if (sc) ag.env->DeleteLocalRef(sc);
    }
}
extern "C" void* __macapk_arm64_ANativeWindow_fromSurface(
        void* /*env*/, void* surface) {
    macapk_remember_native_window_surface(reinterpret_cast<jobject>(surface));
    // v1.0.162: return a real ANativeWindow backed by the Cocoa
    // CAMetalLayer (pre-created on the main thread in drawInMTKView for
    // Unity). v1.0.572: prefer the GENERIC ensure-entry, which also
    // creates the dedicated layer ON DEMAND when this call arrives on the
    // main thread -- AGDK GameActivity (Minecraft) and other native-EGL
    // engines call ANativeWindow_fromSurface from the UI thread inside
    // surfaceCreated, where the layer can be attached synchronously.
    // Until a layer exists we fall back to the 4 KB dummy so we never
    // crash.
    using GetLayerFn = void* (*)(int*, int*);
    static GetLayerFn get_layer = []() -> GetLayerFn {
        if (void* f = dlsym(RTLD_DEFAULT, "CocoaEnsureNativeEglLayer"))
            return reinterpret_cast<GetLayerFn>(f);
        return reinterpret_cast<GetLayerFn>(
            dlsym(RTLD_DEFAULT, "CocoaGetUnityRenderLayer"));
    }();
    int w = 0, h = 0;
    void* layer = get_layer ? get_layer(&w, &h) : nullptr;
    static std::atomic<int> n{0};
    int c = n.fetch_add(1);
    if (layer && w > 0 && h > 0) {
        g_macapk_unity_window.magic  = kMacApkNWMagic;
        g_macapk_unity_window.width  = w;
        g_macapk_unity_window.height = h;
        g_macapk_unity_window.format = 1; // RGBA_8888
        g_macapk_unity_window.layer  = layer;
        if (c < 8) {
            std::fprintf(stderr,
                "[arm64-shim] ANativeWindow_fromSurface -> real window %p "
                "(layer=%p %dx%d)\n",
                (void*)&g_macapk_unity_window, layer, w, h);
            std::fflush(stderr);
        }
        return &g_macapk_unity_window;
    }
    if (c < 8) {
        std::fprintf(stderr,
            "[arm64-shim] ANativeWindow_fromSurface: layer not ready "
            "(get_layer=%p) -> dummy\n", (void*)get_layer);
        std::fflush(stderr);
    }
    return g_macapk_dummy_ANativeWindow;
}
// The CAMetalLayer behind an ANativeWindow ANativeWindow_fromSurface returned
// (NULL for the dummy): what vkCreateAndroidSurfaceKHR presents to.
extern "C" void* __macapk_native_window_layer(void* w) {
    return macapk_is_unity_window(w) ? g_macapk_unity_window.layer : nullptr;
}
extern "C" int32_t __macapk_arm64_ANativeWindow_getFormat(void* w) {
    if (macapk_is_unity_window(w)) return g_macapk_unity_window.format;
    return 1; // WINDOW_FORMAT_RGBA_8888
}
// ANativeWindow_toSurface(env, window) -- NDK native_window_jni.h (API 26+):
// "Return a Java Surface object derived from the ANativeWindow", the inverse of
// ANativeWindow_fromSurface. Absent entirely before this, so a STRONG-undefined
// reference (which is what the NDK emits when minSdkVersion >= 26, since the
// symbol is then guaranteed present) bound to the loader's unresolved trap and
// aborted the whole process on first call. Hand back the Surface the guest
// itself gave us, as a LOCAL ref (the caller owns it, like any JNI return);
// NULL when no real Surface ever arrived, which is the documented answer for a
// window that has no Java counterpart.
extern "C" void* __macapk_arm64_ANativeWindow_toSurface(void* /*env*/,
                                                        void* /*w*/) {
    jobject gref = nullptr;
    {
        std::lock_guard<std::mutex> lk(g_macapk_nw_surface_mu);
        gref = g_macapk_nw_surface_gref;
    }
    if (!gref) return nullptr;
    AttachGuard ag;
    if (!ag.env) return nullptr;
    jobject local = ag.env->NewLocalRef(gref);
    if (!local && ag.env->ExceptionCheck()) ag.env->ExceptionClear();
    return local;
}

// ANativeWindow_lock(window, outBuffer, inOutDirtyBounds) -- the CPU
// software-rendering entry point. NDK android/native_window.h:
//
//   typedef struct ANativeWindow_Buffer {
//       int32_t width; int32_t height; int32_t stride; int32_t format;
//       void* bits; uint32_t reserved[6];
//   } ANativeWindow_Buffer;
//   int32_t ANativeWindow_lock(ANativeWindow*, ANativeWindow_Buffer* outBuffer,
//                              ARect* inOutDirtyBounds);
//
// This used to `return 0` (success) WITHOUT touching outBuffer, so a caller's
// stack-allocated ANativeWindow_Buffer kept whatever garbage was already there
// and the very next `memcpy(buf.bits, ...)` wrote through an uninitialised
// pointer -- a SIGSEGV, or silent corruption of an unrelated mapping. Hand out
// a real, correctly-described, zero-filled buffer instead, so the documented
// contract (return 0 => outBuffer is usable) actually holds.
//
// The buffer is not yet composited to the CAMetalLayer on unlockAndPost: that
// blit belongs with the Canvas/SurfaceView software-present path outside this
// file. Until it lands, unlockAndPost reports the honest "posted nothing"
// outcome by returning 0 for a valid lock (the NDK contract has no "posted but
// not displayed" code) while never handing back an unusable pointer.
namespace {
struct MacApkANWBuffer {
    int32_t  width, height, stride, format;
    void*    bits;
    uint32_t reserved[6];
};
struct MacApkARect { int32_t left, top, right, bottom; };
std::mutex           g_anw_lock_mu;
std::vector<uint8_t> g_anw_lock_pixels;
bool                 g_anw_locked = false;
}  // namespace
extern "C" int32_t __macapk_arm64_ANativeWindow_lock(
        void* w, void* outBuffer, void* inOutDirtyBounds) {
    auto* out = reinterpret_cast<MacApkANWBuffer*>(outBuffer);
    if (!out) return -EINVAL;
    const int32_t width  = __macapk_arm64_ANativeWindow_getWidth(w);
    const int32_t height = __macapk_arm64_ANativeWindow_getHeight(w);
    if (width <= 0 || height <= 0) return -EINVAL;
    const size_t need = size_t(width) * size_t(height) * 4u;
    std::lock_guard<std::mutex> lk(g_anw_lock_mu);
    if (g_anw_locked) return -EBUSY;   // a second lock without unlockAndPost
    if (g_anw_lock_pixels.size() != need) {
        // Bionic and Darwin agree on errno 1..34, so EINVAL(22)/EBUSY(16)/
        // ENOMEM(12) need no mac2lin translation on the way out.
        try { g_anw_lock_pixels.assign(need, 0); }
        catch (const std::exception&) { return -ENOMEM; }
    }
    g_anw_locked  = true;
    out->width    = width;
    out->height   = height;
    out->stride   = width;                 // stride is in PIXELS, not bytes
    out->format   = __macapk_arm64_ANativeWindow_getFormat(w);
    out->bits     = g_anw_lock_pixels.data();
    std::memset(out->reserved, 0, sizeof(out->reserved));
    // inOutDirtyBounds is in/out: the caller asks for a region and the window
    // reports back the region it must actually redraw ("often extended"). We
    // keep no partial-update history, so the honest answer is the whole
    // surface.
    if (auto* r = reinterpret_cast<MacApkARect*>(inOutDirtyBounds)) {
        r->left = 0; r->top = 0; r->right = width; r->bottom = height;
    }
    return 0;
}
extern "C" int32_t __macapk_arm64_ANativeWindow_unlockAndPost(void* /*w*/) {
    std::lock_guard<std::mutex> lk(g_anw_lock_mu);
    if (!g_anw_locked) return -EINVAL;    // unlock without a matching lock
    g_anw_locked = false;
    return 0;
}

// =========================================================================
// ARM32 (arm32rc) siblings of the ANativeWindow_* family above, plus the
// EGL bridge those windows are ultimately fed into (2026-07-28). See
// docs/anativewindow-bridge_2026-07-28.md for the full contract, the
// measured Smash Hit UND symbol list, and the exact kPointerAwareImports /
// kPointerAwareWideImports diff main.cpp's owner needs to apply -- adding
// these __macapk_shim_<name> exports alone does nothing until that lands.
//
// WHY BOTH FAMILIES: the KNOWN OPEN catalog row (docs/hard-fixes-catalog.md)
// and Current_State.md's v1.0.812 entry name ANativeWindow_fromSurface as
// "the single thing standing between Smash Hit and a renderer". That is
// necessary but not sufficient: `llvm-readelf --dyn-syms` on Smash Hit's
// libsmashhit.so (armeabi-v7a) shows it ALSO imports eglGetDisplay,
// eglInitialize, eglChooseConfig, eglGetConfigAttrib, eglCreateContext,
// eglCreateWindowSurface, eglMakeCurrent, eglSwapBuffers, eglQuerySurface,
// eglDestroySurface, eglDestroyContext, eglTerminate -- and NONE of them had
// a __macapk_shim_<name> or a kPointerAwareImports entry, so main.cpp's own
// resolver (the `resolve_import` lambda, ~line 5530) falls through to
// "is the bare name resolvable in the runtime namespace" -- true, because
// ANGLE's libEGL.dylib exports all of these under their real names -- and
// binds RAW to ANGLE's real (64-bit-pointer-returning) functions. That is
// the exact "hands Darwin a 32-bit guest vaddr as a 64-bit pointer" hazard
// main.cpp's own comment warns about for memmem: eglGetDisplay's real
// EGLDisplay return value gets truncated to 32 bits the moment recompiled
// ARM32 code stores it in a register, and every later call that hands that
// truncated value back (eglInitialize, eglChooseConfig, ...) receives a
// wrong pointer. It had gone unnoticed only because GameActivity's own
// control flow gates ALL of EGL setup on first getting a non-null
// ANativeWindow* from fromSurface, and fromSurface has been panic-stubbing
// to 0 -- so this class of bug was dormant, not absent, and fixing
// ANativeWindow alone would have traded one silent failure for a new,
// much more confusing one (a real EGLDisplay pointer truncated to 32 bits
// used as a 64-bit pointer the moment the app's own gate opened).
//
// DESIGN: every value that crosses this ABI boundary (JNIEnv*, jobject,
// EGLDisplay, EGLConfig, EGLContext, EGLSurface, ANativeWindow*) is a
// 32-bit HANDLE-TABLE TOKEN on the ARM32 side, exactly like every other
// JNI-shaped value already in this file -- verified against
// macapk_arm32_jni_call_core (the JVM-calls-into-guest marshaller, ~line
// 35162), which mints a guest handle via __macapk_jni_make_handle for
// every jobject/jclass it hands to recompiled ARM32 code (see its
// `detect()` lambda and the AAPCS32-descriptor-walk branch, lines
// 35183-35257). So the SAME __macapk_jni_make_handle / resolve_handle /
// release_handle table (used elsewhere in this file for FILE*, jclass,
// jmethodID) is reused here for EGL handles and ANativeWindow* -- not a
// new mechanism, the established one. Where an __macapk_arm64_egl* twin
// already exists (eglGetDisplay, eglInitialize, eglChooseConfig,
// eglCreateContext, eglCreateWindowSurface, eglMakeCurrent, eglSwapBuffers)
// we resolve handles to real host pointers and call THAT function directly
// -- reusing its blob-cache install, EGL_RECORDABLE_ANDROID neutralization,
// Vulkan-backend forcing, and (for eglCreateWindowSurface) the
// ANativeWindow* -> CAMetalLayer swap, rather than re-deriving any of it.
// The five with no arm64 twin (eglGetConfigAttrib, eglQuerySurface,
// eglDestroySurface, eglDestroyContext, eglTerminate) are plain
// dlsym-resolved forwards -- arm64 never needed a wrapper for these because
// a raw 64-bit pointer needs no translation, only ARM32 does.
//
// NDK CONTRACT (fetched 2026-07-28, quoted in full in the docs note):
// android.googlesource.com/platform/frameworks/native/+/refs/heads/
// android10-release/include/android/native_window_jni.h --
// ANativeWindow_fromSurface "acquires a reference ... be sure to use
// ANativeWindow_release() when done with it so that it doesn't leak."
// .../libs/nativewindow/include/android/native_window.h --
// ANativeWindow_acquire/_release are the manual refcount pair;
// ANativeWindow_setBuffersGeometry: "if 0 is supplied [for width/height/
// format] then the window's base value will come back in force";
// WINDOW_FORMAT_RGBA_8888 = AHARDWAREBUFFER_FORMAT_R8G8B8A8_UNORM = 1,
// WINDOW_FORMAT_RGBX_8888 = 2, WINDOW_FORMAT_RGB_565 = 4 (hardware_buffer.h,
// same branch). EGL signatures cross-checked against this repo's own
// vendored thirdparty/angle/include/EGL/egl.h.
//
// SCOPE: ANativeWindow_lock/_unlockAndPost are DELIBERATELY not given ARM32
// shims here. Their ANativeWindow_Buffer out-struct embeds a `void* bits`
// field whose size (4 bytes on the ARM32 guest side, 8 on the host) makes a
// naive reinterpret of the guest struct wrong, and the pixel storage would
// need to live inside the guest's own 4 GiB arena for guest code to write
// through it -- real work, and Smash Hit's measured UND list does not
// reference either symbol (it is a native-EGL renderer, not a software
// Canvas one). Left as a genuinely unresolved import (an honest panic-stub
// warning) rather than a half-correct implementation; see OPEN QUESTIONS in
// the docs note. Likewise AAssetManager_*/AConfiguration_*/ALooper_* are
// ALSO completely unbridged for ARM32 (measured, same audit) but are out of
// scope for "get a renderer" and are flagged as NEXT, not fixed here.

extern "C" uint32_t __macapk_shim_ANativeWindow_fromSurface(
        uint32_t /*env_h*/, uint32_t surface_h, uint32_t, uint32_t) {
    // Mirrors the arm64 twin: it ignores its own env parameter too (the
    // one place it needs a JNIEnv*, stashing the Surface as a global ref,
    // re-derives a thread-correct one via AttachGuard internally instead
    // of trusting the caller's). Only `surface` needs decoding here.
    jobject surface = macapk_jni::obj_for<jobject>(surface_h);
    void* host_window = __macapk_arm64_ANativeWindow_fromSurface(
        nullptr, reinterpret_cast<void*>(surface));
    static std::atomic<int> n{0};
    int c = n.fetch_add(1);
    if (c < 8) {
        std::fprintf(stderr,
            "[arm32-shim] ANativeWindow_fromSurface(surface_h=0x%x) -> "
            "host=%p%s\n", surface_h, host_window,
            host_window ? "" : " (NULL -- layer not ready yet)");
        std::fflush(stderr);
    }
    return host_window ? __macapk_jni_make_handle(host_window) : 0;
}
extern "C" uint32_t __macapk_shim_ANativeWindow_getWidth(
        uint32_t w_h, uint32_t, uint32_t, uint32_t) {
    void* w = __macapk_jni_resolve_handle(w_h);
    return static_cast<uint32_t>(__macapk_arm64_ANativeWindow_getWidth(w));
}
extern "C" uint32_t __macapk_shim_ANativeWindow_getHeight(
        uint32_t w_h, uint32_t, uint32_t, uint32_t) {
    void* w = __macapk_jni_resolve_handle(w_h);
    return static_cast<uint32_t>(__macapk_arm64_ANativeWindow_getHeight(w));
}
extern "C" uint32_t __macapk_shim_ANativeWindow_getFormat(
        uint32_t w_h, uint32_t, uint32_t, uint32_t) {
    void* w = __macapk_jni_resolve_handle(w_h);
    return static_cast<uint32_t>(__macapk_arm64_ANativeWindow_getFormat(w));
}
extern "C" uint32_t __macapk_shim_ANativeWindow_setBuffersGeometry(
        uint32_t w_h, uint32_t width, uint32_t height, uint32_t format) {
    void* w = __macapk_jni_resolve_handle(w_h);
    return static_cast<uint32_t>(__macapk_arm64_ANativeWindow_setBuffersGeometry(
        w, static_cast<int32_t>(width), static_cast<int32_t>(height),
        static_cast<int32_t>(format)));
}
// Real Android refcounts ANativeWindow; ours is the process-wide
// g_macapk_unity_window singleton (never allocated/freed per-call), so the
// arm64 twins are genuine no-ops and these mirror that exactly -- do NOT
// release the handle here (a stray extra release/acquire pair from the
// guest must not make a LATER, legitimate getWidth/getHeight/etc. on the
// same window start failing).
extern "C" uint32_t __macapk_shim_ANativeWindow_release(
        uint32_t w_h, uint32_t, uint32_t, uint32_t) {
    __macapk_arm64_ANativeWindow_release(__macapk_jni_resolve_handle(w_h));
    return 0;
}
extern "C" uint32_t __macapk_shim_ANativeWindow_acquire(
        uint32_t w_h, uint32_t, uint32_t, uint32_t) {
    __macapk_arm64_ANativeWindow_acquire(__macapk_jni_resolve_handle(w_h));
    return 0;
}
// Not in Smash Hit's measured UND list (nothing currently calls this on
// ARM32); implemented for parity with the arm64 family and because it is
// the trivial logical inverse of fromSurface (no ABI-width struct issue
// like lock/unlockAndPost has), so a future ARM32 NDK app doesn't reopen
// this investigation for one more symbol.
extern "C" uint32_t __macapk_shim_ANativeWindow_toSurface(
        uint32_t /*env_h*/, uint32_t w_h, uint32_t, uint32_t) {
    void* w = __macapk_jni_resolve_handle(w_h);
    jobject surf = static_cast<jobject>(
        __macapk_arm64_ANativeWindow_toSurface(nullptr, w));
    return surf ? __macapk_jni_make_handle(surf) : 0;
}

// ---- EGL bridge (ARM32 handle <-> arm64/real-pointer translation only;
// see the section banner above for why this is in scope). ----

extern "C" uint32_t __macapk_shim_eglGetDisplay(
        uint32_t display_id, uint32_t, uint32_t, uint32_t) {
    // EGL_DEFAULT_DISPLAY is ((EGLNativeDisplayType)0); any other value a
    // guest passes is not a real host pointer either, but ANGLE only ever
    // looks at "is it the default" here, so passing the raw 32-bit value
    // through unrebased is what every other guest ABI (including arm64
    // Stage-6, which never translates this arg) already does.
    void* dpy = __macapk_arm64_eglGetDisplay(
        reinterpret_cast<void*>(static_cast<uintptr_t>(display_id)));
    return dpy ? __macapk_jni_make_handle(dpy) : 0;
}
extern "C" uint32_t __macapk_shim_eglInitialize(
        uint32_t dpy_h, uint32_t major_addr, uint32_t minor_addr, uint32_t) {
    void* dpy = __macapk_jni_resolve_handle(dpy_h);
    if (!dpy) return 0;
    int32_t major = 0, minor = 0;
    unsigned r = __macapk_arm64_eglInitialize(dpy, &major, &minor);
    if (r) {
        if (major_addr) std::memcpy(gptr_mut(major_addr), &major, sizeof(int32_t));
        if (minor_addr) std::memcpy(gptr_mut(minor_addr), &minor, sizeof(int32_t));
    }
    return r;
}
// 5 args (dpy, attrib_list, configs, config_size, num_config) -- the 5th
// is stack-spilled per AAPCS32, read via `sp` like every other wide shim
// in this file (see glReadPixels above). Needs kPointerAwareWideImports
// too, not just kPointerAwareImports (see docs note for the exact diff).
extern "C" uint32_t __macapk_shim_eglChooseConfig(
        uint32_t dpy_h, uint32_t attribs_addr, uint32_t configs_addr,
        uint32_t cfg_size, uint32_t sp) {
    uint32_t num_config_addr = stack_arg(sp, 0);
    void* dpy = __macapk_jni_resolve_handle(dpy_h);
    if (!dpy) return 0;
    const int32_t* attribs = attribs_addr
        ? reinterpret_cast<const int32_t*>(gptr_const(attribs_addr)) : nullptr;
    // Guest-supplied count; clamp defensively (real callers ask for single
    // digits to low dozens) rather than trust an arbitrary register value
    // for a host allocation size.
    uint32_t n_req = cfg_size;
    if (n_req > 1024) n_req = 1024;
    std::vector<void*> real_configs(n_req);
    int32_t num_config = 0;
    unsigned r = __macapk_arm64_eglChooseConfig(
        dpy, attribs, n_req ? real_configs.data() : nullptr,
        static_cast<int32_t>(n_req), &num_config);
    if (r) {
        if (configs_addr && n_req) {
            int32_t* out = reinterpret_cast<int32_t*>(gptr_mut(configs_addr));
            int32_t n = num_config < static_cast<int32_t>(n_req)
                ? num_config : static_cast<int32_t>(n_req);
            for (int32_t i = 0; i < n; ++i)
                out[i] = static_cast<int32_t>(__macapk_jni_make_handle(real_configs[i]));
        }
        if (num_config_addr)
            std::memcpy(gptr_mut(num_config_addr), &num_config, sizeof(int32_t));
    }
    return r;
}
// No arm64 twin (a raw 64-bit EGLConfig/out-pointer needs no translation
// there); plain dlsym forward + handle/pointer translation.
extern "C" uint32_t __macapk_shim_eglGetConfigAttrib(
        uint32_t dpy_h, uint32_t config_h, uint32_t attribute,
        uint32_t value_addr) {
    using Fn = unsigned (*)(void*, void*, int32_t, int32_t*);
    static Fn real =
        reinterpret_cast<Fn>(dlsym(RTLD_DEFAULT, "eglGetConfigAttrib"));
    void* dpy = __macapk_jni_resolve_handle(dpy_h);
    void* config = __macapk_jni_resolve_handle(config_h);
    if (!dpy || !config || !real) return 0;
    int32_t value = 0;
    unsigned r = real(dpy, config, static_cast<int32_t>(attribute), &value);
    if (r && value_addr) std::memcpy(gptr_mut(value_addr), &value, sizeof(int32_t));
    return r;
}
extern "C" uint32_t __macapk_shim_eglCreateContext(
        uint32_t dpy_h, uint32_t config_h, uint32_t share_h,
        uint32_t attribs_addr) {
    void* dpy    = __macapk_jni_resolve_handle(dpy_h);
    void* config = __macapk_jni_resolve_handle(config_h);
    // resolve_handle(0) == nullptr == EGL_NO_CONTEXT, so share_h==0 (the
    // overwhelmingly common case -- no context sharing) needs no special
    // casing here.
    void* share  = __macapk_jni_resolve_handle(share_h);
    const int32_t* attribs = attribs_addr
        ? reinterpret_cast<const int32_t*>(gptr_const(attribs_addr)) : nullptr;
    void* ctx = __macapk_arm64_eglCreateContext(dpy, config, share, attribs);
    return ctx ? __macapk_jni_make_handle(ctx) : 0;
}
// Reuses __macapk_arm64_egl_create_window_surface_bridge directly, which
// already detects our MacApkNativeWindow by magic and swaps in ->layer
// (the real CAMetalLayer) before calling ANGLE's real eglCreateWindowSurface
// -- exactly the step that made the analogous arm64/Unity GOT-bypass bug
// (v1.0.172->173, see the ALIAS comment above __macapk_arm64_eglCreateWindowSurface)
// a SIGSEGV instead of a picture. Getting this reuse right is why
// ANativeWindow_fromSurface's ARM32 handle above resolves to the SAME
// underlying host pointer arm64 windows use, not a parallel struct.
extern "C" uint32_t __macapk_shim_eglCreateWindowSurface(
        uint32_t dpy_h, uint32_t config_h, uint32_t win_h,
        uint32_t attribs_addr) {
    void* dpy    = __macapk_jni_resolve_handle(dpy_h);
    void* config = __macapk_jni_resolve_handle(config_h);
    void* win    = __macapk_jni_resolve_handle(win_h);
    const int32_t* attribs = attribs_addr
        ? reinterpret_cast<const int32_t*>(gptr_const(attribs_addr)) : nullptr;
    void* surf = __macapk_arm64_egl_create_window_surface_bridge(
        dpy, config, win, attribs);
    return surf ? __macapk_jni_make_handle(surf) : 0;
}
extern "C" uint32_t __macapk_shim_eglMakeCurrent(
        uint32_t dpy_h, uint32_t draw_h, uint32_t read_h, uint32_t ctx_h) {
    // resolve_handle(0) == nullptr for draw/read/ctx == EGL_NO_SURFACE /
    // EGL_NO_CONTEXT, matching real EGL's NULL-valued sentinels exactly.
    void* dpy  = __macapk_jni_resolve_handle(dpy_h);
    void* draw = __macapk_jni_resolve_handle(draw_h);
    void* read = __macapk_jni_resolve_handle(read_h);
    void* ctx  = __macapk_jni_resolve_handle(ctx_h);
    return __macapk_arm64_eglMakeCurrent(dpy, draw, read, ctx);
}
extern "C" uint32_t __macapk_shim_eglSwapBuffers(
        uint32_t dpy_h, uint32_t surface_h, uint32_t, uint32_t) {
    void* dpy  = __macapk_jni_resolve_handle(dpy_h);
    void* surf = __macapk_jni_resolve_handle(surface_h);
    return __macapk_arm64_eglSwapBuffers(dpy, surf);
}
extern "C" uint32_t __macapk_shim_eglQuerySurface(
        uint32_t dpy_h, uint32_t surface_h, uint32_t attribute,
        uint32_t value_addr) {
    using Fn = unsigned (*)(void*, void*, int32_t, int32_t*);
    static Fn real = reinterpret_cast<Fn>(dlsym(RTLD_DEFAULT, "eglQuerySurface"));
    void* dpy  = __macapk_jni_resolve_handle(dpy_h);
    void* surf = __macapk_jni_resolve_handle(surface_h);
    if (!dpy || !surf || !real) return 0;
    int32_t value = 0;
    unsigned r = real(dpy, surf, static_cast<int32_t>(attribute), &value);
    if (r && value_addr) std::memcpy(gptr_mut(value_addr), &value, sizeof(int32_t));
    return r;
}
extern "C" uint32_t __macapk_shim_eglDestroySurface(
        uint32_t dpy_h, uint32_t surface_h, uint32_t, uint32_t) {
    using Fn = unsigned (*)(void*, void*);
    static Fn real = reinterpret_cast<Fn>(dlsym(RTLD_DEFAULT, "eglDestroySurface"));
    void* dpy  = __macapk_jni_resolve_handle(dpy_h);
    void* surf = __macapk_jni_resolve_handle(surface_h);
    if (!dpy || !surf || !real) return 0;
    unsigned r = real(dpy, surf);
    if (r) __macapk_jni_release_handle(surface_h);
    return r;
}
extern "C" uint32_t __macapk_shim_eglDestroyContext(
        uint32_t dpy_h, uint32_t ctx_h, uint32_t, uint32_t) {
    using Fn = unsigned (*)(void*, void*);
    static Fn real = reinterpret_cast<Fn>(dlsym(RTLD_DEFAULT, "eglDestroyContext"));
    void* dpy = __macapk_jni_resolve_handle(dpy_h);
    void* ctx = __macapk_jni_resolve_handle(ctx_h);
    if (!dpy || !ctx || !real) return 0;
    unsigned r = real(dpy, ctx);
    if (r) __macapk_jni_release_handle(ctx_h);
    return r;
}
extern "C" uint32_t __macapk_shim_eglTerminate(
        uint32_t dpy_h, uint32_t, uint32_t, uint32_t) {
    // Through the arm64 twin so the AOSP refcount sees it: the ARM32
    // eglInitialize above reaches __macapk_arm64_eglInitialize, which counted.
    void* dpy = __macapk_jni_resolve_handle(dpy_h);
    if (!dpy) return 0;
    return __macapk_arm64_eglTerminate(dpy);
}

// =========================================================================
// Android NDK AConfiguration_* (android/configuration.h). SmashHit and other
// NDK games read the device configuration to pick asset variants and set up
// input. Real Android backs this with the AssetManager's ResTable_config; we
// have no Android resource table, so AConfiguration_fromAssetManager fills a
// faithful phone-class configuration derived from the live Mac.apk canvas
// (orientation from the window aspect, dp sizes from the canvas points). This
// is the honest "what device is this" answer, not a zero stub -- callers that
// branch on orientation / density / sdkVersion get correct values.
//
// Constant values verified from NDK android/configuration.h. The opaque
// AConfiguration is our own struct (apps only ever hold the pointer).
// =========================================================================
namespace {
enum {
    MACAPK_ACONF_ORIENTATION_ANY = 0, MACAPK_ACONF_ORIENTATION_PORT = 1,
    MACAPK_ACONF_ORIENTATION_LAND = 2,
    MACAPK_ACONF_TOUCHSCREEN_FINGER = 3,
    MACAPK_ACONF_DENSITY_XHIGH = 320,
    MACAPK_ACONF_KEYBOARD_NOKEYS = 1,
    MACAPK_ACONF_KEYBOARD_QWERTY = 2,   // <android/configuration.h> ACONFIGURATION_KEYBOARD_QWERTY
    MACAPK_ACONF_NAVIGATION_NONAV = 1,
    MACAPK_ACONF_KEYSHIDDEN_NO = 1,     // ACONFIGURATION_KEYSHIDDEN_NO
    MACAPK_ACONF_KEYSHIDDEN_YES = 2,
    MACAPK_ACONF_NAVHIDDEN_YES = 2,
    MACAPK_ACONF_SCREENSIZE_NORMAL = 2,
    MACAPK_ACONF_SCREENLONG_YES = 2,
    MACAPK_ACONF_UI_MODE_TYPE_NORMAL = 1,
    MACAPK_ACONF_UI_MODE_NIGHT_NO = 1,
    MACAPK_ACONF_LAYOUTDIR_LTR = 1,
    MACAPK_ACONF_SDK_VERSION = 29,   // mirrors android.os.Build.VERSION.SDK_INT
};
// The host keyboard (MACAPK_HOST_KEYBOARD, default ON; the same gate and spelling as the Java
// InputManager.MACAPK_HOST_KEYBOARD, "0" is the only off value): the Mac's keyboard is a
// physical alphabetic keyboard, so the native Configuration says what the Java one does
// (android.content.res.Configuration keyboard = KEYBOARD_QWERTY, keyboardHidden = NO, which is
// what AOSP's DisplayContent.computeScreenConfiguration derives from a non-virtual
// KEYBOARD_TYPE_ALPHABETIC device; ResourcesImpl.updateConfiguration android14-release :456-462 hands the
// asset manager keyboardHidden unchanged unless hardKeyboardHidden is YES). Values from
// <android/configuration.h> android14-release :147-207 (NOKEYS 1, QWERTY 2, KEYSHIDDEN_NO 1, _YES 2).
// =0 keeps NOKEYS / KEYSHIDDEN_YES, byte-identical to before.
// docs/host-keyboard-device_2026-10-01.md
static bool macapk_host_keyboard_on() {
    static const bool on = []{ const char* e = getenv("MACAPK_HOST_KEYBOARD");
                               return !(e && e[0] == '0' && e[1] == 0); }();
    return on;
}
struct MacApkAConfig {
    int32_t mcc = 0, mnc = 0;
    char language[2] = {'e','n'};
    char country[2]  = {'U','S'};
    int32_t orientation = MACAPK_ACONF_ORIENTATION_ANY;
    int32_t touchscreen = MACAPK_ACONF_TOUCHSCREEN_FINGER;
    int32_t density = MACAPK_ACONF_DENSITY_XHIGH;
    int32_t keyboard = macapk_host_keyboard_on() ? MACAPK_ACONF_KEYBOARD_QWERTY : MACAPK_ACONF_KEYBOARD_NOKEYS;
    int32_t navigation = MACAPK_ACONF_NAVIGATION_NONAV;
    int32_t keysHidden = macapk_host_keyboard_on() ? MACAPK_ACONF_KEYSHIDDEN_NO : MACAPK_ACONF_KEYSHIDDEN_YES;
    int32_t navHidden = MACAPK_ACONF_NAVHIDDEN_YES;
    int32_t sdkVersion = MACAPK_ACONF_SDK_VERSION;
    int32_t screenSize = MACAPK_ACONF_SCREENSIZE_NORMAL;
    int32_t screenLong = MACAPK_ACONF_SCREENLONG_YES;
    int32_t uiModeType = MACAPK_ACONF_UI_MODE_TYPE_NORMAL;
    int32_t uiModeNight = MACAPK_ACONF_UI_MODE_NIGHT_NO;
    int32_t layoutDirection = MACAPK_ACONF_LAYOUTDIR_LTR;
    int32_t screenWidthDp = 0;
    int32_t screenHeightDp = 0;
    int32_t smallestScreenWidthDp = 0;
};
// Query the live canvas size (logical points) from the runtime's Cocoa side.
// CocoaPhoneWidth/Height live in namespace macapk in the runtime binary; we
// resolve their mangled names via dlsym so the shim dylib needn't link the
// runtime. Falls back to a 16:9 landscape default if unavailable.
static void macapk_canvas_size(int* w, int* h) {
    using IntFn = int (*)();
    static IntFn wf = reinterpret_cast<IntFn>(dlsym(RTLD_DEFAULT, "_ZN6macapk15CocoaPhoneWidthEv"));
    static IntFn hf = reinterpret_cast<IntFn>(dlsym(RTLD_DEFAULT, "_ZN6macapk16CocoaPhoneHeightEv"));
    int ww = wf ? wf() : 0;
    int hh = hf ? hf() : 0;
    if (ww <= 0 || hh <= 0) { ww = 1280; hh = 720; }
    *w = ww; *h = hh;
}
} // namespace

extern "C" MacApkAConfig* __macapk_arm64_AConfiguration_new(void) {
    return new MacApkAConfig();
}
extern "C" void __macapk_arm64_AConfiguration_delete(MacApkAConfig* c) {
    delete c;
}
extern "C" void __macapk_arm64_AConfiguration_fromAssetManager(
        MacApkAConfig* out, void* /*am*/) {
    if (!out) return;
    int w = 0, h = 0;
    macapk_canvas_size(&w, &h);
    out->orientation = (w >= h) ? MACAPK_ACONF_ORIENTATION_LAND
                                : MACAPK_ACONF_ORIENTATION_PORT;
    // dp at xhdpi (320): dp = px * 160 / 320 = px / 2. Canvas points already
    // approximate dp closely enough for layout selection.
    out->screenWidthDp  = w;
    out->screenHeightDp = h;
    out->smallestScreenWidthDp = (w < h) ? w : h;
    int longEdge  = (w > h) ? w : h;
    int shortEdge = (w < h) ? w : h;
    out->screenLong = (shortEdge > 0 && (longEdge * 3) >= (shortEdge * 5))
                          ? MACAPK_ACONF_SCREENLONG_YES : 0;
}
extern "C" void __macapk_arm64_AConfiguration_copy(MacApkAConfig* dest,
                                                   MacApkAConfig* src) {
    if (dest && src) *dest = *src;
}
