extern "C" void __macapk_arm64_AConfiguration_setMcc(MacApkAConfig* c, int32_t v) { if (c) c->mcc = v; }
extern "C" int32_t __macapk_arm64_AConfiguration_getMnc(MacApkAConfig* c) { return c ? c->mnc : 0; }
extern "C" void __macapk_arm64_AConfiguration_setMnc(MacApkAConfig* c, int32_t v) { if (c) c->mnc = v; }
