// diff/match/isBetterThan: apps rarely call these, but provide faithful
// semantics. diff returns a bitmask of changed fields; we report 0 (identical)
// when both sides equal, else a coarse non-zero. match: a config "matches" a
// requested one if every set requested field is compatible -- we return 1
// (compatible) which is the safe default for asset selection.
extern "C" int32_t __macapk_arm64_AConfiguration_diff(MacApkAConfig* a, MacApkAConfig* b) {
    if (!a || !b) return 0;
    return (std::memcmp(a, b, sizeof(MacApkAConfig)) == 0) ? 0 : -1;
}
extern "C" int32_t __macapk_arm64_AConfiguration_match(MacApkAConfig* /*base*/, MacApkAConfig* /*requested*/) {
    return 1;
}
extern "C" int32_t __macapk_arm64_AConfiguration_isBetterThan(MacApkAConfig* /*base*/, MacApkAConfig* /*test*/, MacApkAConfig* /*requested*/) {
    return 0;
}

// Android NDK ALooper_* + AChoreographer_* — PROPER per-thread implementation.
//
// Real Android: each thread can own ONE ALooper (ALooper_prepare). A thread's
// AChoreographer is bound to that thread's looper. ALooper_pollOnce BLOCKS the
// calling thread until an event arrives (an fd is ready, ALooper_wake is called,
// or — for our purposes — a display vsync is delivered to a registered
// AChoreographer frame callback), then runs the ready callbacks ON THE POLLING
// THREAD and returns. This is exactly the contract Unity's frame-pacing
// (Swappy's ChoreographerThread, or any NDK-vsync render loop) relies on: the
// pacing thread does prepare → postFrameCallback → pollOnce(-1) and is woken
// once per real display frame. The previous dummy-buffer stubs returned a
// non-blocking ALOOPER_POLL_TIMEOUT immediately and dropped frame callbacks, so
// a pacing thread either spun or never advanced to its eglSwapBuffers present —
// the multithreaded render pipeline stalled. v1.0.196: real per-thread looper.
// Generic NDK behaviour; no per-APK code.
//
// vsync source: the Cocoa display tick (cocoa_bridge.mm MacapkDriveTickAt →
// __macapk_arm64_choreographer_fire) moves each looper's pending frame
// callbacks to its ready list and wakes its pollOnce, once per display frame.
// MACAPK_VSYNC_THREAD (2026-09-28): that tick runs on the dedicated
// macapk-vsync thread by default, not always the AppKit main thread
// (drawInMTKView) -- see the MacapkVsyncThreadEnabled design comment there.
namespace {
struct MacApkChoreoCb { void* fn; void* data; bool is64; };
// A file descriptor registered with a looper via ALooper_addFd. Unity's native
// vsync/Choreographer thread adds a pipe read-fd here with a callback; the
// looper's pollOnce poll()s these and fires the callback when readable. This is
// how Unity's frame driver actually advances (it uses NEITHER the Java nor NDK
// Choreographer -- it rolls its own pipe + ALooper_addFd vsync receiver).
// is_guest_vaddr (2026-07-28, default false so every EXISTING aggregate-init
// call site -- MacApkFd{fd,ident,events,callback,data} -- is unaffected;
// C++ aggregate init leaves an unlisted trailing member at its default):
// callback/data are real host pointers for an arm64-registered entry
// (Unity), but a 32-bit ARM32 GUEST VADDR stuffed into a void* for an
// ARM32-registered one (ALooper_addFd's ARM32 shim, further down this
// file) -- the dispatcher below must call the two shapes differently, or
// it invokes a small guest integer as if it were a callable host address.
struct MacApkFd { int fd; int ident; int events; void* callback; void* data;
                  bool is_guest_vaddr = false;
                  // Added through __macapk_looper_add_fd_plain (an NDK sensor
                  // or input queue), not a vsync receiver: the busy-pass poll
                  // (__macapk_looper_poll_plain_fds) services only these.
                  bool plain = false; };
struct MacApkLooper {
    std::mutex              mu;
    std::condition_variable cv;
    std::vector<MacApkChoreoCb> pending;  // registered, awaiting next vsync
    std::vector<MacApkChoreoCb> ready;    // vsync fired; run on next pollOnce
    std::vector<MacApkFd> fds;            // ALooper_addFd registrations
    int64_t ready_ft = 0;                   // frame time (ns) for the ready batch
    bool    wake_flag = false;              // ALooper_wake pending
    int     wake_r = -1, wake_w = -1;       // self-pipe to wake a blocked poll
    // True once the thread that OWNS this looper has polled it (pollOnce, the
    // Java loop's native poll, or the main-thread poll). On Android an fd
    // callback runs only on the thread polling its looper, so an owner-polled
    // looper must never be adopted as an orphan by the vsync feeder thread.
    std::atomic<bool> owner_polls{false};
    // Lazily create the wake self-pipe (macOS has no eventfd; a non-blocking
    // self-pipe is the portable equivalent we poll() alongside the looper fds).
    void ensure_wake_pipe() {
        if (wake_r >= 0) return;
        int p[2];
        if (::pipe(p) == 0) {
            for (int f : p) {
                int fl = ::fcntl(f, F_GETFL, 0); ::fcntl(f, F_SETFL, fl | O_NONBLOCK);
                int fd = ::fcntl(f, F_GETFD, 0); ::fcntl(f, F_SETFD, fd | FD_CLOEXEC);
            }
            wake_r = p[0]; wake_w = p[1];
        }
    }
};
thread_local MacApkLooper* t_looper = nullptr;
std::mutex                 g_loopers_mu;
std::vector<MacApkLooper*> g_loopers;     // registry for the vsync broadcast

MacApkLooper* macapk_looper_ensure() {
    if (!t_looper) {
        t_looper = new MacApkLooper();
        t_looper->ensure_wake_pipe();
        std::lock_guard<std::mutex> lk(g_loopers_mu);
        g_loopers.push_back(t_looper);
    }
    return t_looper;
}
void macapk_choreo_register_on(void* inst, void* fn, void* data, bool is64) {
    if (!fn) return;
    MacApkLooper* L = inst ? static_cast<MacApkLooper*>(inst)
                             : macapk_looper_ensure();
    static std::atomic<int> rn{0};
    int c = rn.fetch_add(1);
    if (c < 24) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
        std::fprintf(stderr,
        "[choreo] register #%d cb=%p data=%p is64=%d REGTID=%llu looper=%p\n",
        c, fn, data, is64, (unsigned long long)tid, (void*)L); }
    std::lock_guard<std::mutex> lk(L->mu);
    if (L->pending.size() < 256) L->pending.push_back({fn, data, is64});
}

// --- EXPERIMENTAL Unity native-vsync pump (env-gated MACAPK_UNITY_VSYNC_PUMP) ---
// Unity's frame driver registers a pipe read-fd via ALooper_addFd with a
// callback (a read routine, libunity+0x8a5c0c) + data (the vsync handler,
// libunity+0x8b8b44). On Android a vsync source writes a 24-byte event to the
// pipe each refresh; the looper-owner thread polls it, the callback read()s the
// 24 bytes, then calls handler(buffer) where buffer[0] is the display context.
// On Mac.apk the NDK fd lands on a looper nobody polls (the owner runs the
// Java Looper.loop(), which does not service NDK fds) AND nothing writes the
// pipe -> no frames. FIRST TEST of whether driving the handler advances Unity:
// synthesize the 24-byte event (buffer[0] = the display singleton, derivable
// from the handler address: singleton slot = handler + (0x17280c8 - 0x8b8b44)
// = handler + 0xe6f584) and call the handler ~60Hz from a pump thread.
// Now that the Java<->native Looper is unified, the OWNER thread (UnityMain)
// polls the vsync fd and runs the FD callback on itself. We just need to make
// the pipe readable each display frame by writing the 24-byte event Unity's
// callback expects. buf[0] MUST be the REGISTRAR object (handler 0x8b8b44
// derefs buf[0] as `this`), recovered from Unity's source-struct array at
// [singleton+0xf0] -- entries {singleton@0, write_fd@8, read_fd@0xc,
// registrar@0x10}; the singleton lives at [libunity 0x17280c8] and the libunity
// base = handler - 0x8b8b44. All reads are fault-free (macapk_safe_read_*).
struct MacApkVsyncFeed { int read_fd; void* callback; void* handler; };
// ⚠ INTENTIONALLY LEAKED, and the leak is the fix. macapk_vsync_feeder_thread
// is a DETACHED, infinite-loop thread (Unity vsync workaround) that locks this
// mutex every ~16ms and has no shutdown signal. Closing the window calls
// System.exit(), whose native halt path runs OpenJDK's os::exit() -> libc
// ::exit(), and ::exit() RUNS C++ STATIC DESTRUCTORS -- destroying this mutex
// while the feeder thread is still locking it. The next lock() throws an
// uncaught std::system_error and the process aborts.
//
// MEASURED 2026-08-17, from a real .ips
// (macapk-runtime-2026-08-17-015210.ips, pid-matched):
//   EXC_CRASH / SIGABRT, faulting thread NOT main:
//     std::mutex::lock() <- macapk_feed_vsync_all <- macapk_vsync_feeder_thread
//   and the in-process handler logged: what(): mutex lock failed: Invalid
//   argument -- the canonical EINVAL signature of a DESTROYED pthread mutex.
// Unity-only: Crossy Road reproduces it every time, while Flappy Bird and HCR
// (cocos2d-x, no feeder thread) close cleanly.
//
// Heap-allocating and never deleting removes the destructor entirely, so there
// is nothing to race. The memory is reclaimed by the OS at process exit either
// way -- this costs nothing and is the standard fix for a static whose lifetime
// must outlive every thread that touches it.
//
// ⚠ Other detached watchdog threads in this file share the shape. If one of
// them ever aborts on exit, look here first.
std::mutex& g_vsync_feed_mu = *new std::mutex();
std::vector<MacApkVsyncFeed>& g_vsync_feeds = *new std::vector<MacApkVsyncFeed>();

// Service the vsync fd on the FEEDER thread instead of relying on the looper
// owner to poll it. Unity registers the display vsync fd via ALooper_addFd on a
// looper it obtained from ALooper_forThread (lazy-create, non-NULL), but NO
// thread runs a poll loop on that looper -- the natural owner (UnityMain) is
// blocked in GfxEvent::Wait at render-init, the very wait the vsync callback is
// supposed to release. So the pipe is written but never read, the frame handler
// never runs, GfxEvent::Signal never fires, and render-init deadlocks. Real
// Android drives vsync from a SEPARATE thread (the Choreographer/main thread)
// that is not the one blocked in the gfx present wait, so it fires regardless.
// Mirror that: after writing the 24-byte event, invoke the registered ALooper
// FD read-callback directly here, which read()s the event and runs the frame
// handler. The handler's completion path is a pthread_cond_broadcast (thread-
// agnostic), so running it off the owner thread is safe. Gated for A/B during
// bring-up; once verified it should be the default for any looper-orphaned
// vsync fd (engine-level, gated on the feed existing, never on package name).
static bool vsync_drive_cb_enabled() {
    static int on = -1;
    if (on < 0) on = std::getenv("MACAPK_VSYNC_DRIVE_CB") ? 1 : 0;
    return on != 0;
}

// WRITE one 24-byte vsync event to a Unity native-vsync pipe so its read fd
// becomes readable; the OWNER thread's poll loop (__macapk_looper_run_main_poll)
// then read()s it via Unity's FD callback and runs the frame handler ON THAT
// THREAD. Recover {write_fd, registrar} from Unity's source-struct array at
// [singleton+0xf0] (entries {singleton@0, write_fd@8, read_fd@0xc,
// registrar@0x10}; singleton @[libunity 0x17280c8]; libunity base =
// handler-0x8b8b44). buf[0] MUST be the registrar (the handler derefs it as
// `this`). All guest reads are fault-free.
void macapk_vsync_feed_one(const MacApkVsyncFeed& f, int64_t ft) {
    uintptr_t base = reinterpret_cast<uintptr_t>(f.handler) - 0x8b8b44;
    void* singleton = nullptr;
    if (!macapk_safe_read_ptr(reinterpret_cast<void*>(base + 0x17280c8),
                                &singleton) || !singleton) return;
    void* array = nullptr; uint32_t count = 0;
    if (!macapk_safe_read_ptr(reinterpret_cast<char*>(singleton) + 0xf0,
                                &array) || !array) return;
    if (!macapk_safe_read_u32(reinterpret_cast<char*>(singleton) + 0x100,
                                &count) || count == 0 || count > 64) return;
    for (uint32_t i = 0; i < count; ++i) {
        void* st = nullptr;
        if (!macapk_safe_read_ptr(reinterpret_cast<char*>(array) + i*8, &st)
            || !st) continue;
        uint32_t rfd = 0, wfd = 0; void* registrar = nullptr;
        if (!macapk_safe_read_u32(reinterpret_cast<char*>(st) + 0xc, &rfd)
            || (int)rfd != f.read_fd) continue;
        if (!macapk_safe_read_u32(reinterpret_cast<char*>(st) + 0x8, &wfd)) continue;
        if (!macapk_safe_read_ptr(reinterpret_cast<char*>(st) + 0x10, &registrar)
            || !registrar) continue;
        int64_t buf[3] = { reinterpret_cast<int64_t>(registrar), ft, 0 };
        (void)::write((int)wfd, buf, 24);
        // Drive the frame handler on THIS (feeder) thread by invoking the
        // registered ALooper FD read-callback: cb(fd, ALOOPER_EVENT_INPUT, data)
        // read()s the 24 bytes we just wrote and calls Unity's vsync handler.
        if (vsync_drive_cb_enabled() && f.callback) {
            reinterpret_cast<int(*)(int,int,void*)>(f.callback)(
                f.read_fd, 1 /*ALOOPER_EVENT_INPUT*/, f.handler);
        }
        return;
    }
}
void macapk_feed_vsync_all(int64_t ft) {
    std::vector<MacApkVsyncFeed> feeds;
    { std::lock_guard<std::mutex> lk(g_vsync_feed_mu); feeds = g_vsync_feeds; }
    for (const MacApkVsyncFeed& f : feeds) macapk_vsync_feed_one(f, ft);
}

// ~60Hz vsync source + servicer. Real Android's display hardware writes a vsync
// event into Unity's pipe each refresh and the looper-owner thread polls it;
// Mac.apk has no Android display AND the looper-owner thread (the display-init
// thread) doesn't run a poll loop, so a dedicated thread both FEEDS the pipe
// (writes the 24-byte event) and POLLS the orphan looper (reads it + runs the
// frame handler). buf[0]=registrar gives the handler correct affinity so the
// recursive mutex isn't contended.
extern "C" void __macapk_looper_native_poll(void* looperPtr, int timeoutMs);
MacApkLooper* g_orphan_looper = nullptr;  // looper the vsync fd landed on
std::atomic<bool> g_feeder_started{false};

void* macapk_vsync_feeder_thread(void*) {
    std::fprintf(stderr, "[vsync-thread] feeder+poll thread started\n");
    for (;;) {
        // Feed NANOSECONDS, not raw mach_absolute_time() ticks (24MHz on
        // Apple Silicon). Unity reads this vsync timestamp as Android's
        // frameTimeNanos and derives Time.unscaledDeltaTime from it; ticks
        // made the frame clock advance ~41x too slowly, collapsing
        // unscaledDeltaTime to ~0 so every unscaledDeltaTime-driven UI
        // animation (menus / the age gate) crawled.
        //
        // And feed them on the GUEST's CLOCK_MONOTONIC, not macOS's
        // CLOCK_MONOTONIC_RAW. AOSP guarantees a vsync frameTimeNanos sits in
        // the SAME CLOCK_MONOTONIC epoch as the process's own clock_gettime
        // (NDK choreographer.h; Choreographer.doFrame subtracts frameTimeNanos
        // directly from System.nanoTime()), and our clock_gettime shim hands the
        // guest a REBASED value (~1e10 ns, only under =0 / MACAPK_CLOCK_REBASE=1
        // -- see clock_rebase_enabled) while CLOCK_MONOTONIC_RAW is host uptime
        // (~1e15 ns on a multi-day-up Mac). This vsync feeder only runs at all
        // under MACAPK_SWAPPY_BRIDGE, itself installed only under
        // MACAPK_CHOREO_NANOTIME_BASE=0 -- but that is a DIFFERENT flag from
        // MACAPK_GUEST_CLOCK_NANOTIME (default ON), so the guest clock read here
        // can still be the unrebased default; either way the two callers must
        // agree, which is what this feed does regardless of which arm is active.
        // A consumer differencing consecutive vsyncs cannot tell, but anything
        // computing `now - frameTimeNanos` sees a ~5-order-of-magnitude
        // mismatch -- exactly the defect v1.0.567 root-caused and fixed for the
        // sibling __macapk_arm64_choreographer_fire. (The old note here claiming
        // parity with "the cocoa_bridge choreoFire feeder (v1.0.212)" described
        // that function's PRE-v1.0.567 behaviour and had gone stale.)
        // Cited: docs/unity-android-frametime-deltatime-contract_2026-07-03.md
        struct timespec vts;
        __macapk_arm64_clock_gettime(1 /*CLOCK_MONOTONIC*/, &vts);
        macapk_feed_vsync_all(static_cast<int64_t>(vts.tv_sec) * 1000000000LL
                              + vts.tv_nsec);
        // Poll the orphan only while it IS one: once its owner thread polls it
        // (the main loop, MACAPK_MAIN_NATIVE_POLL), its callbacks belong on that
        // thread -- AGDK's mainWorkCallback uses the main thread's JNIEnv.
        MacApkLooper* L = g_orphan_looper;
        if (L && !L->owner_polls.load(std::memory_order_relaxed))
            __macapk_looper_native_poll(L, 16);
        else usleep(16667);
    }
    return nullptr;
}

void macapk_register_vsync_feed(int read_fd, void* callback, void* data,
                                  MacApkLooper* L) {
    if (!callback || !data || read_fd < 0) return;  // the callback-fd vsync pattern
    { std::lock_guard<std::mutex> lk(g_vsync_feed_mu);
      for (const MacApkVsyncFeed& f : g_vsync_feeds) if (f.read_fd == read_fd) return;
      g_vsync_feeds.push_back({read_fd, callback, data}); }
    g_orphan_looper = L;
    std::fprintf(stderr, "[vsync-feed] registered read_fd=%d cb=%p handler=%p looper=%p\n",
                 read_fd, callback, data, (void*)L);
    if (!g_feeder_started.exchange(true)) {
        pthread_t t; pthread_create(&t, nullptr, macapk_vsync_feeder_thread, nullptr);
        pthread_detach(t);
    }
}
}  // namespace

extern "C" void* __macapk_arm64_ALooper_forThread() {
    // ANDROID-CORRECT semantics (v1.0.199): ALooper_forThread returns the
    // calling thread's looper IFF the thread actually HAS one -- i.e. it called
    // ALooper_prepare (native) OR it is a Java Looper thread that bound its
    // native looper at Looper.prepare (-> NativeLooper.forCurrentThread ->
    // macapk_looper_ensure). It must NOT lazily create a looper for an
    // arbitrary caller. WHY this matters (the bug v1.0.196's lazy-create
    // introduced): Unity's display/vsync setup does
    //   looper = ALooper_forThread();
    //   if (looper == NULL) { spawn a DEDICATED receiver thread (routine
    //       0x8a5ed4) that ALooper_prepare()s its OWN looper and runs the
    //       ALooper_pollOnce loop that services the vsync pipe fd; }
    //   else { assume THIS thread already pumps `looper`, just attach to it; }
    // On a pure-native Unity setup thread, real Android returns NULL here, so
    // Unity spawns the polling receiver. v1.0.196 lazy-created a looper for
    // EVERY caller -> forThread returned non-NULL on that native thread ->
    // Unity took the else-branch -> the vsync fd landed on a looper NOBODY
    // polls (orphan) -> the receiver was never created -> the render-init
    // worker never completes its first frame -> UnityMain blocks forever in the
    // render-init cond_wait (black screen). Returning the genuine t_looper (or
    // NULL) restores the Android branch so Unity builds its own polling
    // receiver. The Java-Looper threads that the v1.0.196 singleton-NULL crash
    // cared about STILL get non-NULL here, because their t_looper was created
    // by Looper.prepare -> NativeLooper.forCurrentThread. Generic; no per-APK
    // code.
    //
    // v1.0.199 NOTE: returning bare t_looper (no create) was tried + REGRESSED.
    // Unity's display init REQUIRES forThread != NULL: its forThread==NULL branch
    // (libunity 0x8a652c) is a dead end that never ALooper_addFd's the vsync
    // pipe (BIND drops 10 -> 0). On Android the display-init thread genuinely
    // owns a looper, so non-NULL is correct; the real gap is that thread not
    // POLLING the looper. Keep lazy-create.
    void* L = macapk_looper_ensure();
    if (macapk_envp("MACAPK_FUTEX_TRACE")) {
        static std::atomic<int> n{0};
        if (n.fetch_add(1) < 16) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
            std::fprintf(stderr, "[looper] ALooper_forThread tid=%llu ra=%p L=%p\n",
                (unsigned long long)tid, __builtin_return_address(0), L); std::fflush(stderr); }
    }
    return L;
}
extern "C" void* __macapk_arm64_ALooper_prepare(int /*opts*/) {
    void* L = macapk_looper_ensure();
    if (macapk_envp("MACAPK_FUTEX_TRACE")) {
        static std::atomic<int> n{0};
        if (n.fetch_add(1) < 16) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
            std::fprintf(stderr, "[looper] ALooper_prepare tid=%llu ra=%p L=%p\n",
                (unsigned long long)tid, __builtin_return_address(0), L); std::fflush(stderr); }
    }
    return L;
}
// Invoke a registered ALooper fd-ready callback correctly for whichever
// tier registered it (2026-07-28 -- honest re-assessment of ALooper_addFd/
// pollOnce/removeFd for ARM32, see docs/arm32-alooper-addfd_2026-07-28.md).
// arm64/Unity's callback is a real host function pointer -- dispatch
// unchanged, the exact pre-existing reinterpret_cast. An ARM32-tagged
// entry's callback/data are 32-bit GUEST VADDRS stuffed into void* by
// __macapk_shim_ALooper_addFd (further down this file): resolve+
// invoke_safe, the SAME host-calls-into-recompiled-ARM32-code primitive
// pthread_once/qsort's macapk_call_guest_compar/__cxa_thread_atexit_impl
// already use daily -- this was the earlier, overly-cautious call: that
// primitive was never the missing piece, only a tier-aware dispatch was.
// Returns the callback's "keep this fd registered" result (matching
// ALooper's own contract: nonzero == keep registered), or 1 (keep) if an
// ARM32 vaddr fails to resolve -- fail open (don't silently drop a
// still-wanted fd over a resolution issue), logged loudly once per
// distinct vaddr.
static int macapk_invoke_fd_callback(const MacApkFd& f, int aev) {
    if (!f.is_guest_vaddr) {
        return reinterpret_cast<int(*)(int,int,void*)>(f.callback)(
            f.fd, aev, f.data);
    }
    uint32_t cb_vaddr = static_cast<uint32_t>(
        reinterpret_cast<uintptr_t>(f.callback));
    uint32_t data_vaddr = static_cast<uint32_t>(
        reinterpret_cast<uintptr_t>(f.data));
    void* host_fn = __macapk_resolve_function(cb_vaddr);
    if (!host_fn) {
        static std::mutex mu;
        static std::unordered_set<uint32_t> logged;
        bool first_time;
        { std::lock_guard<std::mutex> lk(mu);
          first_time = logged.insert(cb_vaddr).second; }
        if (first_time) {
            std::fprintf(stderr,
                "[macapk-shim] CORRECTNESS ALooper fd callback: vaddr=0x%x "
                "could not be resolved -- fd=%d event skipped this time, fd "
                "left registered so a later ready event can retry.\n",
                cb_vaddr, f.fd);
            std::fflush(stderr);
        }
        return 1;
    }
    uint32_t sp = __macapk_alloc_thread_stack();
    return __macapk_invoke_safe(reinterpret_cast<LiftedArmFn>(host_fn),
                                static_cast<uint32_t>(f.fd),
                                static_cast<uint32_t>(aev),
                                data_vaddr, 0, sp);
}
// One bounded pass of ALooper_pollOnce: waits at most 100 ms, whatever the
// caller asked for. __macapk_arm64_ALooper_pollOnce below turns it into the
// NDK contract.
static int macapk_alooper_poll_slice(
        int timeout_ms, int* outFd, int* outEvents, void** outData) {
    if (outFd)     *outFd     = -1;
    if (outEvents) *outEvents = 0;
    if (outData)   *outData   = nullptr;
    MacApkLooper* L = t_looper;
    if (L) L->owner_polls.store(true, std::memory_order_relaxed);
    if (!L) {
        // No looper on this thread: emulate a benign timeout so callers that
        // poll without preparing don't busy-spin.
        if (timeout_ms > 0) usleep((useconds_t)timeout_ms * 1000);
        else if (timeout_ms < 0) usleep(2000);
        return -3; // ALOOPER_POLL_TIMEOUT
    }
    // Snapshot registered fds + consume a pending wake under the lock.
    std::vector<MacApkFd> fds;
    bool woken = false;
    {
        std::lock_guard<std::mutex> lk(L->mu);
        fds = L->fds;
        if (L->wake_flag) { L->wake_flag = false; woken = true; }
    }
    if (woken) return -1; // ALOOPER_POLL_WAKE -- service the wake first

    if (!fds.empty()) {
        // fd-driven looper -- THIS is how Unity's native vsync/Choreographer
        // thread advances: it ALooper_addFd's a pipe read-fd with a callback
        // and blocks here until the fd is readable (a 24-byte vsync event),
        // then the callback read()s it + drives the frame. (Unity uses neither
        // the Java nor the NDK Choreographer; it rolls its own pipe receiver.)
        std::vector<struct pollfd> pfds;
        pfds.reserve(fds.size());
        for (const MacApkFd& f : fds) {
            short ev = 0;
            if (f.events & 1) ev |= POLLIN;   // ALOOPER_EVENT_INPUT
            if (f.events & 2) ev |= POLLOUT;  // ALOOPER_EVENT_OUTPUT
            if (!ev) ev = POLLIN;
            pfds.push_back(pollfd{f.fd, ev, 0});
        }
        // Bound the wait at 100ms so ALooper_wake / fd-removal is seen promptly.
        int to = (timeout_ms < 0) ? 100
               : (timeout_ms == 0) ? 0
               : (timeout_ms > 100 ? 100 : timeout_ms);
        { static std::atomic<int> pn{0}; int c = pn.fetch_add(1);
          if (c < 8) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
            std::fprintf(stderr, "[looper] pollOnce #%d looper=%p tid=%llu "
              "nfds=%zu fd0=%d to=%d\n", c, (void*)L,
              (unsigned long long)tid, pfds.size(),
              pfds.empty()?-1:pfds[0].fd, to); } }
        int r = ::poll(pfds.data(), (nfds_t)pfds.size(), to);
        int ret = -3; // ALOOPER_POLL_TIMEOUT default
        if (r > 0) {
            for (size_t i = 0; i < pfds.size(); ++i) {
                short re = pfds[i].revents;
                if (!re) continue;
                int aev = 0;
                if (re & POLLIN)  aev |= 1;
                if (re & POLLOUT) aev |= 2;
                // ALOOPER_EVENT_ERROR(1<<2), _HANGUP(1<<3) and _INVALID(1<<4) are
                // three INDEPENDENT bits in NDK looper.h; collapsing all three into
                // HANGUP's bit meant `events & ALOOPER_EVENT_ERROR` was false even
                // on a genuine POLLERR, so a caller that retries on ERROR but tears
                // down on HANGUP always took the teardown branch.
                if (re & POLLERR)  aev |= 4;   // ALOOPER_EVENT_ERROR
                if (re & POLLHUP)  aev |= 8;   // ALOOPER_EVENT_HANGUP
                if (re & POLLNVAL) aev |= 16;  // ALOOPER_EVENT_INVALID
                if (!aev) aev = 1;
                const MacApkFd& f = fds[i];
                static std::atomic<int> fc{0};
                int c = fc.fetch_add(1);
                if (c < 12) std::fprintf(stderr,
                    "[looper] fd-ready fd=%d aev=0x%x cb=%p data=%p\n",
                    f.fd, aev, f.callback, f.data);
                if (f.callback) {
                    int keep = macapk_invoke_fd_callback(f, aev);
                    ret = -2; // ALOOPER_POLL_CALLBACK
                    if (keep == 0) {
                        std::lock_guard<std::mutex> lk(L->mu);
                        for (auto it = L->fds.begin(); it != L->fds.end(); ++it)
                            if (it->fd == f.fd) { L->fds.erase(it); break; }
                    }
                } else {
                    if (outFd)     *outFd     = f.fd;
                    if (outEvents) *outEvents = aev;
                    if (outData)   *outData   = f.data;
                    return f.ident; // ident-based fd: pollOnce returns the ident
                }
            }
        }
        // Also drain any AChoreographer ready callbacks for this looper.
        std::vector<MacApkChoreoCb> cbs; int64_t ft = 0;
        { std::lock_guard<std::mutex> lk(L->mu); cbs.swap(L->ready); ft = L->ready_ft; }
        for (const MacApkChoreoCb& c : cbs) {
            if (!c.fn) continue;
            if (c.is64) reinterpret_cast<void(*)(int64_t,void*)>(c.fn)(ft, c.data);
            else        reinterpret_cast<void(*)(long,void*)>(c.fn)((long)ft, c.data);
            ret = -2;
        }
        return ret;
    }

    // No fds: AChoreographer/condvar path.
    std::vector<MacApkChoreoCb> cbs;
    int64_t ft = 0;
    {
        std::unique_lock<std::mutex> lk(L->mu);
        auto have = [&]{ return !L->ready.empty() || L->wake_flag; };
        if (!have()) {
            // Infinite timeout bounded at 100ms as a liveness net (a pacing
            // thread with a registered callback is woken immediately by the
            // vsync notify).
            if (timeout_ms < 0)
                L->cv.wait_for(lk, std::chrono::milliseconds(100), have);
            else if (timeout_ms > 0)
                L->cv.wait_for(lk, std::chrono::milliseconds(timeout_ms), have);
            // timeout_ms == 0: non-blocking peek, fall through
        }
        if (L->wake_flag) { L->wake_flag = false; woken = true; }
        cbs.swap(L->ready);
        ft = L->ready_ft;
    }
    if (!cbs.empty()) {
        // Run frame callbacks ON THIS (the polling) thread, OUTSIDE the lock —
        // Unity's callback re-registers (postFrameCallback) from inside.
        for (const MacApkChoreoCb& c : cbs) {
            if (!c.fn) continue;
            if (c.is64)
                reinterpret_cast<void (*)(int64_t, void*)>(c.fn)(ft, c.data);
            else
                reinterpret_cast<void (*)(long, void*)>(c.fn)(
                    static_cast<long>(ft), c.data);
        }
        return -2; // ALOOPER_POLL_CALLBACK
    }
    if (woken) return -1; // ALOOPER_POLL_WAKE
    return -3; // ALOOPER_POLL_TIMEOUT
}
// MACAPK_LOOPER_FAITHFUL_TIMEOUT (default ON): ALooper_pollOnce returns
// ALOOPER_POLL_TIMEOUT only when the caller's timeout has actually run out.
//
// AOSP Looper::pollOnce (system/core/libutils/Looper.cpp) loops over pollInner
// until something happens: a negative timeout waits forever, a positive one
// until it expires. The slice above caps every wait at 100 ms (so a wake or an
// fd change is seen promptly) and used to hand that cap straight back as
// TIMEOUT, so pollOnce(-1) on an idle looper "timed out" ten times a second.
// Flutter's engine runs each of its threads on fml::MessageLoopAndroid, whose
// Run() is
//     int result = ::ALooper_pollOnce(-1, nullptr, nullptr, nullptr);
//     if (result == ALOOPER_POLL_TIMEOUT || result == ALOOPER_POLL_ERROR)
//       running_ = false;
// i.e. a TIMEOUT from an infinite wait means "the loop was terminated". Its
// raster and io threads go idle right after startup, took that TIMEOUT 100 ms
// later and exited, and nothing was ever drawn: the engine created its EGL
// contexts and never made a window surface (Feeel 2.4.1, Ente Auth). The 100 ms
// slices stay; they are now repeated here until the caller's own timeout ends.
// A thread with no looper keeps the old immediate answer. =0 restores the
// single slice.
static bool macapk_looper_faithful_timeout() {
    static const bool on = [] {
        const char* v = std::getenv("MACAPK_LOOPER_FAITHFUL_TIMEOUT");
        return !(v && v[0] == '0');
    }();
    return on;
}
extern "C" int __macapk_arm64_ALooper_pollOnce(
        int timeout_ms, int* outFd, int* outEvents, void** outData) {
    if (timeout_ms == 0 || !t_looper || !macapk_looper_faithful_timeout())
        return macapk_alooper_poll_slice(timeout_ms, outFd, outEvents, outData);
    const auto t0 = std::chrono::steady_clock::now();
    for (;;) {
        int slice = -1;
        if (timeout_ms > 0) {
            const long long left = timeout_ms - std::chrono::duration_cast<
                std::chrono::milliseconds>(std::chrono::steady_clock::now() - t0).count();
            if (left <= 0) return -3;   // ALOOPER_POLL_TIMEOUT
            slice = static_cast<int>(left);
        }
        const int r = macapk_alooper_poll_slice(slice, outFd, outEvents, outData);
        if (r != -3) return r;
    }
}
extern "C" int __macapk_arm64_ALooper_pollAll(
        int timeout_ms, int* outFd, int* outEvents, void** outData) {
    // pollAll drains ready callbacks then returns; one pollOnce pass is
    // equivalent for our single-callback-source looper.
    return __macapk_arm64_ALooper_pollOnce(timeout_ms, outFd, outEvents, outData);
}
extern "C" int __macapk_arm64_ALooper_addFd(
        void* looper, int fd, int ident, int events,
        void* callback, void* data) {
    MacApkLooper* L = looper ? static_cast<MacApkLooper*>(looper)
                               : t_looper;
    if (!L || fd < 0) return -1;
    static std::atomic<int> an{0};
    int c = an.fetch_add(1);
    if (c < 16) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
        std::fprintf(stderr,
        "[looper] addFd #%d fd=%d ident=%d events=0x%x cb=%p data=%p "
        "TID=%llu looper=%p (t_looper=%p)\n",
        c, fd, ident, events, callback, data,
        (unsigned long long)tid, (void*)L, (void*)t_looper); }
    {
        std::lock_guard<std::mutex> lk(L->mu);
        bool found = false;
        for (MacApkFd& f : L->fds)
            if (f.fd == fd) { f.ident=ident; f.events=events;
                              f.callback=callback; f.data=data; found=true; break; }
        if (!found)
            L->fds.push_back(MacApkFd{fd, ident, events, callback, data});
    }
    // If this is a native-vsync pipe fd (callback-driven), register it so a
    // dedicated thread feeds it each frame + polls THIS looper L (the orphan:
    // the native thread that owns it runs no Java loop), running the callback
    // (Unity render driver) on that thread.
    macapk_register_vsync_feed(fd, callback, data, L);
    return 1; // ALooper_addFd returns 1 on success
}
// ALooper_addFd's registration WITHOUT the vsync-feed hookup above, for
// AInputQueue_attachLooper (bionic_shim_nativeactivity.cpp). The input queue's
// dispatch pipe is an ordinary fd: a callback on it must never be mistaken for
// Unity's vsync receiver, which would start the feeder thread polling this
// looper from a second thread.
extern "C" int __macapk_looper_add_fd_plain(
        void* looper, int fd, int ident, int events, void* callback, void* data) {
    MacApkLooper* L = looper ? static_cast<MacApkLooper*>(looper) : t_looper;
    if (!L || fd < 0) return -1;
    std::lock_guard<std::mutex> lk(L->mu);
    for (MacApkFd& f : L->fds)
        if (f.fd == fd) { f.ident=ident; f.events=events;
                          f.callback=callback; f.data=data; f.plain=true; return 1; }
    L->fds.push_back(MacApkFd{fd, ident, events, callback, data, false, true});
    return 1;
}

// Diagnostics: how many fds this looper holds (bionic_shim_sensors.cpp trace).
extern "C" int __macapk_looper_fd_count(void* looperPtr) {
    MacApkLooper* L = static_cast<MacApkLooper*>(looperPtr);
    if (!L) return -1;
    std::lock_guard<std::mutex> lk(L->mu);
    return static_cast<int>(L->fds.size());
}

// A Java per-thread Looper whose queue is never idle (UnityMain dispatches a
// message every frame) never reaches its blocking native poll, so a callback
// fd on its looper was never serviced: Unity's NDK sensor queue, created on
// UnityMain with a callback, got no events. AOSP MessageQueue.next() calls
// nativePollOnce(ptr, 0) on every pass, busy or not. This is that non-blocking
// poll, narrowed to the PLAIN fds (sensor / input queues): servicing the whole
// looper on every busy pass -- vsync receivers and AChoreographer callbacks
// included -- was measured to crash Temple Run 2 during asset loading
// (2026-10-05), so those keep their existing cadence. Called from
// android.os.Looper.loop() (MACAPK_POLL_FDS_WHEN_BUSY).
extern "C" void __macapk_looper_poll_plain_fds(void* looperPtr) {
    MacApkLooper* L = looperPtr ? static_cast<MacApkLooper*>(looperPtr) : t_looper;
    if (!L) return;
    std::vector<MacApkFd> fds;
    {
        std::lock_guard<std::mutex> lk(L->mu);
        for (const MacApkFd& f : L->fds) if (f.plain && f.callback) fds.push_back(f);
    }
    if (fds.empty()) return;
    std::vector<struct pollfd> pfds;
    for (const MacApkFd& f : fds) pfds.push_back(pollfd{f.fd, POLLIN, 0});
    int pr = ::poll(pfds.data(), (nfds_t)pfds.size(), 0);
    {
        static std::atomic<int> logged{0};
        if (logged.fetch_add(1) < 3)
            std::fprintf(stderr, "[looper] busy-pass poll looper=%p plain-fds=%zu ready=%d\n",
                         (void*)L, fds.size(), pr);
    }
    if (pr <= 0) return;
    for (size_t i = 0; i < pfds.size(); ++i) {
        short re = pfds[i].revents;
        if (!re) continue;
        int aev = 0;
        if (re & POLLIN)   aev |= 1;
        if (re & POLLERR)  aev |= 4;
        if (re & POLLHUP)  aev |= 8;
        if (re & POLLNVAL) aev |= 16;
        if (!aev) aev = 1;
        int keep = macapk_invoke_fd_callback(fds[i], aev);
        {
            static std::atomic<int> logged{0};
            if (logged.fetch_add(1) < 3)
                std::fprintf(stderr, "[looper] busy-pass callback fd=%d cb=%p -> keep=%d\n",
                             fds[i].fd, fds[i].callback, keep);
        }
        if (keep == 0) {
            std::lock_guard<std::mutex> lk(L->mu);
            for (auto it = L->fds.begin(); it != L->fds.end(); ++it)
                if (it->fd == fds[i].fd) { L->fds.erase(it); break; }
        }
    }
}
extern "C" int __macapk_arm64_ALooper_removeFd(void* looper, int fd) {
    MacApkLooper* L = looper ? static_cast<MacApkLooper*>(looper)
                               : t_looper;
    if (!L) return 1;
    std::lock_guard<std::mutex> lk(L->mu);
    for (auto it = L->fds.begin(); it != L->fds.end(); ++it)
        if (it->fd == fd) { L->fds.erase(it); break; }
    return 1;
}
extern "C" void __macapk_arm64_ALooper_acquire(void* /*looper*/) {}
extern "C" void __macapk_arm64_ALooper_release(void* /*looper*/) {}

// ARM32 siblings -- NARROWLY SCOPED (2026-07-28, see
// docs/anativewindow-bridge_2026-07-28.md "IMPORTANT CORRECTION" +
// "Also implemented" sections for the full story). Only the four ALooper
// entry points that involve no guest CALLBACK invocation are bridged here:
// AGDK's GameActivity.cpp (initializeNativeCode_native, fetched from
// github.com/msft-mirror-aosp/platform.frameworks.opt.gamesdk) calls
// ONLY `ALooper_forThread()` and treats a NULL result as FATAL --
// `delete code; return 0;` -- which is why forced-ARM32 Smash Hit's
// onCreate threw "UnsatisfiedLinkError: ... Unable to retrieve native
// ALooper" and never reached the ANativeWindow_fromSurface call this
// session's main fix targets. Fixing exactly that unblocks GameActivity's
// own init without touching the harder problem below.
//
// `ALooper_addFd`/`_pollOnce`/`_pollAll`/`_wake` are DELIBERATELY NOT
// bridged here. `_addFd` stores a raw GUEST CODE ADDRESS as a "callback"
// (bionic_shim.cpp's MacApkFd::callback) that `_pollOnce` later invokes
// with a bare `reinterpret_cast<int(*)(int,int,void*)>(f.callback)(...)`
// (see __macapk_arm64_ALooper_pollOnce above) -- valid on arm64, where a
// guest function IS a real host-callable arm64 function, but WRONG for
// ARM32: a 32-bit ARM32 vaddr is not a callable host function pointer, and
// invoking it as one is undefined behaviour, not a graceful degradation.
// Making that path safe needs the SAME "host calls into recompiled ARM32
// code" indirection RegisterNatives already solved for JNI callbacks
// (macapk_arm32_jni_call_core / the per-method thunk machinery) but applied
// to an arbitrary fd-ready callback instead of a JNI method -- real,
// separate work, out of scope for "get a renderer". Left as an honest,
// unresolved import (panic-stub warning) rather than storing a value nothing
// can safely call yet.
extern "C" uint32_t __macapk_shim_ALooper_forThread(
        uint32_t, uint32_t, uint32_t, uint32_t) {
    void* L = __macapk_arm64_ALooper_forThread();
    return L ? __macapk_jni_make_handle(L) : 0;
}
extern "C" uint32_t __macapk_shim_ALooper_prepare(
        uint32_t opts, uint32_t, uint32_t, uint32_t) {
    // opts is a plain int (ALOOPER_PREPARE_ALLOW_NON_CALLBACKS), not a
    // pointer -- no guest_base translation needed, pass through as-is.
    void* L = __macapk_arm64_ALooper_prepare(static_cast<int>(opts));
    return L ? __macapk_jni_make_handle(L) : 0;
}
extern "C" uint32_t __macapk_shim_ALooper_acquire(
        uint32_t looper_h, uint32_t, uint32_t, uint32_t) {
    __macapk_arm64_ALooper_acquire(__macapk_jni_resolve_handle(looper_h));
    return 0;
}
extern "C" uint32_t __macapk_shim_ALooper_release(
        uint32_t looper_h, uint32_t, uint32_t, uint32_t) {
    __macapk_arm64_ALooper_release(__macapk_jni_resolve_handle(looper_h));
    return 0;
}

// ALooper_addFd/_pollOnce/_removeFd -- 2026-07-28, honest re-assessment
// after being asked directly whether the earlier "needs a new primitive"
// scoping call was right. It was NOT: __macapk_resolve_function +
// __macapk_invoke_safe (used daily by pthread_once/qsort's
// macapk_call_guest_compar/__cxa_thread_atexit_impl) already IS the
// "host calls into recompiled ARM32 code" primitive. What was actually
// missing was making the SHARED MacApkFd/pollOnce dispatch (one process-
// wide MacApkLooper per thread, the same one ALooper_forThread/_prepare's
// ARM32 shims above already hand out a handle to) tell an ARM32 guest
// vaddr apart from an arm64 real pointer -- see MacApkFd::is_guest_vaddr
// and macapk_invoke_fd_callback, both further up this file, for that half.
// Full account: docs/arm32-alooper-addfd_2026-07-28.md.
//
// Deliberately NOT calling macapk_register_vsync_feed from here (unlike
// the arm64 twin, which always does): that is Unity's own heuristic for
// "this looks like a vsync pipe fd," and it invokes its OWN copy of the
// callback via a bare reinterpret_cast on a SEPARATE feeder thread (see
// macapk_vsync_feed_one, gated by MACAPK_VSYNC_DRIVE_CB, default OFF).
// GameActivity apps do not need that mechanism; skipping the call
// entirely sidesteps its raw-pointer invocation rather than needing to
// make a second, independent call site tier-aware too.
//
// ALooper_addFd(looper, fd, ident, events, callback, data) is SIX args:
// r0..r3 = looper,fd,ident,events; [sp+0]=callback, [sp+4]=data (stack-
// spilled per AAPCS32) -- needs kPointerAwareWideImports, not just
// kPointerAwareImports (see the doc for the exact main.cpp diff).
extern "C" uint32_t __macapk_shim_ALooper_addFd(
        uint32_t looper_h, uint32_t fd, uint32_t ident, uint32_t events,
        uint32_t sp) {
    // Inlined stack-arg read, not a call to stack_arg() (defined inside an
    // anonymous namespace further down this file) -- same forward-
    // reference avoidance as strftime_l's inlined read above.
    uint32_t callback_vaddr = 0, data_vaddr = 0;
    if (sp && g_guest_base) {
        std::memcpy(&callback_vaddr, g_guest_base + sp, sizeof(callback_vaddr));
        std::memcpy(&data_vaddr, g_guest_base + sp + 4, sizeof(data_vaddr));
    }
    MacApkLooper* L = looper_h
        ? static_cast<MacApkLooper*>(__macapk_jni_resolve_handle(looper_h))
        : t_looper;
    if (!L || static_cast<int32_t>(fd) < 0) return static_cast<uint32_t>(-1);
    void* callback_as_ptr = reinterpret_cast<void*>(
        static_cast<uintptr_t>(callback_vaddr));
    void* data_as_ptr = reinterpret_cast<void*>(
        static_cast<uintptr_t>(data_vaddr));
    {
        std::lock_guard<std::mutex> lk(L->mu);
        bool found = false;
        for (MacApkFd& f : L->fds)
            if (f.fd == static_cast<int>(fd)) {
                f.ident = static_cast<int>(ident);
                f.events = static_cast<int>(events);
                f.callback = callback_as_ptr;
                f.data = data_as_ptr;
                f.is_guest_vaddr = true;
                found = true;
                break;
            }
        if (!found)
            L->fds.push_back(MacApkFd{static_cast<int>(fd),
                                      static_cast<int>(ident),
                                      static_cast<int>(events),
                                      callback_as_ptr, data_as_ptr, true});
    }
    return 1;  // ALooper_addFd returns 1 on success
}
// pollOnce(timeout_ms, outFd, outEvents, outData) -- fits the regular 4-reg
// shape. Reuses __macapk_arm64_ALooper_pollOnce directly: since
// macapk_invoke_fd_callback (further up this file) already dispatches each
// MacApkFd entry correctly per its own is_guest_vaddr tag, the shared
// function handles a looper with a MIX of arm64- and ARM32-registered fds
// correctly with no ARM32-specific logic duplicated here -- only the
// int*/void** out-params need guest-pointer translation.
extern "C" uint32_t __macapk_shim_ALooper_pollOnce(
        uint32_t timeout_ms, uint32_t outFd_addr, uint32_t outEvents_addr,
        uint32_t outData_addr) {
    int fd = -1, events = 0;
    void* data = nullptr;
    int r = __macapk_arm64_ALooper_pollOnce(static_cast<int>(timeout_ms),
                                            &fd, &events, &data);
    if (outFd_addr) {
        int32_t v = fd;
        std::memcpy(g_guest_base + outFd_addr, &v, sizeof(v));
    }
    if (outEvents_addr) {
        int32_t v = events;
        std::memcpy(g_guest_base + outEvents_addr, &v, sizeof(v));
    }
    if (outData_addr) {
        // The ident-based (no-callback) pollOnce path returns `f.data`
        // verbatim; for an ARM32-tagged entry that is already a 32-bit
        // guest vaddr stuffed into a void*, so extracting the low 32 bits
        // is the exact, correct inverse of __macapk_shim_ALooper_addFd's
        // own packing above.
        uint32_t v = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(data));
        std::memcpy(g_guest_base + outData_addr, &v, sizeof(v));
    }
    return static_cast<uint32_t>(r);
}
extern "C" uint32_t __macapk_shim_ALooper_removeFd(
        uint32_t looper_h, uint32_t fd, uint32_t, uint32_t) {
    MacApkLooper* L = looper_h
        ? static_cast<MacApkLooper*>(__macapk_jni_resolve_handle(looper_h))
        : t_looper;
    if (!L) return 1;
    std::lock_guard<std::mutex> lk(L->mu);
    for (auto it = L->fds.begin(); it != L->fds.end(); ++it)
        if (it->fd == static_cast<int>(fd)) { L->fds.erase(it); break; }
    return 1;
}

// --- Java<->native Looper unification (v1.0.198) -----------------------------
// On real Android a thread's Java Looper and NDK ALooper are the SAME native
// Looper: Looper.loop() -> MessageQueue.next() -> nativePollOnce() ->
// Looper::pollOnce() waits over a wake-fd + the ALooper_addFd fds and runs fd
// callbacks ON THE POLLING THREAD. Mac.apk split them (Java Looper = a
// BlockingQueue; NDK ALooper = MacApkLooper) so the thread that owns Unity's
// native vsync fd never polled it. These entrypoints (called from Java via
// com.macapk.loader.NativeLooper) re-unify them: a per-thread Java
// Looper.loop() blocks in __macapk_looper_native_poll on its OWN
// MacApkLooper (the same object ALooper_forThread()/addFd use), servicing
// native fds + a wake self-pipe; Handler.enqueue calls __macapk_looper_wake.

// Wake a thread blocked in __macapk_looper_native_poll / ALooper_pollOnce.
extern "C" void __macapk_looper_wake(void* looperPtr) {
    MacApkLooper* L = looperPtr ? static_cast<MacApkLooper*>(looperPtr)
                                  : t_looper;
    if (!L) return;
    { std::lock_guard<std::mutex> lk(L->mu); L->wake_flag = true; }
    if (L->wake_w >= 0) { uint8_t b = 1; (void)::write(L->wake_w, &b, 1); }
    L->cv.notify_all();
}

// The calling thread's native looper as a long (created if needed). Same object
// ALooper_forThread()/ALooper_addFd use on this thread, so Unity's vsync fd and
// the Java loop share ONE looper per thread (the Android invariant).
extern "C" long __macapk_looper_for_current_thread() {
    return reinterpret_cast<long>(macapk_looper_ensure());
}

// Block up to timeoutMs (-1 = until an fd event / wake; 0 = peek) polling this
// looper's ALooper fds + its wake self-pipe; run ready fd callbacks ON THIS
// thread. Mirrors android_os_MessageQueue nativePollOnce -> Looper::pollOnce.
extern "C" void __macapk_looper_native_poll(void* looperPtr, int timeoutMs) {
    MacApkLooper* L = looperPtr ? static_cast<MacApkLooper*>(looperPtr)
                                  : t_looper;
    if (!L) { if (timeoutMs > 0) usleep((useconds_t)timeoutMs * 1000);
              else if (timeoutMs < 0) usleep(2000); return; }
    if (L == t_looper) L->owner_polls.store(true, std::memory_order_relaxed);
    L->ensure_wake_pipe();
    std::vector<MacApkFd> fds;
    { std::lock_guard<std::mutex> lk(L->mu); fds = L->fds; L->wake_flag = false; }
    std::vector<struct pollfd> pfds;
    pfds.push_back(pollfd{L->wake_r, POLLIN, 0});       // index 0 = wake pipe
    for (const MacApkFd& f : fds) {
        short ev = 0;
        if (f.events & 1) ev |= POLLIN;
        if (f.events & 2) ev |= POLLOUT;
        if (!ev) ev = POLLIN;
        pfds.push_back(pollfd{f.fd, ev, 0});
    }
    // Honest timeout, but cap an infinite wait at 250ms as a liveness net so a
    // lost wake can't hang a Looper thread forever (bounds quit() latency too).
    int to = (timeoutMs < 0) ? 250 : (timeoutMs > 250 ? 250 : timeoutMs);
    int r = ::poll(pfds.data(), (nfds_t)pfds.size(), to);
    if (std::getenv("MACAPK_LOOPER_POLL_TRACE")) {
        static std::atomic<int> pt{0};
        if (fds.size() >= 1 && pt.fetch_add(1) < 40) {
            char tn[64] = {0}; pthread_getname_np(pthread_self(), tn, sizeof tn);
            std::fprintf(stderr, "[looper] native-poll looper=%p thread=%s nfds=%zu r=%d to=%d fd0=%d rev0=0x%x\n",
                         (void*)L, tn, fds.size(), r, to, fds[0].fd, pfds.size() > 1 ? pfds[1].revents : 0);
        }
    }
    if (r > 0) {
        if (pfds[0].revents & POLLIN) {                 // drain the wake pipe
            uint8_t buf[64];
            while (::read(L->wake_r, buf, sizeof buf) > 0) {}
        }
        for (size_t i = 1; i < pfds.size(); ++i) {
            short re = pfds[i].revents;
            if (!re) continue;
            int aev = 0;
            if (re & POLLIN)  aev |= 1;
            if (re & POLLOUT) aev |= 2;
            // See the ALOOPER_EVENT_* note in ALooper_pollOnce: ERROR/HANGUP/
            // INVALID are three independent bits, not one.
            if (re & POLLERR)  aev |= 4;   // ALOOPER_EVENT_ERROR
            if (re & POLLHUP)  aev |= 8;   // ALOOPER_EVENT_HANGUP
            if (re & POLLNVAL) aev |= 16;  // ALOOPER_EVENT_INVALID
            if (!aev) aev = 1;
            const MacApkFd& f = fds[i - 1];
            static std::atomic<int> fc{0}; int c = fc.fetch_add(1);
            if (c < 12) { uint64_t tid=0; pthread_threadid_np(nullptr,&tid);
                std::fprintf(stderr, "[looper] native-poll fd-ready fd=%d aev=0x%x"
                    " cb=%p data=%p TID=%llu\n", f.fd, aev, f.callback, f.data,
                    (unsigned long long)tid); }
            if (f.callback) {
                int keep = macapk_invoke_fd_callback(f, aev);
                if (keep == 0) {
                    std::lock_guard<std::mutex> lk(L->mu);
                    for (auto it = L->fds.begin(); it != L->fds.end(); ++it)
                        if (it->fd == f.fd) { L->fds.erase(it); break; }
                }
            }
        }
    }
    // Drain any AChoreographer ready callbacks for this looper.
    std::vector<MacApkChoreoCb> cbs; int64_t ft = 0;
    { std::lock_guard<std::mutex> lk(L->mu); cbs.swap(L->ready); ft = L->ready_ft; }
    for (const MacApkChoreoCb& c : cbs) {
        if (!c.fn) continue;
        if (c.is64) reinterpret_cast<void(*)(int64_t,void*)>(c.fn)(ft, c.data);
        else        reinterpret_cast<void(*)(long,void*)>(c.fn)((long)ft, c.data);
    }
}

// Called from the "main"/owner thread's Java Looper.loop() (via
// NativeLooper.runMainPoll). Unity registers its display/gfx pipe fd on the
// JNI_OnLoad/activity thread's native looper, but that thread runs Mac.apk's
// NO-OP MAIN Java loop, so the fd is never serviced AND nativeRender's posted
// gfx work (queued on that looper) deadlocks waiting for a result. If this
// thread's native looper HAS registered fds (i.e. it's the Unity display-looper
// owner), run the poll loop HERE: feed the vsync pipe(s) + native-poll the
// looper, so the FD callbacks (Unity's frame + gfx handlers) run ON THIS thread
// -- the thread Unity created the looper on (correct affinity). Blocks forever
// (the Android main-thread invariant). Returns 0 immediately for a thread with
// NO native fds (non-Unity main thread) so the Java caller keeps its no-op.
extern "C" int __macapk_looper_run_main_poll(void* looperPtr) {
    MacApkLooper* L = looperPtr ? static_cast<MacApkLooper*>(looperPtr)
                                  : t_looper;
    if (!L) return 0;
    { std::lock_guard<std::mutex> lk(L->mu); if (L->fds.empty()) return 0; }
    { uint64_t tid = 0; pthread_threadid_np(nullptr, &tid);
      std::fprintf(stderr,
        "[looper] MAIN owner-thread poll loop START tid=%llu looper=%p\n",
        (unsigned long long)tid, (void*)L); }
    for (;;) {
        // Feed NANOSECONDS, not raw mach_absolute_time() ticks (24MHz on
        // Apple Silicon). Unity reads this vsync timestamp as Android's
        // frameTimeNanos and derives Time.unscaledDeltaTime from it; ticks
        // made the frame clock advance ~41x too slowly, collapsing
        // unscaledDeltaTime to ~0 so every unscaledDeltaTime-driven UI
        // animation (menus / the age gate) crawled.
        //
        // And feed them on the GUEST's CLOCK_MONOTONIC, not macOS's
        // CLOCK_MONOTONIC_RAW. AOSP guarantees a vsync frameTimeNanos sits in
        // the SAME CLOCK_MONOTONIC epoch as the process's own clock_gettime
        // (NDK choreographer.h; Choreographer.doFrame subtracts frameTimeNanos
        // directly from System.nanoTime()), and our clock_gettime shim hands the
        // guest a REBASED value (~1e10 ns, only under =0 / MACAPK_CLOCK_REBASE=1
        // -- see clock_rebase_enabled) while CLOCK_MONOTONIC_RAW is host uptime
        // (~1e15 ns on a multi-day-up Mac). This vsync feeder only runs at all
        // under MACAPK_SWAPPY_BRIDGE, itself installed only under
        // MACAPK_CHOREO_NANOTIME_BASE=0 -- but that is a DIFFERENT flag from
        // MACAPK_GUEST_CLOCK_NANOTIME (default ON), so the guest clock read here
        // can still be the unrebased default; either way the two callers must
        // agree, which is what this feed does regardless of which arm is active.
        // A consumer differencing consecutive vsyncs cannot tell, but anything
        // computing `now - frameTimeNanos` sees a ~5-order-of-magnitude
        // mismatch -- exactly the defect v1.0.567 root-caused and fixed for the
        // sibling __macapk_arm64_choreographer_fire. (The old note here claiming
        // parity with "the cocoa_bridge choreoFire feeder (v1.0.212)" described
        // that function's PRE-v1.0.567 behaviour and had gone stale.)
        // Cited: docs/unity-android-frametime-deltatime-contract_2026-07-03.md
        struct timespec vts;
        __macapk_arm64_clock_gettime(1 /*CLOCK_MONOTONIC*/, &vts);
        macapk_feed_vsync_all(static_cast<int64_t>(vts.tv_sec) * 1000000000LL
                              + vts.tv_nsec);
        __macapk_looper_native_poll(L, 16);
    }
    return 1; // unreachable
}

extern "C" void __macapk_arm64_ALooper_wake(void* looper) {
    __macapk_looper_wake(looper);
}

// Android NDK AChoreographer_* — bound to the CALLING THREAD's looper (above).
// getInstance returns that thread's looper; postFrameCallback registers a
// single-shot frame callback on it that fires on the next display vsync, when
// the thread is woken inside ALooper_pollOnce (or, for the tick thread itself --
// the macapk-vsync thread under MACAPK_VSYNC_THREAD, else the AppKit main thread
// -- via __macapk_arm64_choreographer_run_ready's drain from drawInMTKView, since
// that thread never itself sits in pollOnce). This is what a frame-pacing thread
// (Swappy's ChoreographerThread, or any NDK-vsync render loop) needs to advance
// to its present each frame.
extern "C" void* __macapk_arm64_AChoreographer_getInstance() {
    return macapk_looper_ensure();  // AChoreographer == the calling thread's looper
}
extern "C" void __macapk_arm64_AChoreographer_postFrameCallback(
        void* c, void (*cb)(long, void*), void* data) {
    macapk_choreo_register_on(c, reinterpret_cast<void*>(cb), data, false);
}
extern "C" void __macapk_arm64_AChoreographer_postFrameCallback64(
        void* c, void (*cb)(int64_t, void*), void* data) {
    macapk_choreo_register_on(c, reinterpret_cast<void*>(cb), data, true);
}
extern "C" void __macapk_arm64_AChoreographer_postFrameCallbackDelayed(
        void* c, void (*cb)(long, void*), void* data, long /*delayMs*/) {
    macapk_choreo_register_on(c, reinterpret_cast<void*>(cb), data, false);
}
extern "C" void __macapk_arm64_AChoreographer_postFrameCallbackDelayed64(
        void* c, void (*cb)(int64_t, void*), void* data, long /*delayMs*/) {
    macapk_choreo_register_on(c, reinterpret_cast<void*>(cb), data, true);
}
// Display vsync tick (once per frame, from cocoa_bridge.mm MacapkDriveTickAt --
// see MACAPK_VSYNC_THREAD there for which thread that is). Move every looper's
// pending frame callbacks to its ready list and wake any thread blocked in
// ALooper_pollOnce so it runs them on ITS OWN thread. Callbacks are invoked
// OUTSIDE all looper locks because they re-register (postFrameCallback) from
// inside. The tick thread's OWN looper (if any) does not itself sit in
// pollOnce -- see macapk_choreo_run_ready_on below for how its ready callbacks
// get run instead.
// Run a looper's READY frame callbacks on the calling thread, outside its lock
// (they re-register from inside). The inline half of the display tick below,
// split out 2026-09-28 so the AppKit main thread can still run the callbacks
// registered on its OWN looper when the tick itself runs on the dedicated vsync
// thread (cocoa_bridge.mm MACAPK_VSYNC_THREAD): the main thread never sits in
// pollOnce, so nothing else would run them.
static void macapk_choreo_run_ready_on(MacApkLooper* self, int64_t fallback_ft) {
    std::vector<MacApkChoreoCb> cbs;
    int64_t ft = fallback_ft;
    {
        std::lock_guard<std::mutex> lk(self->mu);
        if (self->ready.empty()) return;
        cbs.swap(self->ready);
        ft = self->ready_ft;
    }
    for (const MacApkChoreoCb& c : cbs) {
        if (!c.fn) continue;
        if (c.is64)
            reinterpret_cast<void (*)(int64_t, void*)>(c.fn)(ft, c.data);
        else
            reinterpret_cast<void (*)(long, void*)>(c.fn)(
                static_cast<long>(ft), c.data);
    }
}
// Exported for drawInMTKView when the vsync thread owns the tick: runs the calling
// thread's (the main thread's) ready AChoreographer callbacks, stamped with the
// vsync that readied them. No looper on this thread = nothing to do.
extern "C" void __macapk_arm64_choreographer_run_ready(void) {
    if (MacApkLooper* self = t_looper) macapk_choreo_run_ready_on(self, 0);
}
extern "C" void __macapk_arm64_choreographer_fire(int64_t /*frameTimeNanos_raw*/) {
    // AOSP FRAME-TIME EPOCH (v1.0.567). AChoreographer's frameTimeNanos MUST be in
    // the SAME CLOCK_MONOTONIC epoch as the guest's clock_gettime(CLOCK_MONOTONIC):
    // AOSP Choreographer.doFrame subtracts them directly (`System.nanoTime() -
    // frameTimeNanos`), and Unity 2020.2+ derives Time.deltaTime from the delta of
    // consecutive PRESENT timestamps in that same base. The caller (cocoa_bridge
    // drawInMTKView) passes macOS CLOCK_MONOTONIC_RAW (~8.8e14 ns, host uptime), but
    // our guest clock_gettime(CLOCK_MONOTONIC) shim returns a REBASED process-
    // relative value (~1e10 ns). The ~5-order-of-magnitude mismatch made every
    // frame's `now - frameTimeNanos` gigantic -> the doFrame resync branch fired
    // every frame, snapping the frame clock forward -> deltaTime jumped far past one
    // refresh period -> the game simulated ~2-3x too much time per frame (the
    // "gameplay too fast" bug). Re-sample the guest's rebased CLOCK_MONOTONIC here so
    // the epoch matches. (Cited: docs/unity-android-frametime-deltatime-contract_2026-07-03.md)
    struct timespec _gts;
    __macapk_arm64_clock_gettime(1 /*CLOCK_MONOTONIC*/, &_gts);
    int64_t frameTimeNanos = (int64_t)_gts.tv_sec * 1000000000LL + _gts.tv_nsec;
    MacApkLooper* self = t_looper;
    size_t moved = 0, nloopers = 0;
    {
        std::lock_guard<std::mutex> glk(g_loopers_mu);
        nloopers = g_loopers.size();
        for (MacApkLooper* L : g_loopers) {
            std::lock_guard<std::mutex> lk(L->mu);
            if (L->pending.empty()) continue;
            moved += L->pending.size();
            for (const MacApkChoreoCb& c : L->pending) L->ready.push_back(c);
            L->pending.clear();
            L->ready_ft = frameTimeNanos;
            L->cv.notify_all();
        }
    }
    // Drive the tick thread's own looper inline (it never calls pollOnce).
    if (self) macapk_choreo_run_ready_on(self, frameTimeNanos);
    static std::atomic<int> firen{0};
    int fc = firen.fetch_add(1);
    if (fc < 8 || (fc % 600) == 0) std::fprintf(stderr,
        "[choreo] fire #%d moved=%zu loopers=%zu\n", fc, moved, nloopers);
}

// ============================================================================
// Swappy (Unity "Optimized Frame Pacing") present bridge.
//
// Unity's render thread (UnityMain) paces frames with Swappy: before each
// frame it blocks in a wait loop (libunity, e.g. +0x6ece88 in Among Us'
// 2022.3.62f3 build):
//     pthread_mutex_lock(M);
//     while (*COUNTER < target) pthread_cond_wait(C, M);   // C = M+0x28
//     pthread_mutex_unlock(M);                              // COUNTER = M+0x58
// where COUNTER is the count of frames that have actually been PRESENTED. On
// Android, Swappy's swap path (SwappyGL_swap, called by the render thread)
// advances COUNTER + broadcasts C after each present. [⚠ REFUTED 2026-09-27:
// no swap path advances COUNTER. Its ONLY writer is Unity's per-vsync
// choreographer handler (Subway libunity 0x71a488 / store 0x71a4d0; Crossy
// 0x898c7c), driven by the Java Choreographer on "UnityChoreographer". This
// bridge is therefore a SECOND writer, and it is not installed by default --
// see macapk_swappy_bridge_enabled. The original text continues:] On Mac.apk the present
// happens on the MAIN thread (MTKView -> AngleEndFrame -> eglSwapBuffers), not
// from the render thread's SwappyGL_swap, so COUNTER never advances and
// UnityMain blocks forever in the pacing wait -> the boot logo renders, then
// the menu scene freezes. We mirror the missing signal: once per real present
// (driven from cocoa_bridge drawInMTKView), bump COUNTER + broadcast C, so the
// render thread is released in step with our vsync'd Metal present. cond_wait
// drops M while waiting, so locking M from the present thread cannot deadlock.
//
// STATUS: GENERIC, zero per-build offsets (v1.0.317). The wait that has to be
// bridged is identified entirely by its Swappy-source-stable STRUCT SHAPE --
// cond == mutex+0x28, presented-counter at mutex+0x58 -- discovered at runtime
// in __macapk_arm64_pthread_cond_wait (which publishes the stuck pacing mutex
// in g_swappy_gen_mutex after it has been re-entered enough times to be the
// pacing loop, with a plausible frame-count at +0x58). This bridge then
// advances that counter + broadcasts the cond on every real Metal present. No
// libunity base lookup, no absolute vaddr, no per-build signature gate: it works
// for every Unity/Swappy build (verified Subway + Among Us). The previous
// hardcoded Among-Us fast-path (mutex +0x12a7710, sig 0x911c4294/0xf943b6d5)
// was deleted here once the generic path was re-verified to cover Among Us.

extern "C" void __macapk_arm64_swappy_present_tick() {
    // MACAPK_SWAPPY_BRIDGE (default: not installed unless
    // MACAPK_CHOREO_NANOTIME_BASE=0) -- see macapk_swappy_bridge_enabled. With it
    // off nothing is ever published, so this is belt and braces for a runtime
    // whose call-site check disagrees.
    if (!macapk_swappy_bridge_enabled()) return;
    if (!g_unity_present.load(std::memory_order_relaxed)) return;
    // The published SwappyCommon mWaitingMutex (M), identified by struct shape in
    // __macapk_arm64_pthread_cond_wait. SwappyCommon field offsets relative to M
    // (RE'd from libunity waitUntil@0xce89c0 / wakeClient@0xce7564 /
    // updateSwapInterval@0xce7f4c, source-confirmed): mCurrentFrameTimestamp
    // @M+0x58 (steady ns), mCurrentFrame @M+0x60 (int32), mAutoSwapIntervalEnabled
    // @M+0xf0 (bool), mAutoSwapInterval @M+0x100 (int32).
    uintptr_t gm = g_swappy_gen_mutex.load(std::memory_order_acquire);
    if (!gm) return;  // no SwappyCommon discovered -> nothing to pace
    // Counter/timestamp offsets were discriminated at publish time (0x58/0x60
    // are order-swapped between builds -- see g_swappy_counter_off).
    int coff  = g_swappy_counter_off.load(std::memory_order_relaxed);
    int tsoff = (coff == 0x58) ? 0x60 : 0x58;
    int32_t*           mtx      = reinterpret_cast<int32_t*>(gm);
    int32_t*           cnd      = reinterpret_cast<int32_t*>(gm + 0x28);
    volatile int64_t*  ts       = reinterpret_cast<volatile int64_t*>(gm + tsoff);
    volatile int32_t*  curFrame = reinterpret_cast<volatile int32_t*>(gm + coff);
    volatile uint8_t*  autoEn   = reinterpret_cast<volatile uint8_t*>(gm + 0xf0);
    volatile int32_t*  autoSwap = reinterpret_cast<volatile int32_t*>(gm + 0x100);
    // SAFETY RE-VERIFY (v1.0.560, generalized v1.0.563). The published address
    // can go STALE: Unity DESTROYS + recreates its SwappyCommon during boot
    // (Among Us: publish saw mCurrentFrame=4103, then it reset to ~75 = a fresh/
    // reused object). Writing our values to a freed-and-reused address SCRIBBLES
    // an unrelated object -> corrupted vtable/pointer -> SIGSEGV (the v559 Among
    // Us regression). So re-check the discriminated structural signature EVERY
    // tick before ANY write; if it no longer holds (the object was freed/reused),
    // UN-PUBLISH so a fresh cond_wait can re-detect the live SwappyCommon, and
    // write nothing this tick. The load-bearing invariant is the SAME shape used
    // at publish: a small non-negative counter, with a plausible monotonic-ns
    // timestamp in the adjacent slot (the auto-swap fields are zero on Subway's
    // global variant, so they cannot be part of the staleness gate).
    // A module GLOBAL never goes stale (static data, never freed) -- sanity-check
    // only the counter. A HEAP SwappyCommon can be freed/reused, so also require
    // its timestamp to still look like a live monotonic-ns value (rejects a reused
    // object before we scribble it). Do NOT ts-gate the global: its timestamp is
    // on the guest clock epoch, not our < 1e14 macOS bound, so ts-gating it would
    // churn (observed: ts=8.8e14 on a 10-day-up host -> endless un-publish).
    //
    // SELF-POISON ESCAPE (v1.0.x). The 1e14 upper bound cannot simply be widened:
    // it is what rejects a reused heap object whose slot now holds a POINTER
    // (macOS arm64 heap addresses start around 0x600000000000 == 1.06e14, just
    // above the bound). But the heap branch below writes macOS CLOCK_MONOTONIC_RAW
    // into this very field, and that exceeds 1e14 once the HOST has been up ~1.16
    // days -- so on any Mac awake longer than ~28 h our own write made the next
    // tick declare the object stale, un-publish it, and re-detect the same
    // still-poisoned value forever: pacing stops advancing and UnityMain's
    // cond_wait blocks for good. Remember the exact value we last wrote and treat
    // a byte-identical read as proof the object is still ours; a freed-and-reused
    // object matching a full 64-bit nanosecond stamp is not a real possibility.
    // (This function has exactly one caller at a time -- MacapkDriveTickAt
    // (cocoa_bridge.mm) holds tick_mu across the whole tick body, and that is
    // the ONLY caller of swappy_present_tick -- so a plain static is enough.
    // Since MACAPK_VSYNC_THREAD (2026-09-28) that caller need not be the main
    // thread any more; the safety here now rests on tick_mu's serialization,
    // not on thread identity.)
    static int64_t s_last_heap_ts_written = 0;
    int in_mod  = g_swappy_in_mod.load(std::memory_order_relaxed);
    int32_t cf  = *curFrame;
    int64_t tv  = *ts;
    uint8_t en  = *autoEn;
    int32_t asi = *autoSwap;
    bool stale = !(cf >= 0 && cf < 0x08000000);
    if (!in_mod)
        stale = stale || !((tv >= 1000000000LL && tv < 100000000000000LL)
                           || (s_last_heap_ts_written != 0
                               && tv == s_last_heap_ts_written));
    if (stale) {
        g_swappy_gen_mutex.store(0, std::memory_order_release);  // un-publish; re-detect
        static std::atomic<int> unp{0};
        if (unp.fetch_add(1) < 8)
            std::fprintf(stderr, "[swappy] un-published stale M=%p "
                "(coff=%#x cf=%d ts=%lld in_mod=%d) -- will re-detect\n",
                (void*)mtx, coff, cf, (long long)tv, in_mod);
        return;
    }
    // THE FIX (v1.0.559). UnityMain's Swappy wait is
    //   waitUntil(mCurrentFrame + mAutoSwapInterval)  ==
    //   `while (mCurrentFrame < target) cond_wait`.
    // Swappy's auto-interval (updateSwapInterval) ratchets mAutoSwapInterval up to
    // ~200 because our MAIN-thread present makes each UnityMain frame LOOK slow
    // (UnityMain is blocked in the wait), a positive feedback loop -> ~0.3fps or a
    // full stall. Root fix: PIN mAutoSwapInterval=1 and DISABLE the ratchet
    // (updateSwapInterval early-returns while mAutoSwapIntervalEnabled==false),
    // then advance the REAL mCurrentFrame counter (@M+0x60) by EXACTLY 1 per real
    // Metal present + refresh the timestamp + broadcast -- mirroring Swappy's own
    // wakeClient. target = mCurrentFrame+1 then clears on the very next present ->
    // UnityMain renders at our full 60fps present rate. Advancing the counter by 1
    // (not jumping it, and NOT bumping the +0x58 timestamp-as-counter -- the old
    // bug that corrupted Swappy's frame-delta and crashed) keeps the bookkeeping
    // consistent. MACAPK_SWAPPY_PIN=0 disables the interval pin (pure +1 pacing)
    // for diagnosis.
    static const bool pin = []{ const char* e = std::getenv("MACAPK_SWAPPY_PIN");
                                return !e || e[0] != '0'; }();
    __macapk_arm64_pthread_mutex_lock(mtx);
    // Pin the auto-swap ratchet ONLY when +0xf0/+0x100 look like a real
    // mAutoSwapIntervalEnabled/mAutoSwapInterval pair (Among-Us-style heap
    // SwappyCommon). Subway's global variant leaves them zero and drives the
    // interval elsewhere, so writing 1 there would scribble an unrelated field;
    // advancing the counter alone paces it.
    if (pin && en <= 1 && asi >= 1 && asi <= 1024) {
        *autoEn   = 0;   // mAutoSwapIntervalEnabled = false (stop the ratchet)
        *autoSwap = 1;   // mAutoSwapInterval = 1 (present every refresh)
    }
    *curFrame = cf + 1;  // ++mCurrentFrame (wakeClient's advance)
    // Refresh mCurrentFrameTimestamp EVERY present. Swappy derives its next-frame
    // target from (now - mCurrentFrameTimestamp); a FROZEN or wrong-epoch ts makes
    // the target outrun our +1/present counter, so UnityMain falls further behind
    // each frame -> very low fps (the Subway symptom: counter advances ~76/s but
    // the target grows faster). For an in-module global (Subway/Fruit/Crossy) the
    // ts is on the GUEST'S CLOCK_MONOTONIC epoch (rebased ~1e10 ns only under
    // =0 / MACAPK_CLOCK_REBASE=1; equal to System.nanoTime()'s clock under the
    // default MACAPK_GUEST_CLOCK_NANOTIME), so write that via
    // __macapk_arm64_clock_gettime -- NOT macOS CLOCK_MONOTONIC_RAW (~1e15,
    // days-large) which would corrupt the float32 frame-delta. A heap SwappyCommon
    // (Among Us) keeps the proven macOS-epoch write.
    if (in_mod) {
        struct timespec gts;
        __macapk_arm64_clock_gettime(1 /*CLOCK_MONOTONIC*/, &gts);
        int64_t now_g = (int64_t)gts.tv_sec * 1000000000LL + gts.tv_nsec;
        // AOSP-FAITHFUL FRAME TIME (v1.0.566). Swappy's next-frame target is
        //   base + round((now - mCurrentFrameTimestamp) / frameDuration).
        // On Android the render thread computes this ONE frame period AFTER the
        // present that set mCurrentFrameTimestamp, so (now - ts) ~= frameDuration
        // -> target = current + 1 -> exactly one rendered frame per vsync (60fps).
        // Our present bridge BROADCASTS the condvar immediately after the write, so
        // UnityMain wakes at the SAME instant -> writing "now" gives (now-ts)~=0 ->
        // target ~= current -> the wait never blocks and the PlayerLoop steps the
        // simulation ~2x per present (the "gameplay too fast" symptom). Reproduce
        // Android's one-frame offset by writing the PREVIOUS present's timestamp,
        // so even an immediate wake sees (now - ts) ~= one present interval.
        static int64_t s_prev_present_g = 0;   // single caller at a time, serialized
                                                // by MacapkDriveTickAt's tick_mu (not
                                                // necessarily the main thread any more,
                                                // see the s_last_heap_ts_written comment
                                                // above)
        int64_t interval = now_g - s_prev_present_g;
        int64_t old_ts = *ts;                  // previous mCurrentFrameTimestamp
        *ts = (s_prev_present_g && interval > 0 && interval < 200000000LL)
                  ? s_prev_present_g              // ~one real present interval ago
                  : (now_g - 16666667LL);         // 1st tick / stall: assume 60fps
        s_prev_present_g = now_g;
        // PREV-TIMESTAMP MAINTENANCE (v1.0.569) -- the "gameplay exactly 2x
        // fast" root cause. Unity 2022.x's statically-linked UnitySwappy
        // derives each frame's PRESENT TIMESTAMP (the value that becomes
        // Time.deltaTime via TimeManager::Update) as
        //   presentTime = M[+0x60]*1e-9 + M[+0x70]
        //                 + (M[+0x60] - M[+0x68])*1e-9 * framesAdvanced
        // (Subway libunity 0x7177e0 reader + 0x6f0324 caller; M[+0x68] =
        // previous tick's timestamp, M[+0x70] = ns->GetTimeSinceStartup-epoch
        // offset, both written ONLY by Swappy's own choreographer handler at
        // 0x717864, which never runs on Mac.apk -- we bridge the counter +
        // condvar instead). [⚠ CORRECTED 2026-09-27: 0x717864 is the ONE-SHOT
        // ENABLE (it logs "Choreographer available: Enabling VSYNC timing" and
        // writes curTs = prevTs = System.nanoTime() and the offset ONCE). The
        // per-vsync writer is 0x71a488: prevTs = old curTs, curTs =
        // frameTimeNanos, ++counter. It DOES run here today, via our Java
        // Choreographer: the counter reads 8-15 before this bridge publishes.
        // Why prevTs read frozen when v1.0.569 measured it is not
        // re-established.] With M[+0x68] frozen at its boot value, the
        // "period" term (M[+0x60]-M[+0x68]) GROWS at 1x the guest clock, so
        // presentTime advances at exactly 2x -> deltaTime == 2 refresh
        // periods (33.3 ms at 60 fps) -> the whole simulation runs 2x fast,
        // invariant to the drive rate (measured live: TimeManager
        // dynamicTime 2.04x wall, smoothDeltaTime 0.0333, frozen prevTs
        // 11.42 s, offset -858886.89). Fix: mirror the handler's bookkeeping
        // -- each tick, the OLD mCurrentFrameTimestamp becomes the previous
        // timestamp, so (cur - prev) == one real present interval and
        // presentTime advances 1x with a correct +period*framesAdvanced
        // catch-up. Layout-gated: only for the RE-verified in-module family
        // with counter@+0x58/ts@+0x60/prevTs@+0x68 (Subway/Fruit shape;
        // Crossy's +0x60-counter variant is untouched), and only when the
        // old value is a plausible monotonic-ns so we never scribble an
        // unrelated field on an unknown layout. The offset@+0x70 is rewritten
        // below for the same reason (epoch consistency; see that comment).
        // RE: docs/unity-swappy-present-time-2x-and-clock-epoch-flip_2026-07-03.md
        if (coff == 0x58 && old_ts > 1000000LL && old_ts < (int64_t)4e15) {
            volatile int64_t* prevTs =
                reinterpret_cast<volatile int64_t*>(gm + 0x68);
            // ⚠ prevTs == curTs, i.e. PERIOD IDENTICALLY ZERO. This used to be
            // `*prevTs = old_ts` (the previous tick's value, so period == one
            // drive tick), and that one value is what made the game's SIMULATION
            // speed change whenever the frame pacer moved the swap interval --
            // the owner's "Subway speeds up and slows down randomly".
            //
            // THE ALGEBRA. Unity reads
            //   presentTime = curTs*1e-9 + offset + (curTs - prevTs)*1e-9 * framesAdvanced
            //                 \_______ base_time _______/   \_ period _/
            // We rewrite `offset = now_g - curTs` every tick, so base_time is the
            // guest-clock NOW of the latest drive tick and advances at the REAL
            // cadence. Per UnityMain frame, framesAdvanced changes by
            // (intervals - ticksElapsed) -- target moves +intervals per frame,
            // the counter +1 per drive tick. Therefore
            //   deltaTime = ticksElapsed*tick + period*(intervals - ticksElapsed)
            // With period == one tick that TELESCOPES to deltaTime == intervals*tick
            // == 16.67 ms identically, at every imposed interval and straight
            // through a hitch: the drift in framesAdvanced exactly cancels the real
            // cadence in base_time. So the pacer would hold the guest at 20 fps
            // while the model still said 16.67 ms, and the sim ran at 1/N speed.
            // With period == 0 the term vanishes and deltaTime == the real elapsed
            // tick time between samples == the actual present cadence.
            //
            // AND ZERO IS WHAT A DEVICE DOES. Unity's own Android choreographer
            // handler (libunity 0x717864, which runs on a device and never here)
            // writes curTs@+0x60 = x19 AND prevTs@+0x68 = x19 -- the SAME tick
            // value, under this mutex -- so a reader can never see them differ.
            // This is a literal transcription of that write, not an invention.
            // [⚠ CORRECTED 2026-09-27: 0x717864 is the one-shot ENABLE, which
            // writes curTs == prevTs exactly once. The per-vsync handler 0x71a488
            // writes prevTs = the OLD curTs, so on a device period == one vsync,
            // not zero. Kept as-is only for MACAPK_SWAPPY_BRIDGE=1.]
            // RE: docs/unity-swappy-present-time-2x-and-clock-epoch-flip_2026-07-03.md
            //
            // v1.0.569 wrote old_ts to fix a "gameplay exactly 2x fast" bug where
            // period had been GROWING; that fixed the growth but left period at
            // one tick instead of the device's zero, which is the residue this
            // closes. Both stores stay inside the existing mutex section, so
            // curTs/prevTs are never seen torn.
            *prevTs = *ts;
            // EPOCH-CONSISTENT OFFSET (v1.0.569, second half of the fix).
            // Swappy's own bookkeeping is in the JAVA System.nanoTime() epoch:
            // its boot-time handler (libunity 0x717864) samples nanoTime via
            // JNI (x19) and writes offset@M+0x70 = GetTimeSinceStartup -
            // x19*1e-9, so presentTime = curTs*1e-9 + offset lands in the
            // GTSS timebase. On the host JVM System.nanoTime() is macOS
            // uptime (~8.6e14 ns). This branch only runs when MACAPK_SWAPPY_BRIDGE
            // installed it, i.e. MACAPK_CHOREO_NANOTIME_BASE=0 -- a DIFFERENT,
            // independently-set flag from MACAPK_GUEST_CLOCK_NANOTIME (default
            // ON), so the guest's clock_gettime read below can be EITHER the
            // rebased (=0 / MACAPK_CLOCK_REBASE=1) or the default unrebased
            // System.nanoTime()-based value; historically (both flags at their
            // old =0 default together) they disagreed, so the boot offset was
            // ~-861,000 s. Once OUR tick writes curTs in the
            // guest clock_gettime epoch (required: Swappy's frame-target
            // formula compares curTs against the guest clock [⚠ CORRECTED
            // 2026-09-27: it does not; the target is lastTarget + round(ratio),
            // Subway 0x6f0324, with no clock compare]), the stale
            // nanoTime-compensating offset makes presentTime ~-861,000 s ->
            // TimeManager's unscaled clock clamps against its boot zeroTime
            // and FREEZES (Time.unscaledTime stuck; the "frozen at 0.738 s"
            // live signature). Fix: keep offset consistent with the epoch WE
            // write -- offset = guest_now_s - curTs*1e-9 -- so presentTime ==
            // guest-clock seconds (small positive, one refresh ahead per the
            // +period*framesAdvanced term), and every field the 0x7177e0
            // reader snapshots is one coherent timebase. One-time transient:
            // at takeover the timebase shifts from GTSS to guest-clock
            // seconds (a few seconds forward during boot); the scaled clock
            // absorbs it in one maximumTimestep-clamped frame and the
            // unscaled clock jumps once, then both advance at 1x.
            volatile double* swoff =
                reinterpret_cast<volatile double*>(gm + 0x70);
            *swoff = (double)now_g * 1e-9 - (double)(*ts) * 1e-9;
        }
    } else {
        // Heap SwappyCommon (Among Us): keeps the proven macOS-epoch write.
        // Record it so the staleness gate above recognises our own value
        // instead of reading it back as an implausible timestamp once host
        // uptime passes 1e14 ns. (Whether this branch should ALSO move to the
        // guest-rebased epoch, the way the in_mod branch did in v1.0.566/567,
        // is a pacing change that needs the protected-app sweep to judge.)
        const int64_t now_raw =
            static_cast<int64_t>(clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW));
        *ts = now_raw;
        s_last_heap_ts_written = now_raw;
    }
    __macapk_arm64_pthread_cond_broadcast(cnd);
    __macapk_arm64_pthread_mutex_unlock(mtx);
    static std::atomic<int> announced{0};
    int an = announced.fetch_add(1);
    if (an == 0) {
        std::fprintf(stderr, "[swappy] SwappyCommon pacing active (M=%p "
            "mCurrentFrame=%d; pinned mAutoSwapInterval=1, auto ratchet disabled)\n",
            (void*)mtx, cf);
        // MACAPK_FAIR_SWAPPY_LATCH (see the big comment above g_fair_boot_over): we are now the
        // guest's frame pacer, so close the MUTEX_FAIR boot window rather than letting its 50ms
        // per-unlock tax fight this bridge for the rest of the 90s. One-way -- a later
        // stale-unpublish must not reopen it.
        __macapk_fair_boot_end("swappy-pacing-active");
    }
    else if ((an % 600) == 0 && macapk_envp("MACAPK_SWAPPY_DIAG"))
        std::fprintf(stderr, "[swappy] pacing tick #%d mCurrentFrame=%d ASI=%d\n",
            an, *curFrame, *autoSwap);
}

// Android NDK ASensor_*: implemented in bionic_shim_sensors.cpp (2026-10-05),
// backed by the Java SensorManager so Tilt Control reaches native games.

// process_vm_readv / process_vm_writev (MACAPK_PROCESS_VM_SELF, default ON, v1.0.1654).
//
// On a device these are REAL syscalls for an app. bionic/libc/SYSCALLS.TXT:354-355
// declares both for "all" arches, and the app seccomp policy is SYSCALLS.TXT minus
// SECCOMP_BLOCKLIST_APP.TXT / SECCOMP_BLOCKLIST_COMMON.TXT, neither of which lists them
// (SECCOMP_BLOCKLIST_APP.TXT:4 states the formula). Kernel contract, torvalds/linux
// mm/process_vm_access.c:
//   * flags != 0                                -> -EINVAL (process_vm_rw, "if (flags != 0)")
//   * an iovec count over UIO_MAXIOV (1024)     -> -EINVAL (import_iovec / iovec_from_user)
//   * an unreadable iovec ARRAY                 -> -EFAULT
//   * nothing to copy on either side            -> 0
//   * no such pid                               -> -ESRCH  (find_get_task_by_vpid)
//   * the copy walks the REMOTE side page by page, and the first unmapped or
//     wrong-protection page stops it; "If we have managed to copy any data at all then
//     we return the number of bytes copied. Otherwise we return the error code"
//     (process_vm_rw_core), the error being -EFAULT. A write pins without FOLL_FORCE,
//     so a read-only target page is -EFAULT too.
//
// The stub this replaces answered -ENOSYS for everything. That is NOT harmless: a caller
// that gets ENOSYS for its OWN pid may fall back to a plain memcpy, and Unity's libunity
// does exactly that (Subway Surfers libunity md5 760a50ab..., +0xc39540: `cmp w8,#38`
// (Linux ENOSYS), `bl getpid; cmp w0,w23`, then memcpy over the remote iovecs). Unity
// uses process_vm_readv as a SAFE read of addresses it is not sure are mapped, so the
// fallback memcpy faults in _platform_memmove on exactly the reads the syscall exists to
// make safe (sweep v1.0.1654: subway REGRESS 0, SIGSEGV at _platform_memmove+0x90 called
// from libunity+0xc39570).
//
// Host rung 1: mach_vm_read_overwrite on mach_task_self() is XNU's fault-free in-task
// copy. It returns KERN_INVALID_ADDRESS / KERN_PROTECTION_FAILURE instead of faulting,
// for a bad SOURCE and for an unmapped or non-writable DESTINATION alike, so the one
// primitive serves both directions (readv: remote -> local, writev: local -> remote).
//
// Scope: only pid == getpid(), the process itself (macOS neuters cross-process task
// ports; docs/inlayer-ptrace-emulation_2026-09-06.md). Any other pid keeps the old
// ENOSYS, so a supervisor that already falls back to ptrace (MACAPK_PTRACE_EMU) sees no
// change. A guest TID of this process is also a valid target on Linux and still gets
// ENOSYS here (open residual). MACAPK_PROCESS_VM_SELF=0 restores the ENOSYS stub for
// every pid. Gate: debug/procvm_gate.sh; note: docs/process-vm-readv-self_2026-09-27.md.
static bool macapk_process_vm_self_on() {
    static const bool on = []{
        const char* e = std::getenv("MACAPK_PROCESS_VM_SELF");
        return !(e && e[0] == '0');
    }();
    return on;
}

namespace {
struct MacapkPvmIov { uintptr_t base; size_t len; };   // struct iovec: {void*, size_t} on both
static_assert(sizeof(MacapkPvmIov) == 16, "Bionic arm64 struct iovec is 16 bytes");
constexpr unsigned long kMacapkUioMaxIov = 1024;        // UIO_MAXIOV, include/uapi/linux/uio.h
constexpr uintptr_t kMacapkGuestPage = 4096;            // the guest's PAGE_SIZE (arm64 Android)

// Fault-free in-task copy of `len` bytes from src to dst. Returns the bytes copied, which
// is `len` unless a page failed. The whole range is tried first; on failure the copy is
// redone one guest page of the REMOTE side at a time, so a partial copy stops at the
// first bad page the way the kernel's per-page loop does.
size_t macapk_pvm_copy(uintptr_t src, uintptr_t dst, size_t len, bool remote_is_src) {
    if (len == 0) return 0;
    mach_vm_size_t out = 0;
    if (mach_vm_read_overwrite(mach_task_self(), (mach_vm_address_t)src, (mach_vm_size_t)len,
                               (mach_vm_address_t)dst, &out) == KERN_SUCCESS && out == len)
        return len;
    size_t done = 0;
    while (done < len) {
        const uintptr_t r = (remote_is_src ? src : dst) + done;
        const size_t chunk = std::min<size_t>(len - done, kMacapkGuestPage - (r % kMacapkGuestPage));
        out = 0;
        if (mach_vm_read_overwrite(mach_task_self(), (mach_vm_address_t)(src + done),
                                   (mach_vm_size_t)chunk, (mach_vm_address_t)(dst + done),
                                   &out) != KERN_SUCCESS || out != chunk)
            break;
        done += chunk;
    }
    return done;
}

// Reads a guest iovec array fault-free and strips Android heap tags from each base.
bool macapk_pvm_read_iov(const void* arr, unsigned long n, std::vector<MacapkPvmIov>& v) {
    v.resize(n);
    if (n == 0) return true;
    const size_t bytes = n * sizeof(MacapkPvmIov);
    if (macapk_pvm_copy((uintptr_t)macapk_untag_ptr(arr), (uintptr_t)v.data(), bytes, true) != bytes)
        return false;
    for (auto& e : v) e.base = (uintptr_t)macapk_untag_ptr((const void*)e.base);
    return true;
}
}  // namespace

static ssize_t macapk_process_vm_rw(pid_t pid, const void* lvec, unsigned long lcnt,
                                    const void* rvec, unsigned long rcnt,
                                    unsigned long flags, bool write, void* lr) {
    if (!macapk_process_vm_self_on() || pid != ::getpid()) { errno = ENOSYS; return -1; }
    if (flags != 0) { errno = EINVAL; return -1; }
    if (lcnt > kMacapkUioMaxIov || rcnt > kMacapkUioMaxIov) { errno = EINVAL; return -1; }
    std::vector<MacapkPvmIov> l, r;
    if (!macapk_pvm_read_iov(lvec, lcnt, l) || !macapk_pvm_read_iov(rvec, rcnt, r)) {
        errno = EFAULT; return -1;
    }
    for (const auto& e : l) if ((ssize_t)e.len < 0) { errno = EINVAL; return -1; }
    for (const auto& e : r) if ((ssize_t)e.len < 0) { errno = EINVAL; return -1; }
    size_t total = 0, j = 0, joff = 0;
    bool fault = false, local_full = false;
    for (size_t i = 0; i < r.size() && !fault && !local_full; ++i) {
        size_t roff = 0;
        while (roff < r[i].len) {
            while (j < l.size() && joff == l[j].len) { ++j; joff = 0; }
            if (j == l.size()) { local_full = true; break; }
            const size_t n = std::min(r[i].len - roff, l[j].len - joff);
            const uintptr_t rem = r[i].base + roff, loc = l[j].base + joff;
            const size_t got = write ? macapk_pvm_copy(loc, rem, n, false)
                                     : macapk_pvm_copy(rem, loc, n, true);
            total += got; roff += got; joff += got;
            if (got < n) { fault = true; break; }
        }
    }
    // MACAPK_PROCESS_VM_TRACE=1: one line per call for the first 64 calls, so a live run
    // shows how often the guest's safe reads hit a hole (each EFAULT/partial below is a
    // read that the ENOSYS stub turned into a faulting memcpy fallback in libunity).
    static const bool trace = []{
        const char* e = std::getenv("MACAPK_PROCESS_VM_TRACE");
        return e && e[0] && e[0] != '0';
    }();
    const ssize_t rv = total ? (ssize_t)total : (fault ? -1 : 0);
    if (trace) {
        // The first 16 calls, every fault (up to 64), and a running total every 4096
        // calls: a guest issuing thousands of 8-byte probes would otherwise hide the rare
        // EFAULT, which is the one that matters.
        static std::atomic<long> n{0}, nfault{0};
        const long k = n.fetch_add(1) + 1;
        long kf = fault ? nfault.fetch_add(1) + 1 : nfault.load();
        if (k <= 16 || (fault && kf <= 64))
            std::fprintf(stderr, "[procvm] #%ld %s lcnt=%lu rcnt=%lu r0=%p len0=%zu -> %zd%s (lr=%p)\n",
                         k, write ? "writev" : "readv", lcnt, rcnt,
                         r.empty() ? nullptr : (void*)r[0].base, r.empty() ? (size_t)0 : r[0].len,
                         rv, (fault && !total) ? " EFAULT" : (fault ? " partial" : ""),
                         lr);
        if (k % 4096 == 0)
            std::fprintf(stderr, "[procvm] total calls=%ld faults=%ld\n", k, kf);
    }
    if (total) return (ssize_t)total;
    if (fault) { errno = EFAULT; return -1; }
    return 0;
}

extern "C" ssize_t __macapk_arm64_process_vm_readv(
        pid_t pid, const void* lvec, unsigned long lcnt,
        const void* rvec, unsigned long rcnt, unsigned long flags) {
    return macapk_process_vm_rw(pid, lvec, lcnt, rvec, rcnt, flags, false, __builtin_return_address(0));
}
extern "C" ssize_t __macapk_arm64_process_vm_writev(
        pid_t pid, const void* lvec, unsigned long lcnt,
        const void* rvec, unsigned long rcnt, unsigned long flags) {
    return macapk_process_vm_rw(pid, lvec, lcnt, rvec, rcnt, flags, true, __builtin_return_address(0));
}

// __gnu_strerror_r: GNU-flavor strerror_r returning char* (not int).
// Bionic exports this for libstdc++ compat. macOS has XSI strerror_r
// returning int; wrap it to GNU signature.
extern "C" char* __macapk_arm64___gnu_strerror_r(
        int errnum, char* buf, size_t buflen) {
    if (buf && buflen > 0) {
        ::strerror_r(errnum, buf, buflen);
        return buf;
    }
    return const_cast<char*>("");
}

// ============================================================================
// libjnigraphics: AndroidBitmap_getInfo / lockPixels / unlockPixels
// ============================================================================
// ---- abm_gate --src: section begins ----
// (debug/abm_gate.sh --src compiles everything between this line and the
// matching "section ends" line ON ITS OWN, against a real JVM, so it must stay
// self-contained: <jni.h>, <mutex>, <vector> and the C/C++ standard headers
// only, nothing else from this file.)
//
// The NDK bitmap API. Guest native code uses it to read or write a Bitmap's
// pixels directly instead of going through Java. Telegram imports all three and
// they were COMPLETELY UNSHIMMED (measured 2026-08-24: 0 hits in this file), so
// every call panic-stubbed -- the silent-zero failure family described in the
// auto-memory. Any app that decodes, blurs, or composites in native code needs
// these, so this is broad, not Telegram-specific.
//
// Contract from AOSP (frameworks/base @ android14-release):
//   native/graphics/jni/bitmap.cpp
//     getInfo  :22-33  BAD_PARAMETER if env/jbitmap null, else fills info, SUCCESS
//     lockPixels :47-65  BAD_PARAMETER if env/jbitmap null; JNI_EXCEPTION if the
//                  pixel address is null (a recycled bitmap is !isValid(), and
//                  ABitmap_getPixels returns null for HARDWARE); else writes
//                  *addrPtr and SUCCESS
//     unlockPixels :67-80  BAD_PARAMETER if env/jbitmap null; JNI_EXCEPTION if
//                  the bitmap is invalid; else notifyPixelsChanged(), SUCCESS
//   libs/hwui/apex/android_bitmap.cpp
//     getFormat :53-56  kN32_SkColorType -> ANDROID_BITMAP_FORMAT_RGBA_8888
//     getAlphaFlags :91-103  kOpaque -> ALPHA_OPAQUE, kPremul -> ALPHA_PREMUL,
//                  kUnpremul -> ALPHA_UNPREMUL
// Result codes and flag values are the NDK's <android/bitmap.h> (ndk 28.2
// sysroot, :43-95): SUCCESS 0, BAD_PARAMETER -1, JNI_EXCEPTION -2,
// ALLOCATION_FAILED -3; ALPHA_PREMUL 0, ALPHA_OPAQUE 1, ALPHA_UNPREMUL 2.
// (BAD_PARAMETER used to be defined here as -3, which is ALLOCATION_FAILED.)
//
// ⚠⚠ THE CONFIG DIVERGENCE, STATED LOUDLY BECAUSE IT IS LOAD-BEARING.
// android/graphics/Bitmap.java's backing store is ALWAYS a full-precision ARGB
// int[] (`argbBuffer`), whatever Config the app asked for -- RGB_565, ARGB_4444
// and ALPHA_8 are all stored as 32-bit ARGB and only narrowed on read. So the
// memory we hand out through lockPixels is genuinely 8888, and getInfo reports
// ANDROID_BITMAP_FORMAT_RGBA_8888 with stride = width*4 to MATCH IT.
//
// That means an app which created an RGB_565 bitmap sees RGBA_8888 from
// getInfo. That is a real divergence from a device, and it is the SAFE
// direction: reporting 565 while handing over 8888 memory would make the app
// walk the buffer at half stride and corrupt every row. An app that reads
// info.format (which is why the field exists) stays correct. An app that
// ASSUMES 565 without reading it gets wrong colours -- loudly wrong, not
// silently corrupt. If this ever needs to be exact, the fix is to give Bitmap a
// real per-Config backing store, not to lie in this struct.
//
// ⚠⚠ THE BYTE ORDER, AND WHY THE GUEST NEVER SEES THE JAVA int[].
// RGBA_8888 on Android is kN32_SkColorType, and Skia's kN32 is RGBA on every
// platform but Windows (external/skia @ android14-release, SkTypes.h:48-56
// "default to RGBA everywhere except BGRA on Windows"; SkColorType.h:58-59).
// So a device's pixel memory is the bytes R,G,B,A per pixel, PREMULTIPLIED for
// the default kPremul bitmap. Our int[] holds straight 0xAARRGGBB, which a
// little-endian host stores as B,G,R,A. Handing that out while getInfo says
// RGBA_8888 swaps red and blue for every native pixel writer and reader.
// MEASURED victim (docs/telegram-chat-wallpaper-pattern_2026-09-25.md):
// Telegram's native generateGradient writes correct device RGBA, and on us
// 43,329 of 224,950 backdrop pixels (19%) had B > 187, a value no mix of its
// four palette colours can reach; swapping R/B put 0% outside the palette box.
//
// So lockPixels hands the guest its OWN buffer in the device layout, converted
// from the int[] (swap, and premultiply when the bitmap is kPremul), and
// unlockPixels merges it back (un-premultiply with Skia's float read pipeline,
// the same arithmetic Bitmap.macapkUnpremul models for getPixel, and swap).
// A pixel the guest did not change keeps its exact Java value, so a lock that
// only READS is lossless, as it is on a device.
// getInfo reports the alpha flags from the same alpha type Bitmap.java models
// (hasAlpha / isPremultiplied), and a fresh bitmap whose int[] was never
// materialized gets its zero-state allocated instead of JNI_EXCEPTION: on a
// device a valid non-HARDWARE bitmap always has pixel memory. Canvas.setBitmap
// seeds its AWT image from that int[] (Canvas.java, "ORDER IS LOAD-BEARING").
// BISECT GATE: MACAPK_ABM_RGBA_BYTES=0 restores the pre-fix answers -- the raw
// ARGB int words, flags 0, JNI_EXCEPTION for a never-materialized bitmap, no
// recycled check, the app's pending exception wiped (and every call made with
// one pending failing), and a Java write made while a lock is held reverted by
// the next unlock. The buffer bookkeeping below (own buffer, shared nested
// locks, no AWT push when nothing changed) is common to both arms.
// Gate: debug/abm_gate.sh (POSITIVE CONTROL: with =0, bytes ff 00 00 ff
// written through lockPixels read back as getPixel 0xff0000ff, not 0xffff0000,
// and the pending-exception and Java-write cases show the pre-fix losses).
// COST, MEASURED on a 1636x3362 (5.5 Mpx) bitmap, lock+unlock (the guest's own
// writes not counted): 4.8 ms read-only, 8.5 ms with every pixel rewritten
// translucent and 7.7 ms opaque, against 3.2 ms for the pre-fix shim that
// converted nothing and 1.4 / 3.2 / 3.2 ms with the gate off. Scale by area; a
// 1000x1000 frame is about a fifth of that.
// NOT DONE: Config.HARDWARE is not refused by lock (a device returns
// JNI_EXCEPTION: ABitmap_getPixels is null for it) and getInfo never sets
// ANDROID_BITMAP_FLAGS_IS_HARDWARE, because that flag steers an app to
// AndroidBitmap_getHardwareBuffer, which is not shimmed.
//
// ⚠ WHAT AOSP GUARANTEES, AND WHERE WE DIFFER. On a device the address IS the
// bitmap's storage: a guest write is visible to Java the instant it lands, and
// a Java write (setPixel, eraseColor, Canvas drawing) is visible to the guest.
// Here there are two copies, the guest's buffer and the Java int[], and they
// are reconciled at every SYNC point -- every unlock, and every lock of a
// bitmap that is already locked -- by a three-way merge that judges the guest
// against what the previous sync left in its buffer (macapk_abm_merge_mode):
//   - a pixel the guest changed takes the guest's value;
//   - a pixel only Java changed keeps Java's value and is re-exported into the
//     guest's buffer, so a later sync cannot revert it. The sync re-reads the
//     bitmap's CURRENT int[] (macapkArgbBuffer re-extracts a Canvas target
//     from its AWT image), so Canvas drawing counts as a Java write;
//   - a pixel both sides changed takes the guest's value (on a device the
//     later write wins, and the order is not knowable here);
//   - an untouched pixel is not written at all.
// <android/bitmap.h>:139-151 says a successful lock must be balanced by an
// unlock, after which the address must no longer be used. An unbalanced lock
// is therefore an app bug; on a device it leaks a ref. Here it also leaks the
// buffer, its `seen` copy and two global refs, and the Java int[] is left
// exactly as it was (never half converted). The guest's writes into it reach
// Java at the next lock or unlock of that bitmap, if one ever comes, and Java
// writes made in between survive that sync.
// Nested locks of one bitmap (any thread) share one buffer and return the same
// address, as on a device; every unlock syncs ("pixels changed"), and the last
// one frees it.
// Nothing is pinned BETWEEN lock and unlock, so the app may call back into Java
// freely while it holds the lock (the reason the old code avoided the critical
// variant). The Java int[] is touched only inside short
// GetPrimitiveArrayCritical windows -- the copy-out in a first lock and the
// merge in a sync -- that make no JNI call and never block, which is that API's
// contract.
//
// ⚠ A PENDING JAVA EXCEPTION IS THE APP'S, AND IT SURVIVES THE CALL. AOSP's
// three entry points make no Java upcall (bitmap.cpp:22-80: a field read and
// native Bitmap calls), so on a device native code can lock, unlock or query a
// bitmap while an exception is pending -- an RAII unlock guard running during
// error cleanup does exactly that -- and the call works and the exception is
// still there afterwards. Ours DO call Java, and HotSpot's GetMethodID returns
// NULL whenever an exception is pending (jdk21u prims/jni.cpp:1092,
// `klass->initialize(CHECK_NULL)`), so every such call failed and the helpers'
// failure path then wiped the app's exception. Each entry point therefore sets
// the pending exception aside for its body and re-throws the SAME object on
// every return (MacapkAbmKeepPending). Found by review; the gate's
// pending-exception case measures it in both arms.

#define MACAPK_ABM_RESULT_SUCCESS        0
#define MACAPK_ABM_RESULT_BAD_PARAMETER  (-1)
#define MACAPK_ABM_RESULT_JNI_EXCEPTION  (-2)
#define MACAPK_ABM_FORMAT_RGBA_8888      1
#define MACAPK_ABM_FLAGS_ALPHA_PREMUL    0u
#define MACAPK_ABM_FLAGS_ALPHA_OPAQUE    1u
#define MACAPK_ABM_FLAGS_ALPHA_UNPREMUL  2u

// The conversion a lock applies. Fixed at the first lock of a bitmap, so lock
// and unlock always agree even if the app flips setPremultiplied() in between.
enum {
    MACAPK_ABM_MODE_RAW    = 0,   // gate off: the pre-fix ARGB int words
    MACAPK_ABM_MODE_SWAP   = 1,   // R<->B only: kOpaque / kUnpremul bitmaps
    MACAPK_ABM_MODE_PREMUL = 2,   // R<->B + premultiply: the default kPremul bitmap
};

static_assert(__BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__,
              "a pixel word 0xAABBGGRR is the bytes R,G,B,A only on a little-endian host");

static bool macapk_abm_rgba_bytes_on() {
    static const bool on = !(std::getenv("MACAPK_ABM_RGBA_BYTES")
                             && std::getenv("MACAPK_ABM_RGBA_BYTES")[0] == '0');
    return on;
}

// MACAPK_ABM_NOTIFY_EVERY_UNLOCK (default ON, v1.0.1653): a successful unlock
// is a "pixels changed" notification whether or not the guest wrote anything --
// jnigraphics bitmap.cpp:78 (android14) calls notifyPixelsChanged() on EVERY
// unlock, so Bitmap.getGenerationId() moves. Our sync only bumped it when it saw
// a changed pixel (macapkCommitArgbToAwt). =0 restores that.
static bool macapk_abm_notify_every_unlock_on() {
    static const bool on = !(std::getenv("MACAPK_ABM_NOTIFY_EVERY_UNLOCK")
                             && std::getenv("MACAPK_ABM_NOTIFY_EVERY_UNLOCK")[0] == '0');
    return on;
}

static int macapk_abm_mode(bool has_alpha, bool premultiplied) {
    return (has_alpha && premultiplied) ? MACAPK_ABM_MODE_PREMUL : MACAPK_ABM_MODE_SWAP;
}

// android_bitmap.cpp getAlphaFlags, over the alpha type Bitmap.java models:
// hasAlpha() is `alphaType != OPAQUE`, isPremultiplied() is `== PREMUL`.
static uint32_t macapk_abm_flags(bool has_alpha, bool premultiplied) {
    if (!has_alpha) return MACAPK_ABM_FLAGS_ALPHA_OPAQUE;
    return premultiplied ? MACAPK_ABM_FLAGS_ALPHA_PREMUL : MACAPK_ABM_FLAGS_ALPHA_UNPREMUL;
}

// The WRITE half of a premultiplied store: Skia's div255_round, bit-for-bit
// Bitmap.macapkMulDiv255Round (see its comment for the Skia citation). An
// exact identity at a == 255 (checked for every c), so it needs no alpha
// branch and the export loop stays vectorizable.
static inline uint32_t macapk_abm_mul_div255_round(uint32_t c, uint32_t a) {
    const uint32_t prod = c * a + 128u;
    return (prod + (prod >> 8)) >> 8;
}

// The READ half: Skia's float raster pipeline (load_8888, unpremul, store_8888
// with ties-to-even), bit-for-bit Bitmap.macapkUnpremul, which is what getPixel
// answers on a device for a premultiplied store. float, not double, on purpose:
// the pipeline is float32 and the Java model measured 354 (a,c) pairs where the
// two disagree. No add appears, so -ffp-contract cannot fuse anything here.
// premul(unpremul(p)) == p for every valid premultiplied p (p <= a), so a pixel
// a nested unlock already folded back is still recognised as unchanged.
static uint32_t macapk_abm_unpremul_one(uint32_t c, uint32_t a) {
    const float av = (float)a * (1.0f / 255.0f);
    float inv = 1.0f / av;
    if (!(inv * 0.0f == 0.0f)) inv = 0.0f;         // Skia's is_finite; a == 0
    float v = ((float)c * (1.0f / 255.0f)) * inv;
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;
    return (uint32_t)std::rint((double)(v * 255.0f));
}
// 64 KB, built once (C++11 guarantees the static's thread-safe init).
struct MacapkAbmUnpremulLut {
    uint8_t v[256][256];                             // [alpha][channel]
    MacapkAbmUnpremulLut() {
        for (uint32_t a = 0; a < 256; ++a)
            for (uint32_t c = 0; c < 256; ++c)
                v[a][c] = (uint8_t)macapk_abm_unpremul_one(c, a);
    }
};
static const MacapkAbmUnpremulLut& macapk_abm_unpremul_lut() {
    static const MacapkAbmUnpremulLut lut;
    return lut;
}

// One Java ARGB int -> the device's pixel word (little-endian bytes R,G,B,A).
// The mode is a template parameter so each per-mode loop below compiles
// branch-free and vectorizes. MEASURED on a 1636x3362 (5.5 Mpx) bitmap, a
// read-only lock+unlock: 17.2 ms with the mode as a per-pixel runtime branch,
// 4.5 ms like this (the pre-fix shim, which converted nothing: 3.2 ms).
template <int kMode>
static inline uint32_t macapk_abm_to_android(uint32_t argb) {
    if constexpr (kMode == MACAPK_ABM_MODE_RAW) {
        return argb;
    } else {
        const uint32_t a = argb >> 24;
        uint32_t r = (argb >> 16) & 0xffu, g = (argb >> 8) & 0xffu, b = argb & 0xffu;
        if constexpr (kMode == MACAPK_ABM_MODE_PREMUL) {
            r = macapk_abm_mul_div255_round(r, a);
            g = macapk_abm_mul_div255_round(g, a);
            b = macapk_abm_mul_div255_round(b, a);
        }
        return (a << 24) | (b << 16) | (g << 8) | r;
    }
}

// One device pixel word -> the straight Java ARGB int getPixel would answer.
// `lut` is fetched ONCE per sync by the caller: going through the
// function-local static per pixel costs a load-acquire of its guard each time
// (MEASURED on 5.5 Mpx of translucent writes: 40 ms that way, 12 ms hoisted,
// before the block cache in macapk_abm_merge_mode halved it again).
template <int kMode>
static inline uint32_t macapk_abm_from_android(uint32_t px, const MacapkAbmUnpremulLut* lut) {
    if constexpr (kMode == MACAPK_ABM_MODE_RAW) {
        return px;
    } else {
        const uint32_t a = px >> 24;
        uint32_t r = px & 0xffu, g = (px >> 8) & 0xffu, b = (px >> 16) & 0xffu;
        if constexpr (kMode == MACAPK_ABM_MODE_PREMUL) {
            if (a != 0xffu) {                        // the LUT is identity at 255
                r = lut->v[a][r];
                g = lut->v[a][g];
                b = lut->v[a][b];
            }
        }
        return (a << 24) | (r << 16) | (g << 8) | b;
    }
}

// The first lock's copy-out. `seen`, when non-null, also receives the exported
// words: the guest's buffer as the first sync will judge it. One pass over the
// Java array for both, since at full-screen size it does not fit in cache.
template <int kMode>
static void macapk_abm_export_mode(const uint32_t* argb, uint32_t* px, uint32_t* seen, size_t n) {
    if (seen) {
        for (size_t i = 0; i < n; ++i) {
            const uint32_t w = macapk_abm_to_android<kMode>(argb[i]);
            seen[i] = w;
            px[i] = w;
        }
    } else {
        for (size_t i = 0; i < n; ++i) px[i] = macapk_abm_to_android<kMode>(argb[i]);
    }
}

// True when a word can be read back through macapk_abm_from_android and
// exported again unchanged. Every word is, for the bijective RAW / SWAP
// conversions; for PREMUL exactly the words with no colour channel above alpha,
// since premul(unpremul(c, a)) == c for every c <= a (checked for all 32,896
// such pairs) and a channel above alpha is not a premultiplied pixel at all.
template <int kMode>
static inline bool macapk_abm_round_trips(uint32_t px) {
    if constexpr (kMode != MACAPK_ABM_MODE_PREMUL) {
        return true;
    } else {
        const uint32_t a = px >> 24;
        return (px & 0xffu) <= a && ((px >> 8) & 0xffu) <= a && ((px >> 16) & 0xffu) <= a;
    }
}

// Did Java change this pixel since the last sync? `w` is the export of its
// Java int now, `s` the guest's word as the last sync left it. A guest word
// that does not round-trip was imported as-is, so its Java value exports to
// the word's canonical form instead of to the word; that is not a Java write.
// The round-trip test runs only once the cheap compare has already failed.
template <int kMode>
static inline bool macapk_abm_java_moved(uint32_t w, uint32_t s, const MacapkAbmUnpremulLut* lut) {
    if (w == s) return false;
    if (macapk_abm_round_trips<kMode>(s)) return true;
    return w != macapk_abm_to_android<kMode>(macapk_abm_from_android<kMode>(s, lut));
}

// THE SYNC: a three-way merge of the guest's buffer `px` and the Java ints
// `argb`, judged against `seen`, the guest's buffer as the previous sync left
// it. Per pixel:
//   the guest changed it (px != seen):            Java takes the guest's value;
//   only Java changed it (export(argb) != seen):  the guest's buffer takes Java's;
//   neither:                                      nothing is written.
// Returns true if the guest changed any pixel (so the int[] was written).
// Judging the guest against what it was LAST GIVEN, not against an export of
// the current Java value, is what lets a Java write made while the lock is held
// survive: the first version of this code compared with the current value,
// saw every such pixel as guest-changed and reverted it to the stale copy.
// A Java change that does not change the export (the colour of a fully
// transparent pixel) needs nothing: the guest's view is already right and the
// int[] is not written.
// An untouched pixel keeps its Java value EXACTLY. Without that a read-only
// lock would push every translucent pixel through the lossy premultiplied
// round trip and zero the colour of every fully transparent one, which the
// int[] deliberately keeps (Bitmap.java: "DELIBERATELY NOT APPLIED TO
// setPixels" -- Java2D's bilinear filter would bleed black in from those
// texels).
// A guest word that does not round-trip (macapk_abm_round_trips: a channel
// above alpha, which a device leaves undefined) keeps its bytes: the next sync
// must not take export(argb) != word for a Java write and overwrite them, which
// is what macapk_abm_java_moved rules out.
// Blocks of 64 are tested with a branch-free OR first, so an untouched region
// costs one vectorized compare, and a block the guest rewrote is imported with
// no export of the pixels it wrote. MEASURED on 5.5 Mpx with every pixel
// rewritten: unlock 6.4 ms translucent / 5.6 ms opaque like this; 9.5 / 8.9 ms
// judged against the Java ints (an export of every pixel), and 7.6 / 7.0 ms
// with the round-trip test on the guest's path instead of the rare one.
// `seen == argb` is the gate-off arm (RAW mode only, where export is the
// identity): Java changes are then invisible and the guest's stale copy wins,
// which is what the pre-fix shim did.
template <int kMode>
static bool macapk_abm_merge_mode(uint32_t* px, uint32_t* argb, uint32_t* seen, size_t n) {
    const MacapkAbmUnpremulLut* lut =
        kMode == MACAPK_ABM_MODE_PREMUL ? &macapk_abm_unpremul_lut() : nullptr;
    bool changed = false;
    uint32_t now[64];                    // export of this block's Java ints
    for (size_t i = 0; i < n; i += 64) {
        const size_t m = std::min<size_t>(64, n - i);
        uint32_t guest = 0;
        for (size_t k = 0; k < m; ++k) guest |= px[i + k] ^ seen[i + k];
        if (guest) {
            for (size_t k = 0; k < m; ++k) {
                const size_t j = i + k;
                if (px[j] != seen[j]) {
                    argb[j] = macapk_abm_from_android<kMode>(px[j], lut);
                    seen[j] = px[j];
                } else {
                    const uint32_t w = macapk_abm_to_android<kMode>(argb[j]);
                    if (macapk_abm_java_moved<kMode>(w, seen[j], lut)) { px[j] = w; seen[j] = w; }
                }
            }
            changed = true;
            continue;
        }
        uint32_t java = 0;
        for (size_t k = 0; k < m; ++k) {
            now[k] = macapk_abm_to_android<kMode>(argb[i + k]);
            java |= now[k] ^ seen[i + k];
        }
        if (!java) continue;
        for (size_t k = 0; k < m; ++k) {
            if (macapk_abm_java_moved<kMode>(now[k], seen[i + k], lut)) {
                px[i + k] = now[k];
                seen[i + k] = now[k];
            }
        }
    }
    return changed;
}

// lockPixels: the Java ints -> the device layout the guest sees (+ `seen`).
static void macapk_abm_export(const uint32_t* argb, uint32_t* px, uint32_t* seen, size_t n,
                              int mode) {
    switch (mode) {
    case MACAPK_ABM_MODE_PREMUL:
        macapk_abm_export_mode<MACAPK_ABM_MODE_PREMUL>(argb, px, seen, n);
        break;
    case MACAPK_ABM_MODE_SWAP:
        macapk_abm_export_mode<MACAPK_ABM_MODE_SWAP>(argb, px, seen, n);
        break;
    default:
        std::memcpy(px, argb, n * sizeof(uint32_t));
        if (seen) std::memcpy(seen, argb, n * sizeof(uint32_t));
        break;
    }
}

// A sync's merge; true if the guest changed any pixel.
static bool macapk_abm_merge(uint32_t* px, uint32_t* argb, uint32_t* seen, size_t n, int mode) {
    switch (mode) {
    case MACAPK_ABM_MODE_PREMUL: return macapk_abm_merge_mode<MACAPK_ABM_MODE_PREMUL>(px, argb, seen, n);
    case MACAPK_ABM_MODE_SWAP:   return macapk_abm_merge_mode<MACAPK_ABM_MODE_SWAP>(px, argb, seen, n);
    default:                     return macapk_abm_merge_mode<MACAPK_ABM_MODE_RAW>(px, argb, seen, n);
    }
}

struct MacapkBitmapLock {
    jobject    bitmap_ref;   // global ref, identity key for unlock
    jintArray  array_ref;    // global ref to the int[] the last sync used
    uint32_t*  pixels;       // what the guest sees: the device layout
    uint32_t*  seen;         // `pixels` as the last sync left it; null when the
                             // gate is off (the merge then uses the int[] itself)
    size_t     java_count;   // ints in the Java array, merged at each sync
    int        mode;         // MACAPK_ABM_MODE_*
    int        refs;         // nested locks of one bitmap share one buffer
};
// Held across the whole of every lock and unlock, including their Java calls:
// macapkArgbBuffer() re-extracts an AWT-backed bitmap's int[] from its image,
// so a lock that ran between another thread's merge and its AWT commit
// would read stale pixels and lose that thread's writes. None of the Java
// methods called here takes a monitor or re-enters this file, and a thread
// blocked on this mutex is in native state, so it cannot stall a safepoint.
static std::mutex                    g_abm_mu;
static std::vector<MacapkBitmapLock> g_abm_locks;

// Call an int-returning no-arg Bitmap method; -1 on any failure.
static int macapk_abm_int_call(JNIEnv* env, jobject bmp, const char* name) {
    jclass c = env->GetObjectClass(bmp);
    if (!c) { env->ExceptionClear(); return -1; }
    jmethodID m = env->GetMethodID(c, name, "()I");
    env->DeleteLocalRef(c);
    if (!m) { env->ExceptionClear(); return -1; }
    jint v = env->CallIntMethod(bmp, m);
    if (env->ExceptionCheck()) { env->ExceptionClear(); return -1; }
    return (int)v;
}

// Call a boolean-returning no-arg Bitmap method; 1 / 0, or -1 on any failure.
static int macapk_abm_bool_call(JNIEnv* env, jobject bmp, const char* name) {
    jclass c = env->GetObjectClass(bmp);
    if (!c) { env->ExceptionClear(); return -1; }
    jmethodID m = env->GetMethodID(c, name, "()Z");
    env->DeleteLocalRef(c);
    if (!m) { env->ExceptionClear(); return -1; }
    jboolean v = env->CallBooleanMethod(bmp, m);
    if (env->ExceptionCheck()) { env->ExceptionClear(); return -1; }
    return v ? 1 : 0;
}

// Bitmap.macapkArgbBuffer(); null on any failure.
static jintArray macapk_abm_argb_buffer(JNIEnv* env, jobject bmp) {
    jclass c = env->GetObjectClass(bmp);
    if (!c) { env->ExceptionClear(); return nullptr; }
    jmethodID m = env->GetMethodID(c, "macapkArgbBuffer", "()[I");
    env->DeleteLocalRef(c);
    if (!m) { env->ExceptionClear(); return nullptr; }
    jobject arr = env->CallObjectMethod(bmp, m);
    if (env->ExceptionCheck()) { env->ExceptionClear(); return nullptr; }
    return (jintArray)arr;
}

// Call a void no-arg Bitmap method (JNI ignores Java access control, so a
// private one is fine), swallowing any failure.
static void macapk_abm_void_call(JNIEnv* env, jobject bmp, const char* name) {
    jclass c = env->GetObjectClass(bmp);
    if (!c) { env->ExceptionClear(); return; }
    jmethodID m = env->GetMethodID(c, name, "()V");
    env->DeleteLocalRef(c);
    if (!m) { env->ExceptionClear(); return; }
    env->CallVoidMethod(bmp, m);
    if (env->ExceptionCheck()) env->ExceptionClear();
}

// Sets the app's pending exception aside for one entry point's body and throws
// the SAME object again on every return (see "A PENDING JAVA EXCEPTION" above).
// Declared before the entry point's lock_guard, so the re-throw happens after
// g_abm_mu is released. Every helper clears the exceptions IT causes, so none
// is pending by the time this runs; the clear is only a backstop, because
// Throw is not on JNI's list of calls allowed with an exception pending.
// Inert with the gate off, which reproduces the pre-fix loss.
struct MacapkAbmKeepPending {
    JNIEnv*    env;
    jthrowable pending;
    explicit MacapkAbmKeepPending(JNIEnv* e) : env(e), pending(nullptr) {
        if (macapk_abm_rgba_bytes_on() && env->ExceptionCheck()) {
            pending = env->ExceptionOccurred();
            env->ExceptionClear();
        }
    }
    ~MacapkAbmKeepPending() {
        if (!pending) return;
        if (env->ExceptionCheck()) env->ExceptionClear();
        env->Throw(pending);
        env->DeleteLocalRef(pending);
    }
    MacapkAbmKeepPending(const MacapkAbmKeepPending&) = delete;
    MacapkAbmKeepPending& operator=(const MacapkAbmKeepPending&) = delete;
};

// Point a lock at the bitmap's CURRENT int[] before a sync. macapkArgbBuffer()
// re-extracts a Canvas target from its AWT image (for which the int[] is a
// derived cache), so Canvas drawing done while the lock is held reaches the
// merge as a Java write, and a same-size int[] that Java swapped in is
// followed. A missing or resized one keeps the array the lock last used.
static void macapk_abm_follow_array(JNIEnv* env, jobject bmp, MacapkBitmapLock& lk) {
    jintArray cur = macapk_abm_argb_buffer(env, bmp);
    if (!cur) return;
    if (!env->IsSameObject(cur, lk.array_ref)
        && (size_t)env->GetArrayLength(cur) == lk.java_count) {
        jintArray g = (jintArray)env->NewGlobalRef(cur);
        if (g) {
            env->DeleteGlobalRef(lk.array_ref);
            lk.array_ref = g;
        }
    }
    env->DeleteLocalRef(cur);
}

// A sync (the "pixels changed" commit, and the catch-up of a nested lock):
// merge the guest's buffer with the Java int[] (macapk_abm_merge_mode). -1 if
// the array could not be reached, else 1 if the guest had changed a pixel (so
// the int[] was written) and 0 if not. The critical window makes no JNI call
// and never blocks, which is the whole contract GetPrimitiveArrayCritical asks
// for; JNI_ABORT skips a write-back when the int[] was not written.
static int macapk_abm_sync(JNIEnv* env, jobject bmp, MacapkBitmapLock& lk) {
    if (lk.seen) macapk_abm_follow_array(env, bmp, lk);
    if (lk.java_count == 0) return 0;
    void* java = env->GetPrimitiveArrayCritical(lk.array_ref, nullptr);
    if (!java) { env->ExceptionClear(); return -1; }
    uint32_t* argb = static_cast<uint32_t*>(java);
    const bool changed = macapk_abm_merge(lk.pixels, argb, lk.seen ? lk.seen : argb,
                                          lk.java_count, lk.mode);
    env->ReleasePrimitiveArrayCritical(lk.array_ref, java, changed ? 0 : JNI_ABORT);
    // AND push the int[] back into the AWT image. For a Canvas-backed bitmap the
    // int[] is a DERIVED CACHE of the BufferedImage, so without this the next
    // macapkExtractArgbFromAwt() overwrites the native writes with stale pixels
    // and the app's work vanishes with no error anywhere. No-op when the bitmap
    // has no AWT backing, which is the common case. Skipped when the int[] was
    // not written: the image already matches, and pushing the int[] would only
    // revert anything Java drew since.
    if (changed) macapk_abm_void_call(env, bmp, "macapkCommitArgbToAwt");
    return changed ? 1 : 0;
}

extern "C" {

typedef struct {
    uint32_t width;
    uint32_t height;
    uint32_t stride;
    int32_t  format;
    uint32_t flags;
} MacapkAndroidBitmapInfo;

int __macapk_arm64_AndroidBitmap_getInfo(JNIEnv* env, jobject jbitmap,
                                         MacapkAndroidBitmapInfo* info) {
    if (!env || !jbitmap) return MACAPK_ABM_RESULT_BAD_PARAMETER;
    MacapkAbmKeepPending keep(env);
    if (!info) return MACAPK_ABM_RESULT_SUCCESS;   // AOSP tolerates a null info
    const int w = macapk_abm_int_call(env, jbitmap, "getWidth");
    const int h = macapk_abm_int_call(env, jbitmap, "getHeight");
    if (w < 0 || h < 0) return MACAPK_ABM_RESULT_JNI_EXCEPTION;
    uint32_t flags = 0;
    if (macapk_abm_rgba_bytes_on()) {
        const int has_alpha = macapk_abm_bool_call(env, jbitmap, "hasAlpha");
        const int premul    = macapk_abm_bool_call(env, jbitmap, "isPremultiplied");
        if (has_alpha < 0 || premul < 0) return MACAPK_ABM_RESULT_JNI_EXCEPTION;
        flags = macapk_abm_flags(has_alpha == 1, premul == 1);
    }
    info->width  = (uint32_t)w;
    info->height = (uint32_t)h;
    info->stride = (uint32_t)w * 4u;               // see the config note above
    info->format = MACAPK_ABM_FORMAT_RGBA_8888;
    info->flags  = flags;
    return MACAPK_ABM_RESULT_SUCCESS;
}

int __macapk_arm64_AndroidBitmap_lockPixels(JNIEnv* env, jobject jbitmap,
                                            void** addrPtr) {
    if (!env || !jbitmap) return MACAPK_ABM_RESULT_BAD_PARAMETER;
    const bool on = macapk_abm_rgba_bytes_on();
    MacapkAbmKeepPending keep(env);
    std::lock_guard<std::mutex> g(g_abm_mu);
    // bitmap.cpp:53: a recycled bitmap is !isValid() -> no address. A probe
    // that cannot answer (-1) also refuses: a lock is allowed to fail.
    if (on && macapk_abm_bool_call(env, jbitmap, "isRecycled") != 0)
        return MACAPK_ABM_RESULT_JNI_EXCEPTION;
    // A nested lock gets the SAME address, as on a device (bitmap.cpp:53 hands
    // out the one pixel store and only takes a ref). It is also a sync point:
    // the buffer catches up with Java writes made since the last one (a pin
    // that was never unlocked would otherwise hand out its lock-time snapshot
    // forever), and Java sees the guest's writes so far.
    for (MacapkBitmapLock& lk : g_abm_locks) {
        if (env->IsSameObject(lk.bitmap_ref, jbitmap)) {
            if (on && macapk_abm_sync(env, jbitmap, lk) < 0)
                return MACAPK_ABM_RESULT_JNI_EXCEPTION;
            ++lk.refs;
            if (addrPtr) *addrPtr = (void*)lk.pixels;
            return MACAPK_ABM_RESULT_SUCCESS;
        }
    }
    int mode = MACAPK_ABM_MODE_RAW;
    if (on) {
        const int has_alpha = macapk_abm_bool_call(env, jbitmap, "hasAlpha");
        const int premul    = macapk_abm_bool_call(env, jbitmap, "isPremultiplied");
        if (has_alpha < 0 || premul < 0) return MACAPK_ABM_RESULT_JNI_EXCEPTION;
        mode = macapk_abm_mode(has_alpha == 1, premul == 1);
    }
    jintArray jarr = macapk_abm_argb_buffer(env, jbitmap);
    if (!jarr && on) {
        // Never materialized (a fresh ARGB_8888 createBitmap: macapkArgbBuffer
        // only builds RGB_565's non-zero zero-state). Allocate the Config's
        // zero-state the way every other writer does, then read it back.
        macapk_abm_void_call(env, jbitmap, "ensureArgbBuffer");
        jarr = macapk_abm_argb_buffer(env, jbitmap);
    }
    if (!jarr) return MACAPK_ABM_RESULT_JNI_EXCEPTION;
    const jsize len = env->GetArrayLength(jarr);
    const size_t jn = len > 0 ? (size_t)len : 0;
    const int w = macapk_abm_int_call(env, jbitmap, "getWidth");
    const int h = macapk_abm_int_call(env, jbitmap, "getHeight");
    // The guest walks height rows of stride = width*4 bytes (getInfo), so the
    // buffer is never smaller than that even if the int[] is.
    size_t count = jn;
    if (w > 0 && h > 0 && (size_t)w * (size_t)h > count) count = (size_t)w * (size_t)h;
    uint32_t* px = (uint32_t*)std::malloc((count ? count : 1) * sizeof(uint32_t));
    // What the first sync judges the guest against (gate on only).
    uint32_t* seen = on ? (uint32_t*)std::malloc((jn ? jn : 1) * sizeof(uint32_t)) : nullptr;
    if (!px || (on && !seen)) {
        std::free(px);
        std::free(seen);
        env->DeleteLocalRef(jarr);
        return MACAPK_ABM_RESULT_JNI_EXCEPTION;
    }
    if (count > jn) std::memset(px + jn, 0, (count - jn) * sizeof(uint32_t));
    if (jn) {
        // Read-only critical window: convert straight out of the Java array.
        void* java = env->GetPrimitiveArrayCritical(jarr, nullptr);
        if (!java) {
            env->ExceptionClear();
            std::free(px);
            std::free(seen);
            env->DeleteLocalRef(jarr);
            return MACAPK_ABM_RESULT_JNI_EXCEPTION;
        }
        macapk_abm_export(static_cast<const uint32_t*>(java), px, seen, jn, mode);
        env->ReleasePrimitiveArrayCritical(jarr, java, JNI_ABORT);
    }
    MacapkBitmapLock lk;
    lk.bitmap_ref = env->NewGlobalRef(jbitmap);
    lk.array_ref  = (jintArray)env->NewGlobalRef(jarr);
    lk.pixels     = px;
    lk.seen       = seen;
    lk.java_count = jn;
    lk.mode       = mode;
    lk.refs       = 1;
    g_abm_locks.push_back(lk);
    env->DeleteLocalRef(jarr);
    if (addrPtr) *addrPtr = (void*)px;
    return MACAPK_ABM_RESULT_SUCCESS;
}

int __macapk_arm64_AndroidBitmap_unlockPixels(JNIEnv* env, jobject jbitmap) {
    if (!env || !jbitmap) return MACAPK_ABM_RESULT_BAD_PARAMETER;
    MacapkAbmKeepPending keep(env);
    std::lock_guard<std::mutex> g(g_abm_mu);
    size_t i = 0;
    for (; i < g_abm_locks.size(); ++i)
        if (env->IsSameObject(g_abm_locks[i].bitmap_ref, jbitmap)) break;
    if (i == g_abm_locks.size()) return MACAPK_ABM_RESULT_JNI_EXCEPTION;
    MacapkBitmapLock& lk = g_abm_locks[i];
    int rc = MACAPK_ABM_RESULT_SUCCESS;
    // `== 1`, not `!= 0`: a probe that cannot answer (-1) must never throw the
    // guest's writes away, which is what it used to do whenever the app had an
    // exception pending.
    if (macapk_abm_rgba_bytes_on() && macapk_abm_bool_call(env, jbitmap, "isRecycled") == 1) {
        // bitmap.cpp:73-75: an invalid (recycled) bitmap is JNI_EXCEPTION and
        // nothing is committed. We still drop our side of the lock.
        rc = MACAPK_ABM_RESULT_JNI_EXCEPTION;
    } else {
        // The sync is the "pixels changed" commit (bitmap.cpp:78): without it a
        // native writer's edits are lost. < 0: the int[] could not be reached.
        const int synced = macapk_abm_sync(env, jbitmap, lk);
        if (synced < 0) {
            rc = MACAPK_ABM_RESULT_JNI_EXCEPTION;
        } else if (synced == 0 && macapk_abm_notify_every_unlock_on()) {
            // Nothing changed, so the sync did not commit -- but a device still
            // notifies (bitmap.cpp:78), and a display list keyed on the
            // generation ID must see this unlock as a modification.
            macapk_abm_void_call(env, jbitmap, "macapkNotifyPixelsChanged");
        }
    }
    if (--lk.refs == 0) {
        const MacapkBitmapLock done = lk;
        g_abm_locks.erase(g_abm_locks.begin() + (long)i);
        env->DeleteGlobalRef(done.array_ref);
        env->DeleteGlobalRef(done.bitmap_ref);
        std::free(done.pixels);
        std::free(done.seen);
    }
    return rc;
}

}  // extern "C"
// ---- abm_gate --src: section ends ----
